import numpy as np
import time
from scipy.optimize import minimize


def _feasible_fix(x):
    """Clamp to square and shrink radii slightly to guarantee exact feasibility."""
    x = np.array(x, dtype=float).reshape(-1, 3)
    x[:, 2] = np.maximum(x[:, 2], 1e-6)
    # clamp centers so circle fits
    x[:, 0] = np.clip(x[:, 0], x[:, 2], 1.0 - x[:, 2])
    x[:, 1] = np.clip(x[:, 1], x[:, 2], 1.0 - x[:, 2])
    # shrink radii to remove overlaps
    n = len(x)
    for _ in range(200):
        bad = False
        for i in range(n):
            for j in range(i + 1, n):
                d = np.hypot(x[i, 0] - x[j, 0], x[i, 1] - x[j, 1])
                s = x[i, 2] + x[j, 2]
                if d < s + 1e-12:
                    bad = True
                    excess = s - d + 1e-9
                    x[i, 2] -= excess / 2
                    x[j, 2] -= excess / 2
        x[:, 2] = np.maximum(x[:, 2], 1e-6)
        x[:, 0] = np.clip(x[:, 0], x[:, 2], 1.0 - x[:, 2])
        x[:, 1] = np.clip(x[:, 1], x[:, 2], 1.0 - x[:, 2])
        if not bad:
            break
    # final safety shrink
    x[:, 2] *= (1.0 - 1e-9)
    x[:, 2] = np.maximum(x[:, 2], 1e-6)
    return x


