    t0 = time.process_time()
    n = 32

    # Hexagonal-ish lattice init, 6 rows
    pts = []
    rows = 6
    for j in range(rows):
        y = (j + 0.5) / rows
        # alternate offset
        cnt = 6 if j % 2 == 0 else 5
        for i in range(cnt):
            if j % 2 == 0:
                x = (i + 0.5) / 6
            else:
                x = (i + 1.0) / 6
            pts.append((x, y))
    pts = pts[:n]
    while len(pts) < n:
        pts.append((0.5, 0.5))
    x0 = np.array([[p[0], p[1], 0.08] for p in pts], dtype=float)

    # If start given, use it if it looks better as init (but keep hex as primary per plan)
    # We'll try hex init; if start provided and better feasible, also consider it.

    # variable vector: [x0,y0,r0, x1,y1,r1, ...]
    def unpack(v):
        return v.reshape(n, 3)

    def obj(v):
        return -np.sum(v[2::3])

    def obj_grad(v):
        g = np.zeros_like(v)
        g[2::3] = -1.0
        return g

    bounds = []
    for i in range(n):
        bounds.append((0.0, 1.0))
        bounds.append((0.0, 1.0))
        bounds.append((1e-4, 0.5))

    # constraints
    cons = []
    # wall constraints: x - r >= 0 -> r - x <= 0 ; 1 - x - r >= 0 -> x + r - 1 <= 0
    for i in range(n):
        def make_wall(i, kind):
            def f(v):
                X = v.reshape(n, 3)
                if kind == 0:
                    return X[i, 0] - X[i, 2]
                elif kind == 1:
                    return 1.0 - X[i, 0] - X[i, 2]
                elif kind == 2:
                    return X[i, 1] - X[i, 2]
                else:
                    return 1.0 - X[i, 1] - X[i, 2]
            return f
        for k in range(4):
            cons.append({'type': 'ineq', 'fun': make_wall(i, k)})

    # pair constraints: (ri+rj)^2 - dist^2 <= 0 -> dist^2 - (ri+rj)^2 >= 0
    for i in range(n):
        for j in range(i + 1, n):
            def make_pair(i, j):
                def f(v):
                    X = v.reshape(n, 3)
                    dx = X[i, 0] - X[j, 0]
                    dy = X[i, 1] - X[j, 1]
                    return dx * dx + dy * dy - (X[i, 2] + X[j, 2]) ** 2
                return f
            cons.append({'type': 'ineq', 'fun': make_pair(i, j)})

    v0 = x0.reshape(-1)

    best = None
    best_score = -1.0

    # Try hex init
    try:
        res = minimize(obj, v0, jac=obj_grad, method='SLSQP',
                       bounds=bounds, constraints=cons,
                       options={'maxiter': 500, 'ftol': 1e-12})
        cand = _feasible_fix(res.x)
        sc = cand[:, 2].sum()
        if sc > best_score:
            best_score = sc
            best = cand
    except Exception:
        pass

    # Also try start as init if time permits
    if start is not None and time.process_time() - t0 < 0.5 * budget_seconds:
        try:
            s = np.asarray(start, dtype=float).reshape(n, 3)
            vs = s.reshape(-1).copy()
            # ensure within bounds
            vs[2::3] = np.clip(vs[2::3], 1e-4, 0.5)
            vs[0::3] = np.clip(vs[0::3], 0.0, 1.0)
            vs[1::3] = np.clip(vs[1::3], 0.0, 1.0)
            res2 = minimize(obj, vs, jac=obj_grad, method='SLSQP',
                            bounds=bounds, constraints=cons,
                            options={'maxiter': 500, 'ftol': 1e-12})
            cand2 = _feasible_fix(res2.x)
            sc2 = cand2[:, 2].sum()
            if sc2 > best_score:
                best_score = sc2
                best = cand2
        except Exception:
            pass

    if best is None:
        if start is not None:
            return _feasible_fix(start)
        return _feasible_fix(x0)

    return best

import numpy as np
import time
from scipy.optimize import minimize, linprog


def _feasible_fix(x):
    """Clamp to square and shrink radii slightly to guarantee exact feasibility."""
    x = np.array(x, dtype=float).reshape(-1, 3)
    x[:, 2] = np.maximum(x[:, 2], 1e-6)
    x[:, 0] = np.clip(x[:, 0], x[:, 2], 1.0 - x[:, 2])
    x[:, 1] = np.clip(x[:, 1], x[:, 2], 1.0 - x[:, 2])
    n = len(x)
    for _ in range(200):
        bad = False
        for i in range(n):
            for j in range(i + 1, n):
                d = np.hypot(x[i, 0] - x[j, 0], x[i, 1] - x[j, 1])
                s = x[i, 2] + x[j, 2]
                if d < s + 1e-12:
                    bad = True
                    excess = s - d + 1e-9
                    x[i, 2] -= excess / 2
                    x[j, 2] -= excess / 2
        x[:, 2] = np.maximum(x[:, 2], 1e-6)
        x[:, 0] = np.clip(x[:, 0], x[:, 2], 1.0 - x[:, 2])
        x[:, 1] = np.clip(x[:, 1], x[:, 2], 1.0 - x[:, 2])
        if not bad:
            break
    x[:, 2] *= (1.0 - 1e-9)
    x[:, 2] = np.maximum(x[:, 2], 1e-6)
    return x


def _total_overlap(centers, r):
    n = len(r)
    tot = 0.0
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(centers[i, 0] - centers[j, 0], centers[i, 1] - centers[j, 1])
            s = r[i] + r[j]
            if d < s:
                tot += (s - d)
    return tot


def _grow_repel(centers, r0, outer_steps, inner_iters, grow):
    """Lubachevsky-Stillinger style grow-and-repel."""
    n = len(r0)
    centers = centers.copy()
    r = np.full(n, r0, dtype=float)
    prev_overlap = _total_overlap(centers, r)
    for _ in range(outer_steps):
        r_new = r * grow
        # repel
        c = centers.copy()
        for _ in range(inner_iters):
            # pairwise separation
            for i in range(n):
                for j in range(i + 1, n):
                    dx = c[j, 0] - c[i, 0]
                    dy = c[j, 1] - c[i, 1]
                    d = np.hypot(dx, dy)
                    s = r_new[i] + r_new[j]
                    if d < s and d > 1e-12:
                        push = 0.5 * (s - d)
                        ux = dx / d
                        uy = dy / d
                        c[i, 0] -= push * ux
                        c[i, 1] -= push * uy
                        c[j, 0] += push * ux
                        c[j, 1] += push * uy
                    elif d <= 1e-12:
                        # random nudge
                        c[j, 0] += 1e-4
                        c[j, 1] += 1e-4
            # walls
            for i in range(n):
                ri = r_new[i]
                if c[i, 0] < ri:
                    c[i, 0] = ri
                elif c[i, 0] > 1.0 - ri:
                    c[i, 0] = 1.0 - ri
                if c[i, 1] < ri:
                    c[i, 1] = ri
                elif c[i, 1] > 1.0 - ri:
                    c[i, 1] = 1.0 - ri
        ov = _total_overlap(c, r_new)
        if ov > prev_overlap + 1e-12:
            # undo growth
            break
        centers = c
        r = r_new
        prev_overlap = ov
        if ov < 1e-9:
            # fully feasible, keep growing
            continue
    return centers, r


def _lp_radii(centers, n):
    """Maximize sum r subject to r_i + r_j <= d_ij and r_i <= wall dist."""
    # variables: r_0..r_{n-1}
    c = -np.ones(n)
    A_ub = []
    b_ub = []
    for i in range(n):
        # wall: r_i <= x_i, r_i <= 1-x_i, r_i <= y_i, r_i <= 1-y_i
        for w in (centers[i, 0], 1.0 - centers[i, 0], centers[i, 1], 1.0 - centers[i, 1]):
            row = np.zeros(n)
            row[i] = 1.0
            A_ub.append(row)
            b_ub.append(max(w, 0.0))
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(centers[i, 0] - centers[j, 0], centers[i, 1] - centers[j, 1])
            row = np.zeros(n)
            row[i] = 1.0
            row[j] = 1.0
            A_ub.append(row)
            b_ub.append(max(d, 0.0))
    bounds = [(1e-6, None)] * n
    try:
        res = linprog(c, A_ub=np.array(A_ub), b_ub=np.array(b_ub),
                      bounds=bounds, method='highs')
        if res.success:
            return np.maximum(res.x, 1e-6)
    except Exception:
        pass
    return None


def _slsqp_polish(x_init, n, maxiter):
    def obj(v):
