                    bad = True
                    excess = s - d + 1e-9
                    x[i, 2] -= excess / 2
                    x[j, 2] -= excess / 2
        x[:, 2] = np.maximum(x[:, 2], 1e-6)
        x[:, 0] = np.clip(x[:, 0], x[:, 2], 1.0 - x[:, 2])
        x[:, 1] = np.clip(x[:, 1], x[:, 2], 1.0 - x[:, 2])
        if not bad:
            break
    x[:, 2] *= (1.0 - 1e-9)
    x[:, 2] = np.maximum(x[:, 2], 1e-6)
    return x


def _lp_radius_fix(x, n):
    """Given centers, solve for radii maximizing sum subject to wall + pair constraints.
    Use a simple iterative projection / LP-like scaling via scipy linprog if available,
    else fall back to greedy shrink. Here we use scipy.optimize.linprog."""
    try:
        from scipy.optimize import linprog
    except Exception:
        return x
    x = np.array(x, dtype=float).reshape(n, 3)
    cx = x[:, 0].copy()
    cy = x[:, 1].copy()
    # variables: r_0..r_{n-1} >= 0
    # maximize sum r -> minimize -sum r
    c = -np.ones(n)
    A_ub = []
    b_ub = []
    # wall: r_i <= cx_i, r_i <= 1-cx_i, r_i <= cy_i, r_i <= 1-cy_i
    for i in range(n):
        for w in (cx[i], 1.0 - cx[i], cy[i], 1.0 - cy[i]):
            row = np.zeros(n)
            row[i] = 1.0
            A_ub.append(row)
            b_ub.append(max(w, 0.0))
    # pair: r_i + r_j <= dist
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(cx[i] - cx[j], cy[i] - cy[j])
            row = np.zeros(n)
            row[i] = 1.0
            row[j] = 1.0
            A_ub.append(row)
            b_ub.append(d)
    try:
        res = linprog(c, A_ub=np.array(A_ub), b_ub=np.array(b_ub),
                      bounds=[(0, None)] * n, method='highs')
        if res.success:
            r = res.x
            out = np.column_stack([cx, cy, r])
            return out
    except Exception:
        pass
    return x


def _make_lattice(rows, phase, n):
    pts = []
    for j in range(rows):
        y = (j + 0.5) / rows
        cnt = int(np.ceil(n / rows)) + 1
        for i in range(cnt):
            x = (i + 0.5 + phase) / cnt
            if 0.0 <= x <= 1.0:
                pts.append((x, y))
    # trim / pad
    pts = pts[:n]
    while len(pts) < n:
        pts.append((0.5, 0.5))
    return np.array([[p[0], p[1], 0.08] for p in pts], dtype=float)


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 32
    rng = np.random.default_rng(12345)

    def unpack(v):
        return v.reshape(n, 3)

    def obj(v):
        return -np.sum(v[2::3])

    def obj_grad(v):
        g = np.zeros_like(v)
        g[2::3] = -1.0
        return g

    bounds = []
    for i in range(n):
        bounds.append((0.0, 1.0))
        bounds.append((0.0, 1.0))
        bounds.append((1e-4, 0.5))

    cons = []
    for i in range(n):
        def make_wall(i, kind):
            def f(v):
                X = v.reshape(n, 3)
                if kind == 0:
                    return X[i, 0] - X[i, 2]
                elif kind == 1:
                    return 1.0 - X[i, 0] - X[i, 2]
                elif kind == 2:
                    return X[i, 1] - X[i, 2]
                else:
                    return 1.0 - X[i, 1] - X[i, 2]
            return f
        for k in range(4):
            cons.append({'type': 'ineq', 'fun': make_wall(i, k)})

    for i in range(n):
        for j in range(i + 1, n):
            def make_pair(i, j):
                def f(v):
                    X = v.reshape(n, 3)
                    dx = X[i, 0] - X[j, 0]
                    dy = X[i, 1] - X[j, 1]
                    return dx * dx + dy * dy - (X[i, 2] + X[j, 2]) ** 2
                return f
            cons.append({'type': 'ineq', 'fun': make_pair(i, j)})

    best = None
    best_score = -1.0

    def try_init(x_init, maxiter=200):
        nonlocal best, best_score
        if time.process_time() - t0 > 0.85 * budget_seconds:
            return
        v0 = np.array(x_init, dtype=float).reshape(-1).copy()
        v0[2::3] = np.clip(v0[2::3], 1e-4, 0.5)
        v0[0::3] = np.clip(v0[0::3], 0.0, 1.0)
        v0[1::3] = np.clip(v0[1::3], 0.0, 1.0)
        try:
            res = minimize(obj, v0, jac=obj_grad, method='SLSQP',
                           bounds=bounds, constraints=cons,
                           options={'maxiter': maxiter, 'ftol': 1e-10})
            cand = _feasible_fix(res.x)
            # LP radius fix on centers
            lp = _lp_radius_fix(cand, n)
            lp = _feasible_fix(lp)
            for c in (cand, lp):
                sc = c[:, 2].sum()
                if sc > best_score:
                    best_score = sc
                    best = c
        except Exception:
            pass

    # start as one init
    if start is not None:
        try_init(np.asarray(start, dtype=float).reshape(n, 3), maxiter=200)

    # lattice geometries
    for rows in (5, 6, 7):
        for phase in (0.0, 0.5):
            base = _make_lattice(rows, phase, n)
            try_init(base, maxiter=200)
            for _ in range(3):
                if time.process_time() - t0 > 0.85 * budget_seconds:
                    break
                jit = base.copy()
                jit[:, 0] += rng.normal(0, 0.02, n)
                jit[:, 1] += rng.normal(0, 0.02, n)
                jit[:, 0] = np.clip(jit[:, 0], 0.0, 1.0)
                jit[:, 1] = np.clip(jit[:, 1], 0.0, 1.0)
                try_init(jit, maxiter=200)

    if best is None:
        if start is not None:
            return _feasible_fix(start)
        return _feasible_fix(_make_lattice(6, 0.0, n))

    return best

import numpy as np
import time
from scipy.optimize import minimize, linprog


def _lp_radii(centers):
    """Given centers (n,2), solve LP for maximal radii. Returns radii (n,)."""
    n = len(centers)
    # variables: r_0..r_{n-1}
    c = -np.ones(n)
    A_ub = []
    b_ub = []
    # pair constraints: r_i + r_j <= d_ij
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(centers[i, 0] - centers[j, 0],
                         centers[i, 1] - centers[j, 1])
            row = np.zeros(n)
            row[i] = 1.0
            row[j] = 1.0
            A_ub.append(row)
            b_ub.append(d)
    # wall constraints: r_i <= wall_i
    for i in range(n):
        wall = min(centers[i, 0], 1.0 - centers[i, 0],
                   centers[i, 1], 1.0 - centers[i, 1])
        row = np.zeros(n)
        row[i] = 1.0
        A_ub.append(row)
        b_ub.append(max(wall, 0.0))
    A_ub = np.array(A_ub)
    b_ub = np.array(b_ub)
    bounds = [(0.0, None)] * n
    try:
        res = linprog(c, A_ub=A_ub, b_ub=b_ub, bounds=bounds, method='highs')
        if res.success:
            return np.maximum(res.x, 0.0)
    except Exception:
        pass
    # fallback: zero radii
    return np.zeros(n)


def _feasible_fix(x):
    """Clamp to square and use LP to set maximal radii for given centers."""
    x = np.array(x, dtype=float).reshape(-1, 3)
    x[:, 2] = np.maximum(x[:, 2], 1e-6)
    x[:, 0] = np.clip(x[:, 0], x[:, 2], 1.0 - x[:, 2])
    x[:, 1] = np.clip(x[:, 1], x[:, 2], 1.0 - x[:, 2])
    n = len(x)
    for _ in range(200):
        bad = False
        for i in range(n):
            for j in range(i + 1, n):
                d = np.hypot(x[i, 0] - x[j, 0], x[i, 1] - x[j, 1])
                s = x[i, 2] + x[j, 2]
                if d < s + 1e-12:
                    bad = True
                    excess = s - d + 1e-9
                    x[i, 2] -= excess / 2
                    x[j, 2] -= excess / 2
        x[:, 2] = np.maximum(x[:, 2], 1e-6)
        x[:, 0] = np.clip(x[:, 0], x[:, 2], 1.0 - x[:, 2])
        x[:, 1] = np.clip(x[:, 1], x[:, 2], 1.0 - x[:, 2])
        if not bad:
            break
    x[:, 2] *= (1.0 - 1e-9)
    x[:, 2] = np.maximum(x[:, 2], 1e-6)
    return x


def _lp_set_radii(x):
    """Replace radii with LP-optimal for current centers, with safety shrink."""
    x = np.array(x, dtype=float).reshape(-1, 3)
    n = len(x)
    centers = x[:, :2].copy()
    # clamp centers into [0,1]
    centers[:, 0] = np.clip(centers[:, 0], 0.0, 1.0)
    centers[:, 1] = np.clip(centers[:, 1], 0.0, 1.0)
    r = _lp_radii(centers)
    r = np.maximum(r, 1e-6)
    # ensure centers fit with radii
    centers[:, 0] = np.clip(centers[:, 0], r, 1.0 - r)
    centers[:, 1] = np.clip(centers[:, 1], r, 1.0 - r)
    # re-solve LP once after clamping (clamping may change walls)
    r = _lp_radii(centers)
    r = np.maximum(r, 1e-6)
    centers[:, 0] = np.clip(centers[:, 0], r, 1.0 - r)
    centers[:, 1] = np.clip(centers[:, 1], r, 1.0 - r)
    out = np.column_stack([centers, r])
    out[:, 2] *= (1.0 - 1e-12)
    out[:, 2] = np.maximum(out[:, 2], 1e-6)
    return out


def _slsqp_polish(x0, n, maxiter=300):
    def obj(v):
        return -np.sum(v[2::3])

    def obj_grad(v):
        g = np.zeros_like(v)
        g[2::3] = -1.0
        return g

    bounds = []
    for i in range(n):
        bounds.append((0.0, 1.0))
        bounds.append((0.0, 1.0))
        bounds.append((1e-4, 0.5))

    cons = []
    for i in range(n):
        def make_wall(i, kind):
            def f(v):
                X = v.reshape(n, 3)
                if kind == 0:
                    return X[i, 0] - X[i, 2]
                elif kind == 1:
                    return 1.0 - X[i, 0] - X[i, 2]
                elif kind == 2:
                    return X[i, 1] - X[i, 2]
                else:
                    return 1.0 - X[i, 1] - X[i, 2]
            return f
        for k in range(4):
            cons.append({'type': 'ineq', 'fun': make_wall(i, k)})

    for i in range(n):
        for j in range(i + 1, n):
            def make_pair(i, j):
                def f(v):
                    X = v.reshape(n, 3)
                    dx = X[i, 0] - X[j, 0]
                    dy = X[i, 1] - X[j, 1]
                    return dx * dx + dy * dy - (X[i, 2] + X[j, 2]) ** 2
                return f
            cons.append({'type': 'ineq', 'fun': make_pair(i, j)})

    v0 = np.array(x0, dtype=float).reshape(-1)
    v0[2::3] = np.clip(v0[2::3], 1e-4, 0.5)
    v0[0::3] = np.clip(v0[0::3], 0.0, 1.0)
    v0[1::3] = np.clip(v0[1::3], 0.0, 1.0)
    try:
        res = minimize(obj, v0, jac=obj_grad, method='SLSQP',
                       bounds=bounds, constraints=cons,
                       options={'maxiter': maxiter, 'ftol': 1e-12})
        return res.x.reshape(n, 3)
    except Exception:
        return None


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 32

    # Hexagonal-ish lattice init, 6 rows
    pts = []
    rows = 6
    for j in range(rows):
        y = (j + 0.5) / rows
        cnt = 6 if j % 2 == 0 else 5
        for i in range(cnt):
            if j % 2 == 0:
                x = (i + 0.5) / 6
            else:
                x = (i + 1.0) / 6
            pts.append((x, y))
    pts = pts[:n]
    while len(pts) < n:
        pts.append((0.5, 0.5))
    x_hex = np.array([[p[0], p[1], 0.08] for p in pts], dtype=float)

    best = None
    best_score = -1.0

    def consider(cand):
        nonlocal best, best_score
        if cand is None:
            return
        cand = _feasible_fix(cand)
        sc = cand[:, 2].sum()
        if sc > best_score:
            best_score = sc
            best = cand

    # Build candidate initial points
    inits = [x_hex]
    if start is not None:
        try:
            s = np.asarray(start, dtype=float).reshape(n, 3)
            inits.append(s.copy())
        except Exception:
            pass

    # For each init: LP radii, then alternate SLSQP + LP up to 3 times
    for init in inits:
        if time.process_time() - t0 > 0.85 * budget_seconds:
            break
        cur = _lp_set_radii(init)
        consider(cur)
        for _ in range(3):
            if time.process_time() - t0 > 0.85 * budget_seconds:
                break
            pol = _slsqp_polish(cur, n, maxiter=300)
            if pol is None:
                break
            cur = _lp_set_radii(pol)
            consider(cur)

    if best is None:
        if start is not None:
            return _feasible_fix(start)
        return _feasible_fix(x_hex)

    return best

