        k += 1
    try:
        res = linprog(c, A_ub=A_ub, b_ub=b_ub,
                      bounds=[(1e-7, None)] * n, method='highs')
        if res.success:
            return np.maximum(res.x, 1e-7)
    except Exception:
        pass
    return np.full(n, 1e-6)


def _feasible_fix(x):
    x = np.array(x, dtype=float).reshape(-1, 3)
    n = len(x)
    x[:, 2] = np.maximum(x[:, 2], 1e-6)
    x[:, 0] = np.clip(x[:, 0], x[:, 2], 1.0 - x[:, 2])
    x[:, 1] = np.clip(x[:, 1], x[:, 2], 1.0 - x[:, 2])
    for _ in range(300):
        bad = False
        for i in range(n):
            for j in range(i + 1, n):
                d = np.hypot(x[i, 0] - x[j, 0], x[i, 1] - x[j, 1])
                s = x[i, 2] + x[j, 2]
                if d < s + 1e-12:
                    bad = True
                    excess = s - d + 1e-9
                    x[i, 2] -= excess / 2
                    x[j, 2] -= excess / 2
        x[:, 2] = np.maximum(x[:, 2], 1e-6)
        x[:, 0] = np.clip(x[:, 0], x[:, 2], 1.0 - x[:, 2])
        x[:, 1] = np.clip(x[:, 1], x[:, 2], 1.0 - x[:, 2])
        if not bad:
            break
    x[:, 2] *= (1.0 - 1e-9)
    x[:, 2] = np.maximum(x[:, 2], 1e-6)
    return x


def _lp_set_radii(x):
    x = np.array(x, dtype=float).reshape(-1, 3)
    n = len(x)
    centers = np.clip(x[:, :2].copy(), 0.0, 1.0)
    for _ in range(3):
        r = _lp_radii(centers)
        centers[:, 0] = np.clip(centers[:, 0], r, 1.0 - r)
        centers[:, 1] = np.clip(centers[:, 1], r, 1.0 - r)
    r = _lp_radii(centers)
    out = np.column_stack([centers, np.maximum(r, 1e-6)])
    out[:, 2] *= (1.0 - 1e-12)
    out[:, 2] = np.maximum(out[:, 2], 1e-6)
    return out


def _slsqp_polish(x0, n, maxiter=300):
    def obj(v):
        return -np.sum(v[2::3])

    def obj_grad(v):
        g = np.zeros_like(v)
        g[2::3] = -1.0
        return g

    bounds = [(0.0, 1.0)] * (2 * n) + [(1e-4, 0.5)] * n

    cons = []
    for i in range(n):
        def make_wall(i, kind):
            def f(v):
                X = v.reshape(n, 3)
                if kind == 0:
                    return X[i, 0] - X[i, 2]
                elif kind == 1:
                    return 1.0 - X[i, 0] - X[i, 2]
                elif kind == 2:
                    return X[i, 1] - X[i, 2]
                else:
                    return 1.0 - X[i, 1] - X[i, 2]
            return f
        for k in range(4):
            cons.append({'type': 'ineq', 'fun': make_wall(i, k)})

    for i in range(n):
        for j in range(i + 1, n):
            def make_pair(i, j):
                def f(v):
                    X = v.reshape(n, 3)
                    dx = X[i, 0] - X[j, 0]
                    dy = X[i, 1] - X[j, 1]
                    return dx * dx + dy * dy - (X[i, 2] + X[j, 2]) ** 2
                return f
            cons.append({'type': 'ineq', 'fun': make_pair(i, j)})

    v0 = np.array(x0, dtype=float).reshape(-1).copy()
    v0[2::3] = np.clip(v0[2::3], 1e-4, 0.5)
    v0[0::3] = np.clip(v0[0::3], 0.0, 1.0)
    v0[1::3] = np.clip(v0[1::3], 0.0, 1.0)
    try:
        res = minimize(obj, v0, jac=obj_grad, method='SLSQP',
                       bounds=bounds, constraints=cons,
                       options={'maxiter': maxiter, 'ftol': 1e-13})
        return res.x.reshape(n, 3)
    except Exception:
        return None


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 32
    rng = np.random.default_rng(12345)

    best = None
    best_score = -1.0

    def consider(cand):
        nonlocal best, best_score
        if cand is None:
            return
        cand = _feasible_fix(cand)
        sc = float(np.sum(cand[:, 2]))
        if sc > best_score:
            best_score = sc
            best = cand.copy()

    # Base starting points
    inits = []
    if start is not None:
        try:
            inits.append(np.asarray(start, dtype=float).reshape(n, 3).copy())
        except Exception:
            pass

    # Hexagonal-ish inits (6 rows)
    def hex_init(rows):
        pts = []
        for j in range(rows):
            y = (j + 0.5) / rows
            cnt = 6 if j % 2 == 0 else 5
            for i in range(cnt):
                x = (i + 0.5) / 6 if j % 2 == 0 else (i + 1.0) / 6
                pts.append((x, y))
        return pts

    for rows in (6, 7):
        p = hex_init(rows)[:n]
        while len(p) < n:
            p.append((0.5, 0.5))
        inits.append(np.array([[q[0], q[1], 0.08] for q in p]))

    # Global search: from best current, do SLSQP + LP alternating, plus random restarts
    for init in inits:
        if time.process_time() - t0 > 0.6 * budget_seconds:
            break
        cur = _lp_set_radii(init)
        consider(cur)
        for _ in range(2):
            if time.process_time() - t0 > 0.6 * budget_seconds:
                break
            pol = _slsqp_polish(cur, n, maxiter=400)
            if pol is None:
                break
            cur = _lp_set_radii(pol)
            consider(cur)

    # Local perturbation search around best
    if best is not None:
        while time.process_time() - t0 < 0.85 * budget_seconds:
            cand = best.copy()
            scale = rng.uniform(0.005, 0.03)
            cand[:, 0] += rng.normal(0, scale, n)
            cand[:, 1] += rng.normal(0, scale, n)
            cand = _lp_set_radii(cand)
            pol = _slsqp_polish(cand, n, maxiter=250)
            if pol is not None:
                pol = _lp_set_radii(pol)
                consider(pol)
            # re-polish best occasionally
            if time.process_time() - t0 < 0.85 * budget_seconds:
                pol2 = _slsqp_polish(best, n, maxiter=200)
                if pol2 is not None:
                    consider(_lp_set_radii(pol2))

    if best is None:
        if start is not None:
            return _feasible_fix(start)
        p = hex_init(6)[:n]
        while len(p) < n:
            p.append((0.5, 0.5))
        return _feasible_fix(np.array([[q[0], q[1], 0.08] for q in p]))

    # Final safety shrink
    best[:, 2] *= (1.0 - 1e-10)
    return best

import numpy as np
import time
from scipy.optimize import minimize, linprog


def _feasible_fix(x):
    x = np.array(x, dtype=float).reshape(-1, 3)
    n = len(x)
    x[:, 2] = np.maximum(x[:, 2], 1e-6)
    x[:, 0] = np.clip(x[:, 0], x[:, 2], 1.0 - x[:, 2])
    x[:, 1] = np.clip(x[:, 1], x[:, 2], 1.0 - x[:, 2])
    for _ in range(300):
        bad = False
        for i in range(n):
            for j in range(i + 1, n):
                d = np.hypot(x[i, 0] - x[j, 0], x[i, 1] - x[j, 1])
                s = x[i, 2] + x[j, 2]
                if d < s + 1e-12:
                    bad = True
                    excess = s - d + 1e-9
                    x[i, 2] -= excess / 2
                    x[j, 2] -= excess / 2
        x[:, 2] = np.maximum(x[:, 2], 1e-6)
        x[:, 0] = np.clip(x[:, 0], x[:, 2], 1.0 - x[:, 2])
        x[:, 1] = np.clip(x[:, 1], x[:, 2], 1.0 - x[:, 2])
        if not bad:
            break
    x[:, 2] *= (1.0 - 1e-9)
    x[:, 2] = np.maximum(x[:, 2], 1e-6)
    return x


def _lp_radii(centers, n, return_duals=False):
    c = -np.ones(n)
    A_ub = []
    b_ub = []
    meta = []  # ('wall', i, k) or ('pair', i, j)
    for i in range(n):
        for k, w in enumerate((centers[i, 0], 1.0 - centers[i, 0],
                               centers[i, 1], 1.0 - centers[i, 1])):
            row = np.zeros(n)
            row[i] = 1.0
            A_ub.append(row)
            b_ub.append(max(w, 0.0))
            meta.append(('wall', i, k))
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(centers[i, 0] - centers[j, 0], centers[i, 1] - centers[j, 1])
            row = np.zeros(n)
            row[i] = 1.0
            row[j] = 1.0
            A_ub.append(row)
            b_ub.append(max(d, 0.0))
            meta.append(('pair', i, j))
    bounds = [(1e-6, None)] * n
    try:
        res = linprog(c, A_ub=np.array(A_ub), b_ub=np.array(b_ub),
                      bounds=bounds, method='highs')
        if res.success:
            r = np.maximum(res.x, 1e-6)
            if return_duals:
                try:
                    marg = np.array(res.ineqlin.marginals)
                except Exception:
                    marg = np.zeros(len(A_ub))
                return r, marg, meta
            return r
    except Exception:
        pass
    if return_duals:
        return None, None, meta
    return None


def _slsqp_polish(x_init, n, maxiter):
    def obj(v):
        return -np.sum(v[2::3])

    def obj_grad(v):
        g = np.zeros_like(v)
        g[2::3] = -1.0
        return g

    bounds = []
    for i in range(n):
        bounds.append((0.0, 1.0))
        bounds.append((0.0, 1.0))
        bounds.append((1e-4, 0.5))

    cons = []
    for i in range(n):
        def make_wall(i, kind):
            def f(v):
                X = v.reshape(n, 3)
                if kind == 0:
                    return X[i, 0] - X[i, 2]
                elif kind == 1:
                    return 1.0 - X[i, 0] - X[i, 2]
                elif kind == 2:
                    return X[i, 1] - X[i, 2]
                else:
                    return 1.0 - X[i, 1] - X[i, 2]
            return f
        for k in range(4):
            cons.append({'type': 'ineq', 'fun': make_wall(i, k)})

    for i in range(n):
        for j in range(i + 1, n):
            def make_pair(i, j):
                def f(v):
                    X = v.reshape(n, 3)
                    dx = X[i, 0] - X[j, 0]
                    dy = X[i, 1] - X[j, 1]
                    return dx * dx + dy * dy - (X[i, 2] + X[j, 2]) ** 2
                return f
            cons.append({'type': 'ineq', 'fun': make_pair(i, j)})

    v0 = x_init.reshape(-1).copy()
    v0[2::3] = np.clip(v0[2::3], 1e-4, 0.5)
    v0[0::3] = np.clip(v0[0::3], 0.0, 1.0)
    v0[1::3] = np.clip(v0[1::3], 0.0, 1.0)
    try:
        res = minimize(obj, v0, jac=obj_grad, method='SLSQP',
                       bounds=bounds, constraints=cons,
                       options={'maxiter': maxiter, 'ftol': 1e-13})
        return res.x.reshape(n, 3)
    except Exception:
        return x_init


def _score(x):
    return float(np.sum(x[:, 2]))


def _bilevel_ascent(centers, n, iters, eta=0.001, t0=None, budget=None):
    """Ascent on LP optimum using duals of LP constraints."""
    c = np.array(centers, dtype=float).copy()
    best_c = c.copy()
    best_r = None
    best_val = -1.0
    for it in range(iters):
        if t0 is not None and budget is not None:
            if time.process_time() - t0 > budget:
                break
        r, marg, meta = _lp_radii(c, n, return_duals=True)
        if r is None:
            break
        val = float(np.sum(r))
        if val > best_val:
            best_val = val
            best_c = c.copy()
            best_r = r.copy()
        grad = np.zeros_like(c)
        for idx, m in enumerate(meta):
            lam = marg[idx] if idx < len(marg) else 0.0
            if lam <= 1e-9:
                continue
            if m[0] == 'pair':
                i, j = m[1], m[2]
                dx = c[i, 0] - c[j, 0]
                dy = c[i, 1] - c[j, 1]
                d = np.hypot(dx, dy)
                if d < 1e-12:
                    continue
                ux, uy = dx / d, dy / d
                grad[i, 0] += lam * ux
                grad[i, 1] += lam * uy
                grad[j, 0] -= lam * ux
                grad[j, 1] -= lam * uy
            else:
                i, k = m[1], m[2]
                # wall k: 0 left (x>=r), 1 right (x<=1-r), 2 bottom, 3 top
                # increasing b_ub (the wall distance) raises LP value.
                # left: b = x_i -> move +x ; right: b = 1-x_i -> move -x
                if k == 0:
                    grad[i, 0] += lam
                elif k == 1:
                    grad[i, 0] -= lam
                elif k == 2:
                    grad[i, 1] += lam
                else:
                    grad[i, 1] -= lam
        # normalize gradient magnitude
        gmax = np.max(np.abs(grad))
        if gmax < 1e-12:
            break
        c = c + eta * grad / gmax
        c[:, 0] = np.clip(c[:, 0], 1e-6, 1.0 - 1e-6)
        c[:, 1] = np.clip(c[:, 1], 1e-6, 1.0 - 1e-6)
    if best_r is None:
        r = _lp_radii(best_c, n)
        if r is None:
            r = np.full(n, 0.05)
        best_r = r
    out = np.column_stack([best_c, best_r])
    return _feasible_fix(out)


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 32
    rng = np.random.default_rng(12345)

    best = None
    best_score = -1.0

    if start is not None:
        try:
            s = _feasible_fix(start)
            best = s
            best_score = _score(s)
        except Exception:
            pass

    def hex_init(rows, cols):
        pts = []
        for j in range(rows):
            y = (j + 0.5) / rows
            off = 0.5 if j % 2 == 0 else 1.0
            cnt = cols if j % 2 == 0 else cols - 1
            for i in range(cnt):
                x = (i + off) / cols
                pts.append((x, y))
        return pts

    def grid_init(g):
        pts = []
        for j in range(g):
            for i in range(g):
                pts.append(((i + 0.5) / g, (j + 0.5) / g))
        return pts

    inits = []
    for rows, cols in [(6, 6), (5, 7), (7, 5), (6, 7)]:
        p = hex_init(rows, cols)
        if len(p) >= n:
            inits.append(np.array(p[:n]))
    for g in (6, 7):
        p = grid_init(g)
        if len(p) >= n:
            inits.append(np.array(p[:n]))

    def make_cand(centers):
        rlp = _lp_radii(centers, n)
        if rlp is None:
            rlp = np.full(n, 0.05)
        c = np.column_stack([centers, rlp])
        return _feasible_fix(c)

    def consider(cand, time_frac):
        nonlocal best, best_score
        cand = _feasible_fix(cand)
        if _score(cand) > best_score:
            best_score = _score(cand)
            best = cand
        if time.process_time() - t0 < time_frac * budget_seconds:
            pol = _slsqp_polish(cand, n, maxiter=400)
            pol = _feasible_fix(pol)
            if _score(pol) > best_score:
                best_score = _score(pol)
                best = pol

    # Bilevel ascent from best (start)
    if best is not None:
        try:
            ba = _bilevel_ascent(best[:, :2], n, iters=200, eta=0.001,
                                 t0=t0, budget=0.35 * budget_seconds)
            if _score(ba) > best_score:
                best_score = _score(ba)
                best = ba
            pol = _slsqp_polish(best, n, maxiter=400)
            pol = _feasible_fix(pol)
            if _score(pol) > best_score:
                best_score = _score(pol)
                best = pol
        except Exception:
            pass

    # Bilevel ascent from each init
    for idx, centers in enumerate(inits):
        if time.process_time() - t0 > 0.65 * budget_seconds:
            break
        try:
            ba = _bilevel_ascent(centers, n, iters=150, eta=0.001,
                                 t0=t0, budget=0.65 * budget_seconds)
            consider(ba, 0.70)
        except Exception:
            pass

    # Perturbation search around best
    if best is not None:
        while time.process_time() - t0 < 0.88 * budget_seconds:
            try:
                cand = best.copy()
                scale = rng.uniform(0.01, 0.06)
                cand[:, 0] += rng.normal(0, scale, n)
                cand[:, 1] += rng.normal(0, scale, n)
                cand = _feasible_fix(cand)
                # short bilevel ascent
                ba = _bilevel_ascent(cand[:, :2], n, iters=40, eta=0.001,
                                     t0=t0, budget=0.88 * budget_seconds)
                if _score(ba) > best_score:
                    best_score = _score(ba)
                    best = ba
                pol = _slsqp_polish(ba, n, maxiter=200)
                pol = _feasible_fix(pol)
                if _score(pol) > best_score:
                    best_score = _score(pol)
                    best = pol
            except Exception:
                break

    if best is None:
        if start is not None:
            return _feasible_fix(start)
        centers = np.array(grid_init(6)[:n])
        return _feasible_fix(np.column_stack([centers, np.full(n, 0.07)]))

    return best

