def _bilevel_ascent(centers, n, iters, eta, t0, budget, bma_ema=0.6):
    """Ascent on LP optimum using duals; uses momentum to escape flats."""
    c = np.array(centers, dtype=float).copy()
    best_c = c.copy()
    best_r = None
    best_val = -1.0
    vel = np.zeros_like(c)
    for it in range(iters):
        if time.process_time() - t0 > budget:
            break
        r, marg, meta = _lp_radii(c, n, return_duals=True)
        if r is None:
            break
        val = float(np.sum(r))
        if val > best_val:
            best_val = val
            best_c = c.copy()
            best_r = r.copy()
        grad = np.zeros_like(c)
        for idx, m in enumerate(meta):
            lam = marg[idx] if idx < len(marg) else 0.0
            if lam <= 1e-9:
                continue
            if m[0] == 'pair':
                i, j = m[1], m[2]
                dx = c[i, 0] - c[j, 0]
                dy = c[i, 1] - c[j, 1]
                d = np.hypot(dx, dy)
                if d < 1e-12:
                    continue
                ux, uy = dx / d, dy / d
                grad[i, 0] += lam * ux
                grad[i, 1] += lam * uy
                grad[j, 0] -= lam * ux
                grad[j, 1] -= lam * uy
            else:
                i, k = m[1], m[2]
                if k == 0:
                    grad[i, 0] += lam
                elif k == 1:
                    grad[i, 0] -= lam
                elif k == 2:
                    grad[i, 1] += lam
                else:
                    grad[i, 1] -= lam
