            gmax = np.max(np.abs(grad)) + 1e-12
        step = eta * grad / gmax
        vel = bma_ema * vel + step
        c = c + vel
        c[:, 0] = np.clip(c[:, 0], 1e-6, 1.0 - 1e-6)
