def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 32
    rng = np.random.default_rng(20240521)

    best = None
    best_score = -1.0

    def consider(cand):
        nonlocal best, best_score
        cand = _feasible_fix(cand)
        sc = _score(cand)
        if sc > best_score:
            best_score = sc
            best = cand
            return True
        return False

    if start is not None:
        try:
            consider(start)
        except Exception:
            pass

    # Seed with a good hexagonal-ish lattice matching ~32 circles
    def hex_init(rows):
        pts = []
        for j in range(rows):
            y = (j + 0.5) / rows
            cnt = int(np.ceil(n / rows)) + 1
            off = 0.5 if j % 2 == 0 else 0.0
            for i in range(cnt):
                x = (i + 0.5 + off * 0.5) / (cnt + 0.5)
                if 0.0 < x < 1.0:
                    pts.append((x, y))
        while len(pts) < n:
            pts.append((0.5, 0.5))
        return np.array(pts[:n])

    inits = []
    for rows in (5, 6, 7):
        inits.append(hex_init(rows))

    # If start is good, focus on perturbing it heavily.
    if best is not None:
        base = best[:, :2].copy()
        for k in range(6):
            if time.process_time() - t0 > 0.30 * budget_seconds:
                break
            centers = base + rng.normal(0, 0.03, base.shape)
            centers = np.clip(centers, 1e-4, 1 - 1e-4)
            ba = _bilevel_ascent(centers, n, iters=120, eta=0.0015,
                                 t0=t0, budget=0.30 * budget_seconds)
            consider(ba)
        # Polish current best
        if best is not None and time.process_time() - t0 < 0.40 * budget_seconds:
            pol = _slsqp_polish(best, n, maxiter=500)
            consider(pol)

    # Explore from lattice inits
    for centers in inits:
        if time.process_time() - t0 > 0.60 * budget_seconds:
            break
        ba = _bilevel_ascent(centers, n, iters=150, eta=0.0015,
                             t0=t0, budget=0.60 * budget_seconds)
        consider(ba)

    # Iterated local search around best with increasing/decreasing jitter
    it_no = 0
    while best is not None and time.process_time() - t0 < 0.90 * budget_seconds:
        it_no += 1
        cand = best.copy()
        # perturb a random subset of circles
        k = rng.integers(3, 10)
        idx = rng.choice(n, size=k, replace=False)
        scale = rng.uniform(0.005, 0.04)
        cand[idx, 0] += rng.normal(0, scale, k)
        cand[idx, 1] += rng.normal(0, scale, k)
        cand[:, 0] = np.clip(cand[:, 0], 0.0, 1.0)
        cand[:, 1] = np.clip(cand[:, 1], 0.0, 1.0)
        ba = _bilevel_ascent(cand[:, :2], n, iters=60, eta=0.0015,
                             t0=t0, budget=0.90 * budget_seconds)
        if _score(ba) > best_score:
            consider(ba)
            if time.process_time() - t0 < 0.90 * budget_seconds:
                pol = _slsqp_polish(best, n, maxiter=300)
                consider(pol)

    # Final SLSQP polish
    if best is not None and time.process_time() - t0 < 0.97 * budget_seconds:
        pol = _slsqp_polish(best, n, maxiter=600)
        consider(pol)

    if best is None:
        if start is not None:
            return _feasible_fix(start)
        centers = hex_init(6)
        return _feasible_fix(np.column_stack([centers, np.full(n, 0.07)]))

    return _feasible_fix(best)

import numpy as np
import time
from scipy.optimize import minimize, linprog


def _feasible_fix(x, safety=1e-9):
    x = np.array(x, dtype=float).reshape(-1, 3)
    n = len(x)
    x[:, 2] = np.maximum(x[:, 2], 1e-6)
    x[:, 0] = np.clip(x[:, 0], x[:, 2], 1.0 - x[:, 2])
    x[:, 1] = np.clip(x[:, 1], x[:, 2], 1.0 - x[:, 2])
    for _ in range(400):
        bad = False
        for i in range(n):
            for j in range(i + 1, n):
                d = np.hypot(x[i, 0] - x[j, 0], x[i, 1] - x[j, 1])
                s = x[i, 2] + x[j, 2]
                if d < s + 1e-12:
                    bad = True
                    excess = s - d + 1e-9
                    x[i, 2] -= excess / 2
                    x[j, 2] -= excess / 2
        x[:, 2] = np.maximum(x[:, 2], 1e-6)
        x[:, 0] = np.clip(x[:, 0], x[:, 2], 1.0 - x[:, 2])
        x[:, 1] = np.clip(x[:, 1], x[:, 2], 1.0 - x[:, 2])
        if not bad:
            break
    x[:, 2] *= (1.0 - safety)
    x[:, 2] = np.maximum(x[:, 2], 1e-6)
    return x


def _lp_radii(centers, n, return_duals=False):
    c = -np.ones(n)
    A_ub = []
    b_ub = []
    meta = []
    for i in range(n):
        for k, w in enumerate((centers[i, 0], 1.0 - centers[i, 0],
                               centers[i, 1], 1.0 - centers[i, 1])):
            row = np.zeros(n)
            row[i] = 1.0
            A_ub.append(row)
            b_ub.append(max(w, 0.0))
            meta.append(('wall', i, k))
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(centers[i, 0] - centers[j, 0], centers[i, 1] - centers[j, 1])
            row = np.zeros(n)
            row[i] = 1.0
            row[j] = 1.0
            A_ub.append(row)
            b_ub.append(max(d, 0.0))
            meta.append(('pair', i, j))
    bounds = [(1e-6, None)] * n
    try:
        res = linprog(c, A_ub=np.array(A_ub), b_ub=np.array(b_ub),
                      bounds=bounds, method='highs')
        if res.success:
            r = np.maximum(res.x, 1e-6)
            if return_duals:
                try:
                    marg = np.array(res.ineqlin.marginals)
                except Exception:
                    marg = np.zeros(len(A_ub))
                return r, marg, meta
            return r
    except Exception:
        pass
    if return_duals:
        return None, None, meta
    return None


def _slsqp_polish(x_init, n, maxiter):
    def obj(v):
        return -np.sum(v[2::3])

    def obj_grad(v):
        g = np.zeros_like(v)
        g[2::3] = -1.0
        return g

    bounds = []
    for i in range(n):
        bounds.append((0.0, 1.0))
        bounds.append((0.0, 1.0))
        bounds.append((1e-4, 0.5))

    cons = []
    for i in range(n):
        def make_wall(i, kind):
            def f(v):
                X = v.reshape(n, 3)
                if kind == 0:
                    return X[i, 0] - X[i, 2]
                elif kind == 1:
                    return 1.0 - X[i, 0] - X[i, 2]
                elif kind == 2:
                    return X[i, 1] - X[i, 2]
                else:
                    return 1.0 - X[i, 1] - X[i, 2]
            return f
        for k in range(4):
            cons.append({'type': 'ineq', 'fun': make_wall(i, k)})

    for i in range(n):
        for j in range(i + 1, n):
            def make_pair(i, j):
                def f(v):
                    X = v.reshape(n, 3)
                    dx = X[i, 0] - X[j, 0]
                    dy = X[i, 1] - X[j, 1]
                    return dx * dx + dy * dy - (X[i, 2] + X[j, 2]) ** 2
                return f
            cons.append({'type': 'ineq', 'fun': make_pair(i, j)})

    v0 = x_init.reshape(-1).copy()
    v0[2::3] = np.clip(v0[2::3], 1e-4, 0.5)
    v0[0::3] = np.clip(v0[0::3], 0.0, 1.0)
    v0[1::3] = np.clip(v0[1::3], 0.0, 1.0)
    try:
        res = minimize(obj, v0, jac=obj_grad, method='SLSQP',
                       bounds=bounds, constraints=cons,
