def _score(x):
    return float(np.sum(x[:, 2]))


def _bilevel_ascent(centers, n, iters, eta=0.001, t0=None, budget=None):
    c = np.array(centers, dtype=float).copy()
    best_c = c.copy()
    best_r = None
    best_val = -1.0
    for it in range(iters):
        if t0 is not None and budget is not None:
            if time.process_time() - t0 > budget:
                break
        r, marg, meta = _lp_radii(c, n, return_duals=True)
        if r is None:
            break
        val = float(np.sum(r))
        if val > best_val:
            best_val = val
            best_c = c.copy()
            best_r = r.copy()
        grad = np.zeros_like(c)
        for idx, m in enumerate(meta):
            lam = marg[idx] if idx < len(marg) else 0.0
            if lam <= 1e-9:
                continue
            if m[0] == 'pair':
                i, j = m[1], m[2]
                dx = c[i, 0] - c[j, 0]
                dy = c[i, 1] - c[j, 1]
                d = np.hypot(dx, dy)
                if d < 1e-12:
                    continue
                ux, uy = dx / d, dy / d
                grad[i, 0] += lam * ux
                grad[i, 1] += lam * uy
                grad[j, 0] -= lam * ux
                grad[j, 1] -= lam * uy
            else:
                i, k = m[1], m[2]
                if k == 0:
                    grad[i, 0] += lam
                elif k == 1:
                    grad[i, 0] -= lam
                elif k == 2:
                    grad[i, 1] += lam
                else:
                    grad[i, 1] -= lam
        gmax = np.max(np.abs(grad))
        if gmax < 1e-12:
            break
        c = c + eta * grad / gmax
        c[:, 0] = np.clip(c[:, 0], 1e-6, 1.0 - 1e-6)
        c[:, 1] = np.clip(c[:, 1], 1e-6, 1.0 - 1e-6)
    if best_r is None:
        r = _lp_radii(best_c, n)
        if r is None:
            r = np.full(n, 0.05)
        best_r = r
    out = np.column_stack([best_c, best_r])
    return _feasible_fix(out)


