            if _score(pol) > best_score:
                best_score = _score(pol)
                best = pol
        except Exception:
            pass

    for idx, centers in enumerate(inits):
        if time.process_time() - t0 > 0.55 * budget_seconds:
            break
        try:
            ba = _bilevel_ascent(centers, n, iters=200, eta=0.0015,
                                 t0=t0, budget=0.55 * budget_seconds)
            consider(ba, 0.60)
        except Exception:
            pass

    # Perturbation search around best with shrinking scale
    if best is not None:
        it = 0
        while time.process_time() - t0 < 0.90 * budget_seconds:
            try:
                it += 1
                cand = best.copy()
                # mix of scales: mostly small perturbations
                if it % 3 == 0:
                    scale = rng.uniform(0.02, 0.05)
                else:
                    scale = rng.uniform(0.003, 0.015)
                cand[:, 0] += rng.normal(0, scale, n)
                cand[:, 1] += rng.normal(0, scale, n)
                cand = _feasible_fix(cand)
                ba = _bilevel_ascent(cand[:, :2], n, iters=60, eta=0.0015,
