def _slsqp_polish(x_init, n, maxiter):
    def obj(v):
        return -np.sum(v[2::3])

    def obj_grad(v):
        g = np.zeros_like(v)
        g[2::3] = -1.0
        return g

    bounds = []
    for i in range(n):
        bounds.append((0.0, 1.0))
        bounds.append((0.0, 1.0))
        bounds.append((1e-4, 0.5))

    cons = []
    for i in range(n):
        def make_wall(i, kind):
            def f(v):
                X = v.reshape(n, 3)
                if kind == 0:
                    return X[i, 0] - X[i, 2]
                elif kind == 1:
                    return 1.0 - X[i, 0] - X[i, 2]
                elif kind == 2:
                    return X[i, 1] - X[i, 2]
                else:
                    return 1.0 - X[i, 1] - X[i, 2]
            return f
        for k in range(4):
            cons.append({'type': 'ineq', 'fun': make_wall(i, k)})

    for i in range(n):
        for j in range(i + 1, n):
            def make_pair(i, j):
                def f(v):
                    X = v.reshape(n, 3)
                    dx = X[i, 0] - X[j, 0]
                    dy = X[i, 1] - X[j, 1]
                    return dx * dx + dy * dy - (X[i, 2] + X[j, 2]) ** 2
                return f
            cons.append({'type': 'ineq', 'fun': make_pair(i, j)})

    v0 = x_init.reshape(-1).copy()
    v0[2::3] = np.clip(v0[2::3], 1e-4, 0.5)
    v0[0::3] = np.clip(v0[0::3], 0.0, 1.0)
    v0[1::3] = np.clip(v0[1::3], 0.0, 1.0)
    try:
        res = minimize(obj, v0, jac=obj_grad, method='SLSQP',
                       bounds=bounds, constraints=cons,
                       options={'maxiter': maxiter, 'ftol': 1e-13})
        return res.x.reshape(n, 3)
    except Exception:
        return x_init


def _score(x):
    return float(np.sum(x[:, 2]))


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 32
    rng = np.random.default_rng(987654321)

    best = None
    best_score = -1.0

    if start is not None:
        try:
            s = _feasible_fix(start)
            best = s
            best_score = _score(s)
        except Exception:
            pass

    def hex_init(rows, cols):
        pts = []
        for j in range(rows):
            y = (j + 0.5) / rows
            off = 0.5 if j % 2 == 0 else 1.0
            cnt = cols if j % 2 == 0 else cols - 1
            for i in range(cnt):
                x = (i + off) / cols
                pts.append((x, y))
        return pts

    def grid_init(g):
        pts = []
        for j in range(g):
            for i in range(g):
                pts.append(((i + 0.5) / g, (j + 0.5) / g))
        return pts

    def make_cand(centers):
        rlp = _lp_radii(centers, n)
        if rlp is None:
            rlp = np.full(n, 0.05)
        c = np.column_stack([centers, rlp])
        return _feasible_fix(c)

    # If no start, seed with a hex init
    if best is None:
        p = hex_init(6, 6)
        if len(p) < n:
            p = grid_init(6)
        centers = np.array(p[:n])
        best = make_cand(centers)
        best_score = _score(best)

    # Center-only Metropolis search on f(C) = sum(LP radii)
    centers = best[:, :2].copy()
    cur_val = _score(best)
    T0, T1 = 0.01, 1e-4
    total_time = budget_seconds
    step = 0
    last_polish = time.process_time()

    while True:
        elapsed = time.process_time() - t0
        if elapsed > 0.85 * total_time:
            break
        frac = min(1.0, elapsed / max(total_time, 1e-9))
        T = T0 * (T1 / T0) ** frac

        i = rng.integers(0, n)
        new_centers = centers.copy()
        new_centers[i, 0] = np.clip(new_centers[i, 0] + rng.normal(0, 0.05), 0.0, 1.0)
        new_centers[i, 1] = np.clip(new_centers[i, 1] + rng.normal(0, 0.05), 0.0, 1.0)

        rlp = _lp_radii(new_centers, n)
        if rlp is None:
            step += 1
            continue
        new_val = float(np.sum(rlp))
        delta = new_val - cur_val
        if delta >= 0 or rng.random() < np.exp(delta / max(T, 1e-12)):
            centers = new_centers
            cur_val = new_val
            if new_val > best_score:
                cand = _feasible_fix(np.column_stack([centers, rlp]))
                sc = _score(cand)
                if sc > best_score:
                    best_score = sc
                    best = cand

        step += 1
        if step % 300 == 0 and time.process_time() - t0 < 0.80 * total_time:
            rlp = _lp_radii(centers, n)
            if rlp is not None:
                cand = _feasible_fix(np.column_stack([centers, rlp]))
                pol = _slsqp_polish(cand, n, maxiter=300)
                pol = _feasible_fix(pol)
                if _score(pol) > best_score:
                    best_score = _score(pol)
                    best = pol
                    centers = best[:, :2].copy()
                    cur_val = best_score

    # Final polish of best
    if time.process_time() - t0 < 0.95 * total_time:
        try:
            pol = _slsqp_polish(best, n, maxiter=400)
            pol = _feasible_fix(pol)
            if _score(pol) > best_score:
                best_score = _score(pol)
                best = pol
        except Exception:
            pass

    return _feasible_fix(best)

