    v0[1::3] = np.clip(v0[1::3], 0.0, 1.0)
    try:
        res = minimize(obj, v0, jac=obj_grad, method='SLSQP',
                       bounds=bounds, constraints=cons,
                       options={'maxiter': maxiter, 'ftol': 1e-14})
        return res.x.reshape(n, 3)
    except Exception:
        return x_init


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 32
    rng = np.random.default_rng(12345)
    HARD = min(budget_seconds * 0.82, budget_seconds - 1.2)

    def elapsed():
        return time.process_time() - t0

    best = None
    best_score = -1.0

    def score(x):
        return float(np.sum(x[:, 2]))

    if start is not None:
        try:
            s = _feasible_fix(start, n)
            best = s
            best_score = score(s)
        except Exception:
            pass

    def hex_init(rows, cols):
        pts = []
        for j in range(rows):
            y = (j + 0.5) / rows
            off = 0.5 if j % 2 == 0 else 1.0
            cnt = cols if j % 2 == 0 else cols - 1
            for i in range(cnt):
                x = (i + off) / cols
                pts.append((x, y))
        return pts

    def grid_init(g):
        pts = []
        for j in range(g):
            for i in range(g):
                pts.append(((i + 0.5) / g, (j + 0.5) / g))
        return pts

    inits = []
    for rows, cols in [(6, 6), (5, 7), (7, 5), (6, 7), (8, 4)]:
        p = hex_init(rows, cols)
        if len(p) >= n:
            inits.append(np.array(p[:n]))
    for g in (6, 7):
        p = grid_init(g)
        if len(p) >= n:
            inits.append(np.array(p[:n]))

    def make_cand(centers):
        rlp = _lp_radii(centers, n)
        if rlp is None:
            rlp = np.full(n, 0.05)
        c = np.column_stack([centers, rlp])
        return _feasible_fix(c, n)

    def consider(cand):
        nonlocal best, best_score
        cand = _feasible_fix(cand, n)
        if score(cand) > best_score:
            best_score = score(cand)
            best = cand

    # Polish the start first
    if best is not None and elapsed() < HARD:
        pol = _slsqp_polish(best, n, maxiter=1500)
        pol = _feasible_fix(pol, n)
        if score(pol) > best_score:
            best_score = score(pol)
            best = pol

    for centers in inits:
        if elapsed() > 0.5 * budget_seconds:
            break
        try:
            cand = make_cand(centers)
            consider(cand)
            if elapsed() < 0.5 * budget_seconds:
                pol = _slsqp_polish(cand, n, maxiter=1200)
                pol = _feasible_fix(pol, n)
                if score(pol) > best_score:
                    best_score = score(pol)
                    best = pol
        except Exception:
            pass

    # Random restarts / perturbations around best
    while best is not None and elapsed() < HARD:
        try:
            cand = best.copy()
            scale = rng.uniform(0.01, 0.05)
            cand[:, 0] += rng.normal(0, scale, n)
            cand[:, 1] += rng.normal(0, scale, n)
            cand = _feasible_fix(cand, n)
            newc = make_cand(cand[:, :2])
            pol = _slsqp_polish(newc, n, maxiter=1200)
            pol = _feasible_fix(pol, n)
            if score(pol) > best_score:
                best_score = score(pol)
                best = pol
        except Exception:
            break

    if best is None:
        if start is not None:
            return _feasible_fix(start, n)
        p = hex_init(6, 6)
        return make_cand(np.array(p[:n]))

    return best

import numpy as np
import time
from scipy.optimize import minimize, linprog


def _lp_radii(centers):
    n = len(centers)
    c = -np.ones(n)
    A_ub = []
    b_ub = []
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(centers[i, 0] - centers[j, 0],
                         centers[i, 1] - centers[j, 1])
            row = np.zeros(n)
            row[i] = 1.0
            row[j] = 1.0
            A_ub.append(row)
            b_ub.append(d)
    for i in range(n):
        wall = min(centers[i, 0], 1.0 - centers[i, 0],
                   centers[i, 1], 1.0 - centers[i, 1])
        row = np.zeros(n)
        row[i] = 1.0
        A_ub.append(row)
        b_ub.append(max(wall, 0.0))
    A_ub = np.array(A_ub)
    b_ub = np.array(b_ub)
    bounds = [(0.0, None)] * n
    try:
        res = linprog(c, A_ub=A_ub, b_ub=b_ub, bounds=bounds, method='highs')
        if res.success:
            return np.maximum(res.x, 0.0)
    except Exception:
        pass
    return np.zeros(n)


def _lp_set_radii(x):
    x = np.array(x, dtype=float).reshape(-1, 3)
    n = len(x)
    centers = x[:, :2].copy()
    centers[:, 0] = np.clip(centers[:, 0], 0.0, 1.0)
    centers[:, 1] = np.clip(centers[:, 1], 0.0, 1.0)
    r = _lp_radii(centers)
    r = np.maximum(r, 1e-6)
    centers[:, 0] = np.clip(centers[:, 0], r, 1.0 - r)
    centers[:, 1] = np.clip(centers[:, 1], r, 1.0 - r)
    r = _lp_radii(centers)
    r = np.maximum(r, 1e-6)
    centers[:, 0] = np.clip(centers[:, 0], r, 1.0 - r)
    centers[:, 1] = np.clip(centers[:, 1], r, 1.0 - r)
    out = np.column_stack([centers, r])
    out[:, 2] *= (1.0 - 1e-10)
    out[:, 2] = np.maximum(out[:, 2], 1e-6)
    return out


def _feasible_fix(x):
    x = np.array(x, dtype=float).reshape(-1, 3)
    x[:, 2] = np.maximum(x[:, 2], 1e-6)
    x[:, 0] = np.clip(x[:, 0], x[:, 2], 1.0 - x[:, 2])
    x[:, 1] = np.clip(x[:, 1], x[:, 2], 1.0 - x[:, 2])
    n = len(x)
    for _ in range(300):
        bad = False
        for i in range(n):
            for j in range(i + 1, n):
                d = np.hypot(x[i, 0] - x[j, 0], x[i, 1] - x[j, 1])
                s = x[i, 2] + x[j, 2]
                if d < s + 1e-13:
                    bad = True
                    excess = s - d + 1e-11
                    x[i, 2] -= excess / 2
                    x[j, 2] -= excess / 2
        x[:, 2] = np.maximum(x[:, 2], 1e-6)
        x[:, 0] = np.clip(x[:, 0], x[:, 2], 1.0 - x[:, 2])
        x[:, 1] = np.clip(x[:, 1], x[:, 2], 1.0 - x[:, 2])
        if not bad:
            break
    x[:, 2] *= (1.0 - 1e-10)
    x[:, 2] = np.maximum(x[:, 2], 1e-6)
    return x


def _slsqp_polish(x0, n, maxiter=300):
    def obj(v):
        return -np.sum(v[2::3])

    def obj_grad(v):
        g = np.zeros_like(v)
        g[2::3] = -1.0
        return g

    bounds = []
    for i in range(n):
        bounds.append((0.0, 1.0))
        bounds.append((0.0, 1.0))
        bounds.append((1e-4, 0.5))

    cons = []
    for i in range(n):
        def make_wall(i, kind):
            def f(v):
                X = v.reshape(n, 3)
                if kind == 0:
                    return X[i, 0] - X[i, 2]
                elif kind == 1:
                    return 1.0 - X[i, 0] - X[i, 2]
                elif kind == 2:
                    return X[i, 1] - X[i, 2]
                else:
                    return 1.0 - X[i, 1] - X[i, 2]
            return f
        for k in range(4):
            cons.append({'type': 'ineq', 'fun': make_wall(i, k)})

    for i in range(n):
        for j in range(i + 1, n):
            def make_pair(i, j):
                def f(v):
                    X = v.reshape(n, 3)
                    dx = X[i, 0] - X[j, 0]
                    dy = X[i, 1] - X[j, 1]
                    return dx * dx + dy * dy - (X[i, 2] + X[j, 2]) ** 2
                return f
            cons.append({'type': 'ineq', 'fun': make_pair(i, j)})

    v0 = np.array(x0, dtype=float).reshape(-1)
    v0[2::3] = np.clip(v0[2::3], 1e-4, 0.5)
    v0[0::3] = np.clip(v0[0::3], 0.0, 1.0)
    v0[1::3] = np.clip(v0[1::3], 0.0, 1.0)
    try:
        res = minimize(obj, v0, jac=obj_grad, method='SLSQP',
                       bounds=bounds, constraints=cons,
                       options={'maxiter': maxiter, 'ftol': 1e-12})
        return res.x.reshape(n, 3)
    except Exception:
        return None


def _smooth_push(centers, r, iters, step=0.5):
    """Push centers apart to reduce overlap; walls clamp. Returns new centers."""
    c = centers.copy()
    n = len(c)
    for _ in range(iters):
        moved = False
        for i in range(n):
            for j in range(i + 1, n):
                dx = c[j, 0] - c[i, 0]
                dy = c[j, 1] - c[i, 1]
                d = np.hypot(dx, dy)
                s = r[i] + r[j]
                if d < s and d > 1e-12:
                    push = step * 0.5 * (s - d)
                    ux = dx / d
                    uy = dy / d
                    c[i, 0] -= push * ux
                    c[i, 1] -= push * uy
                    c[j, 0] += push * ux
                    c[j, 1] += push * uy
                    moved = True
        for i in range(n):
            ri = r[i]
            if c[i, 0] < ri:
                c[i, 0] = ri
            elif c[i, 0] > 1.0 - ri:
                c[i, 0] = 1.0 - ri
            if c[i, 1] < ri:
                c[i, 1] = ri
            elif c[i, 1] > 1.0 - ri:
                c[i, 1] = 1.0 - ri
        if not moved:
            break
    return c


def _overlap(centers, r):
    n = len(r)
    tot = 0.0
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(centers[i, 0] - centers[j, 0],
                         centers[i, 1] - centers[j, 1])
            s = r[i] + r[j]
            if d < s:
                tot += (s - d)
    return tot


def _grow_repel(centers, r0, outer_steps, inner_iters, grow):
    n = len(r0)
    centers = centers.copy()
    r = np.full(n, r0, dtype=float)
    prev_ov = _overlap(centers, r)
    for _ in range(outer_steps):
        r_new = r * grow
        c = _smooth_push(centers, r_new, inner_iters, step=1.0)
        ov = _overlap(c, r_new)
        if ov > prev_ov + 1e-12:
            break
        centers = c
        r = r_new
        prev_ov = ov
    return centers, r


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 32

    best = None
    best_score = -1.0

    def consider(cand):
        nonlocal best, best_score
        if cand is None:
            return
        cand = _feasible_fix(cand)
        sc = cand[:, 2].sum()
        if sc > best_score:
            best_score = sc
            best = cand

    # Baseline: start
    if start is not None:
        try:
            consider(np.asarray(start, dtype=float).reshape(n, 3))
        except Exception:
            pass

    # Hex lattice init
    pts = []
    rows = 6
    for j in range(rows):
        y = (j + 0.5) / rows
        cnt = 6 if j % 2 == 0 else 5
        for i in range(cnt):
            if j % 2 == 0:
                x = (i + 0.5) / 6
            else:
                x = (i + 1.0) / 6
            pts.append((x, y))
    pts = pts[:n]
    while len(pts) < n:
        pts.append((0.5, 0.5))
    x_hex = np.array([[p[0], p[1], 0.08] for p in pts], dtype=float)

    # Try grow-and-repel starting from hex and from start
    inits = [x_hex]
    if start is not None:
        try:
            inits.append(np.asarray(start, dtype=float).reshape(n, 3))
        except Exception:
            pass

    for init in inits:
        if time.process_time() - t0 > 0.5 * budget_seconds:
            break
        try:
            c0 = init[:, :2].copy()
            c0 = np.clip(c0, 0.02, 0.98)
            c, _ = _grow_repel(c0, 0.01, outer_steps=400, inner_iters=15, grow=1.003)
            cand = _lp_set_radii(np.column_stack([c, np.full(n, 0.05)]))
            consider(cand)
        except Exception:
            pass

    # SLSQP + LP alternating from best and from start
    seeds = [x_hex]
    if start is not None:
        try:
            seeds.append(np.asarray(start, dtype=float).reshape(n, 3))
        except Exception:
            pass
    if best is not None:
        seeds.append(best.copy())

    for seed in seeds:
        if time.process_time() - t0 > 0.85 * budget_seconds:
            break
        cur = _lp_set_radii(seed)
        consider(cur)
        for _ in range(4):
            if time.process_time() - t0 > 0.85 * budget_seconds:
                break
            pol = _slsqp_polish(cur, n, maxiter=400)
            if pol is None:
                break
            cur = _lp_set_radii(pol)
            consider(cur)

    if best is None:
        if start is not None:
            return _feasible_fix(start)
        return _feasible_fix(x_hex)
    return best

import numpy as np
import time
from scipy.optimize import minimize, linprog


def _feasible_fix(x):
    x = np.array(x, dtype=float).reshape(-1, 3)
    n = len(x)
    x[:, 2] = np.maximum(x[:, 2], 1e-6)
    x[:, 0] = np.clip(x[:, 0], x[:, 2], 1.0 - x[:, 2])
    x[:, 1] = np.clip(x[:, 1], x[:, 2], 1.0 - x[:, 2])
    for _ in range(300):
        bad = False
        for i in range(n):
            for j in range(i + 1, n):
                d = np.hypot(x[i, 0] - x[j, 0], x[i, 1] - x[j, 1])
                s = x[i, 2] + x[j, 2]
                if d < s + 1e-12:
                    bad = True
                    excess = s - d + 1e-9
                    x[i, 2] -= excess / 2
                    x[j, 2] -= excess / 2
        x[:, 2] = np.maximum(x[:, 2], 1e-6)
        x[:, 0] = np.clip(x[:, 0], x[:, 2], 1.0 - x[:, 2])
        x[:, 1] = np.clip(x[:, 1], x[:, 2], 1.0 - x[:, 2])
        if not bad:
            break
    x[:, 2] *= (1.0 - 1e-9)
    x[:, 2] = np.maximum(x[:, 2], 1e-6)
    return x


def _lp_radii(centers, n):
    c = -np.ones(n)
    A_ub = []
    b_ub = []
    for i in range(n):
        for w in (centers[i, 0], 1.0 - centers[i, 0], centers[i, 1], 1.0 - centers[i, 1]):
            row = np.zeros(n)
            row[i] = 1.0
            A_ub.append(row)
            b_ub.append(max(w, 0.0))
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(centers[i, 0] - centers[j, 0], centers[i, 1] - centers[j, 1])
            row = np.zeros(n)
            row[i] = 1.0
            row[j] = 1.0
            A_ub.append(row)
            b_ub.append(max(d, 0.0))
    bounds = [(1e-6, None)] * n
    try:
        res = linprog(c, A_ub=np.array(A_ub), b_ub=np.array(b_ub),
                      bounds=bounds, method='highs')
        if res.success:
            return np.maximum(res.x, 1e-6)
    except Exception:
        pass
    return None


def _lp_with_duals(centers, n):
    """Solve LP; return (radii, grad_centers) using duals as subgradient."""
    c = -np.ones(n)
    A_ub = []
    b_ub = []
    meta = []  # ('wall', i, kind) or ('pair', i, j)
    for i in range(n):
        for kind, w in enumerate((centers[i, 0], 1.0 - centers[i, 0],
                                  centers[i, 1], 1.0 - centers[i, 1])):
            row = np.zeros(n)
            row[i] = 1.0
            A_ub.append(row)
            b_ub.append(max(w, 0.0))
            meta.append(('wall', i, kind))
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(centers[i, 0] - centers[j, 0], centers[i, 1] - centers[j, 1])
            row = np.zeros(n)
            row[i] = 1.0
            row[j] = 1.0
            A_ub.append(row)
            b_ub.append(max(d, 0.0))
            meta.append(('pair', i, j))
    bounds = [(1e-6, None)] * n
    try:
        res = linprog(c, A_ub=np.array(A_ub), b_ub=np.array(b_ub),
                      bounds=bounds, method='highs')
        if not res.success:
            return None, None
        radii = np.maximum(res.x, 1e-6)
        marg = None
        try:
            marg = res.ineqlin.marginals
        except Exception:
            marg = None
        grad = np.zeros((n, 2))
        if marg is not None:
            for k, m in enumerate(meta):
                lam = -float(marg[k])  # convert to "increase b => increase obj"
                if lam <= 1e-9:
                    continue
                if m[0] == 'wall':
                    _, i, kind = m
                    # b = w ; increasing b loosens constraint.
                    # For wall constraints b is x_i, 1-x_i, y_i, 1-y_i.
                    # d(b)/d(center) direction:
                    if kind == 0:
                        grad[i, 0] += lam
                    elif kind == 1:
                        grad[i, 0] -= lam
                    elif kind == 2:
                        grad[i, 1] += lam
                    else:
                        grad[i, 1] -= lam
                else:
                    _, i, j = m
                    dx = centers[i, 0] - centers[j, 0]
                    dy = centers[i, 1] - centers[j, 1]
                    d = np.hypot(dx, dy)
                    if d < 1e-12:
                        continue
                    ux, uy = dx / d, dy / d
                    grad[i, 0] += lam * ux
                    grad[i, 1] += lam * uy
                    grad[j, 0] -= lam * ux
                    grad[j, 1] -= lam * uy
        return radii, grad
    except Exception:
        return None, None


def _slsqp_polish(x_init, n, maxiter, deadline, t0):
    def obj(v):
        return -np.sum(v[2::3])

    def obj_grad(v):
        g = np.zeros_like(v)
        g[2::3] = -1.0
        return g

    bounds = []
    for i in range(n):
        bounds.append((0.0, 1.0))
        bounds.append((0.0, 1.0))
        bounds.append((1e-4, 0.5))

    cons = []
    for i in range(n):
        for kind in range(4):
            def make_wall(i, kind):
                def f(v):
                    X = v.reshape(n, 3)
                    if kind == 0:
                        return X[i, 0] - X[i, 2]
                    elif kind == 1:
                        return 1.0 - X[i, 0] - X[i, 2]
                    elif kind == 2:
                        return X[i, 1] - X[i, 2]
                    else:
                        return 1.0 - X[i, 1] - X[i, 2]
                def jac(v):
                    g = np.zeros(3 * n)
                    if kind == 0:
                        g[3 * i] = 1.0
                    elif kind == 1:
                        g[3 * i] = -1.0
                    elif kind == 2:
                        g[3 * i + 1] = 1.0
                    else:
                        g[3 * i + 1] = -1.0
                    g[3 * i + 2] = -1.0
                    return g
                return f, jac
            f, j = make_wall(i, kind)
            cons.append({'type': 'ineq', 'fun': f, 'jac': j})

    for i in range(n):
        for j in range(i + 1, n):
            def make_pair(i, j):
                def f(v):
                    X = v.reshape(n, 3)
                    dx = X[i, 0] - X[j, 0]
                    dy = X[i, 1] - X[j, 1]
                    return dx * dx + dy * dy - (X[i, 2] + X[j, 2]) ** 2
                def jac(v):
                    X = v.reshape(n, 3)
                    dx = X[i, 0] - X[j, 0]
                    dy = X[i, 1] - X[j, 1]
                    s = X[i, 2] + X[j, 2]
                    g = np.zeros(3 * n)
                    g[3 * i] = 2.0 * dx
                    g[3 * i + 1] = 2.0 * dy
                    g[3 * i + 2] = -2.0 * s
                    g[3 * j] = -2.0 * dx
                    g[3 * j + 1] = -2.0 * dy
                    g[3 * j + 2] = -2.0 * s
                    return g
                return f, jac
            f, j = make_pair(i, j)
            cons.append({'type': 'ineq', 'fun': f, 'jac': j})

    v0 = x_init.reshape(-1).copy()
    v0[2::3] = np.clip(v0[2::3], 1e-4, 0.5)
    v0[0::3] = np.clip(v0[0::3], 0.0, 1.0)
    v0[1::3] = np.clip(v0[1::3], 0.0, 1.0)
    try:
        res = minimize(obj, v0, jac=obj_grad, method='SLSQP',
                       bounds=bounds, constraints=cons,
                       options={'maxiter': maxiter, 'ftol': 1e-14})
        return res.x.reshape(n, 3)
    except Exception:
        return x_init


def _score(x):
    return float(np.sum(x[:, 2]))


def _dual_gradient(centers, n, steps, step0, deadline, t0):
    """Projected gradient ascent on centers using LP duals as subgradient."""
    centers = np.clip(np.array(centers, dtype=float).reshape(n, 2), 0.0, 1.0)
    radii, grad = _lp_with_duals(centers, n)
    if radii is None:
        return None, -1.0
    cur_val = float(np.sum(radii))
    step = step0
    for s in range(steps):
        if time.process_time() - t0 > deadline:
            break
        if s % 10 == 0 or grad is None:
            radii, grad = _lp_with_duals(centers, n)
            if radii is None:
                break
            cur_val = float(np.sum(radii))
        if grad is None:
            break
        gn = np.linalg.norm(grad)
        if gn < 1e-12:
            break
        # backtracking line search
        accepted = False
        for _ in range(8):
            newc = np.clip(centers + step * grad, 0.0, 1.0)
            nr, _ = _lp_with_duals(newc, n)
            if nr is None:
                step *= 0.5
                continue
            nv = float(np.sum(nr))
            if nv > cur_val + 1e-12:
                centers = newc
                cur_val = nv
                radii = nr
                step *= 1.3
                accepted = True
                break
            else:
                step *= 0.5
        if not accepted:
            if step < 1e-6:
                break
        if step > 0.5:
            step = 0.5
    radii, _ = _lp_with_duals(centers, n)
    if radii is None:
        return None, -1.0
    return centers, float(np.sum(radii))


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 32
    rng = np.random.default_rng(12345)
    HARD = min(8.5, 0.85 * budget_seconds)

    def elapsed():
        return time.process_time() - t0

    best = None
    best_score = -1.0

    if start is not None:
        try:
            s = _feasible_fix(start)
            best = s
            best_score = _score(s)
        except Exception:
            pass

