        pol = _slsqp_polish(best, n, maxiter=2000, deadline=HARD, t0=t0)
        pol = _feasible_fix(pol)
        if _score(pol) > best_score:
            best_score = _score(pol)
            best = pol

    # Phase 2: dual gradient ascent from best and perturbations
    if best is not None:
        base_centers = best[:, :2].copy()
        starts = [base_centers]
        for _ in range(20):
            if elapsed() > 0.6 * HARD:
                break
            sc = rng.uniform(0.005, 0.03)
            pert = base_centers + rng.normal(0, sc, base_centers.shape)
            starts.append(np.clip(pert, 0.0, 1.0))
