                                            deadline=0.7 * HARD, t0=t0)
                if c_out is None:
                    continue
                cand = make_cand(c_out)
                if _score(cand) > best_score:
                    best_score = _score(cand)
                    best = cand
            except Exception:
                pass

    # Phase 3: SLSQP polish best
    if best is not None and elapsed() < HARD:
        pol = _slsqp_polish(best, n, maxiter=3000, deadline=HARD, t0=t0)
        pol = _feasible_fix(pol)
        if _score(pol) > best_score:
            best_score = _score(pol)
            best = pol

    # Phase 4: random perturbations + SLSQP if time remains
    if best is not None:
        while elapsed() < HARD:
            try:
                cand = best.copy()
                scale = rng.uniform(0.01, 0.05)
                cand[:, 0] += rng.normal(0, scale, n)
                cand[:, 1] += rng.normal(0, scale, n)
                cand = _feasible_fix(cand)
                cand = make_cand(cand[:, :2])
                pol = _slsqp_polish(cand, n, maxiter=2000, deadline=HARD, t0=t0)
                pol = _feasible_fix(pol)
                if _score(pol) > best_score:
                    best_score = _score(pol)
                    best = pol
            except Exception:
                break

    if best is None:
        if start is not None:
            return _feasible_fix(start)
        centers = np.array(grid_init(6)[:n])
        return _feasible_fix(np.column_stack([centers, np.full(n, 0.07)]))

    return best

import numpy as np
import time
from scipy.optimize import minimize, linprog


def _feasible_fix(x):
    x = np.array(x, dtype=float).reshape(-1, 3)
    n = len(x)
    x[:, 2] = np.maximum(x[:, 2], 1e-6)
    x[:, 0] = np.clip(x[:, 0], x[:, 2], 1.0 - x[:, 2])
    x[:, 1] = np.clip(x[:, 1], x[:, 2], 1.0 - x[:, 2])
    for _ in range(300):
        bad = False
        for i in range(n):
            for j in range(i + 1, n):
                d = np.hypot(x[i, 0] - x[j, 0], x[i, 1] - x[j, 1])
                s = x[i, 2] + x[j, 2]
                if d < s + 1e-12:
                    bad = True
                    excess = s - d + 1e-9
                    x[i, 2] -= excess / 2
                    x[j, 2] -= excess / 2
        x[:, 2] = np.maximum(x[:, 2], 1e-6)
        x[:, 0] = np.clip(x[:, 0], x[:, 2], 1.0 - x[:, 2])
        x[:, 1] = np.clip(x[:, 1], x[:, 2], 1.0 - x[:, 2])
        if not bad:
            break
    x[:, 2] *= (1.0 - 1e-9)
    x[:, 2] = np.maximum(x[:, 2], 1e-6)
    return x


def _lp_radii(centers, n):
    c = -np.ones(n)
    A_ub = []
    b_ub = []
    for i in range(n):
        for w in (centers[i, 0], 1.0 - centers[i, 0], centers[i, 1], 1.0 - centers[i, 1]):
            row = np.zeros(n)
            row[i] = 1.0
            A_ub.append(row)
            b_ub.append(max(w, 0.0))
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(centers[i, 0] - centers[j, 0], centers[i, 1] - centers[j, 1])
            row = np.zeros(n)
            row[i] = 1.0
            row[j] = 1.0
            A_ub.append(row)
            b_ub.append(max(d, 0.0))
    bounds = [(1e-6, None)] * n
    try:
        res = linprog(c, A_ub=np.array(A_ub), b_ub=np.array(b_ub),
                      bounds=bounds, method='highs')
        if res.success:
            return np.maximum(res.x, 1e-6)
    except Exception:
        pass
    return None


def _build_constraints(n):
    cons = []
    for i in range(n):
        for kind in range(4):
            def make_wall(i, kind):
                def f(v):
                    X = v.reshape(n, 3)
                    if kind == 0:
                        return X[i, 0] - X[i, 2]
                    elif kind == 1:
                        return 1.0 - X[i, 0] - X[i, 2]
                    elif kind == 2:
                        return X[i, 1] - X[i, 2]
                    else:
                        return 1.0 - X[i, 1] - X[i, 2]
                def jac(v):
                    g = np.zeros(3 * n)
                    if kind == 0:
                        g[3 * i] = 1.0
                    elif kind == 1:
                        g[3 * i] = -1.0
                    elif kind == 2:
                        g[3 * i + 1] = 1.0
                    else:
                        g[3 * i + 1] = -1.0
                    g[3 * i + 2] = -1.0
                    return g
                return f, jac
            f, j = make_wall(i, kind)
            cons.append({'type': 'ineq', 'fun': f, 'jac': j})

    for i in range(n):
        for j in range(i + 1, n):
            def make_pair(i, j):
                def f(v):
                    X = v.reshape(n, 3)
                    dx = X[i, 0] - X[j, 0]
                    dy = X[i, 1] - X[j, 1]
                    return dx * dx + dy * dy - (X[i, 2] + X[j, 2]) ** 2
                def jac(v):
                    X = v.reshape(n, 3)
                    dx = X[i, 0] - X[j, 0]
                    dy = X[i, 1] - X[j, 1]
                    s = X[i, 2] + X[j, 2]
                    g = np.zeros(3 * n)
                    g[3 * i] = 2.0 * dx
                    g[3 * i + 1] = 2.0 * dy
                    g[3 * i + 2] = -2.0 * s
                    g[3 * j] = -2.0 * dx
                    g[3 * j + 1] = -2.0 * dy
                    g[3 * j + 2] = -2.0 * s
                    return g
                return f, jac
            f, j = make_pair(i, j)
            cons.append({'type': 'ineq', 'fun': f, 'jac': j})
    return cons


def _slsqp_polish(x_init, n, maxiter, deadline, t0):
    def obj(v):
        return -np.sum(v[2::3])

    def obj_grad(v):
        g = np.zeros_like(v)
        g[2::3] = -1.0
        return g

    bounds = []
    for i in range(n):
        bounds.append((0.0, 1.0))
        bounds.append((0.0, 1.0))
        bounds.append((1e-4, 0.5))

    cons = _build_constraints(n)

    v0 = x_init.reshape(-1).copy()
    v0[2::3] = np.clip(v0[2::3], 1e-4, 0.5)
    v0[0::3] = np.clip(v0[0::3], 0.0, 1.0)
    v0[1::3] = np.clip(v0[1::3], 0.0, 1.0)
    try:
        res = minimize(obj, v0, jac=obj_grad, method='SLSQP',
                       bounds=bounds, constraints=cons,
                       options={'maxiter': maxiter, 'ftol': 1e-14})
        return res.x.reshape(n, 3)
    except Exception:
        return x_init


def _trust_polish(x_init, n, maxiter, deadline, t0):
    def obj(v):
        return -np.sum(v[2::3])

    def obj_grad(v):
        g = np.zeros_like(v)
