    v0[0::3] = np.clip(v0[0::3], 0.0, 1.0)
    v0[1::3] = np.clip(v0[1::3], 0.0, 1.0)
    try:
        res = minimize(obj, v0, jac=obj_grad, method='trust-constr',
                       bounds=bounds, constraints=cons,
                       options={'maxiter': maxiter, 'gtol': 1e-12,
                                'xtol': 1e-12, 'barrier_tol': 1e-12,
                                'verbose': 0})
        return res.x.reshape(n, 3)
    except Exception:
        return x_init


