def _compress(x, n, inflate, iters, rng):
    """Inflate radii, resolve overlaps by moving centers, then re-solve LP."""
    c = x.copy()
    c[:, 2] = c[:, 2] * inflate
    # keep centers inside [r, 1-r]
    c[:, 0] = np.clip(c[:, 0], c[:, 2], 1.0 - c[:, 2])
    c[:, 1] = np.clip(c[:, 1], c[:, 2], 1.0 - c[:, 2])
    for it in range(iters):
        moved = False
        # pairwise separation
        for i in range(n):
            for j in range(i + 1, n):
                dx = c[j, 0] - c[i, 0]
                dy = c[j, 1] - c[i, 1]
                d = np.hypot(dx, dy)
                s = c[i, 2] + c[j, 2]
                if d < s:
                    if d < 1e-12:
                        # random direction
                        ang = rng.uniform(0, 2 * np.pi)
                        dx, dy, d = np.cos(ang), np.sin(ang), 1.0
                    overlap = s - d
                    ux, uy = dx / d, dy / d
                    shift = overlap * 0.5
                    c[i, 0] -= ux * shift
                    c[i, 1] -= uy * shift
                    c[j, 0] += ux * shift
                    c[j, 1] += uy * shift
                    moved = True
        # wall pushes
        for i in range(n):
            r = c[i, 2]
            if c[i, 0] < r:
                c[i, 0] = r
                moved = True
            if c[i, 0] > 1.0 - r:
                c[i, 0] = 1.0 - r
                moved = True
            if c[i, 1] < r:
                c[i, 1] = r
                moved = True
            if c[i, 1] > 1.0 - r:
                c[i, 1] = 1.0 - r
                moved = True
        if not moved:
            break
    # re-solve LP for radii given new centers
    rlp = _lp_radii(c[:, :2], n)
    if rlp is None:
        return _feasible_fix(c)
    out = np.column_stack([c[:, 0], c[:, 1], rlp])
    return _feasible_fix(out)


