                best_score = _score(pol)
                best = pol

    # Polish the start first with exact Jacobians
    if best is not None and elapsed() < HARD:
        pol = _slsqp_polish(best, n, maxiter=2000, deadline=HARD, t0=t0)
        pol = _feasible_fix(pol)
        if _score(pol) > best_score:
            best_score = _score(pol)
            best = pol

    for idx, centers in enumerate(inits):
        if elapsed() > 0.45 * budget_seconds or elapsed() > HARD:
            break
        try:
            cand = make_cand(centers)
            consider(cand, 0.45)
        except Exception:
            pass

    # Compression-based basin hopping
    if best is not None:
        inflate_levels = [1.02, 1.01, 1.03, 1.015, 1.005]
        li = 0
        while elapsed() < HARD:
            try:
                inflate = inflate_levels[li % len(inflate_levels)]
                li += 1
                cand = _compress(best, n, inflate, 200, rng)
                if _score(cand) > best_score:
                    pol = _slsqp_polish(cand, n, maxiter=2000, deadline=HARD, t0=t0)
                    pol = _feasible_fix(pol)
                    if _score(pol) > best_score:
                        best_score = _score(pol)
                        best = pol
                    else:
                        best_score = _score(cand)
                        best = cand
                else:
                    # try small perturbation + compress
                    cand2 = best.copy()
                    scale = rng.uniform(0.005, 0.03)
                    cand2[:, 0] += rng.normal(0, scale, n)
                    cand2[:, 1] += rng.normal(0, scale, n)
                    cand2 = _feasible_fix(cand2)
                    cand2 = _compress(cand2, n, inflate, 200, rng)
                    if _score(cand2) > best_score:
                        pol = _slsqp_polish(cand2, n, maxiter=2000, deadline=HARD, t0=t0)
                        pol = _feasible_fix(pol)
                        if _score(pol) > best_score:
                            best_score = _score(pol)
                            best = pol
            except Exception:
                break

    if best is None:
        if start is not None:
            return _feasible_fix(start)
        centers = np.array(grid_init(6)[:n])
        return _feasible_fix(np.column_stack([centers, np.full(n, 0.07)]))

    return best

import numpy as np
import time
from scipy.optimize import minimize, linprog


def _feasible_fix(x):
    x = np.array(x, dtype=float).reshape(-1, 3)
    n = len(x)
    x[:, 2] = np.maximum(x[:, 2], 1e-6)
    x[:, 0] = np.clip(x[:, 0], x[:, 2], 1.0 - x[:, 2])
    x[:, 1] = np.clip(x[:, 1], x[:, 2], 1.0 - x[:, 2])
    for _ in range(300):
        bad = False
        for i in range(n):
            for j in range(i + 1, n):
                d = np.hypot(x[i, 0] - x[j, 0], x[i, 1] - x[j, 1])
                s = x[i, 2] + x[j, 2]
                if d < s + 1e-12:
                    bad = True
                    excess = s - d + 1e-9
                    x[i, 2] -= excess / 2
                    x[j, 2] -= excess / 2
        x[:, 2] = np.maximum(x[:, 2], 1e-6)
        x[:, 0] = np.clip(x[:, 0], x[:, 2], 1.0 - x[:, 2])
        x[:, 1] = np.clip(x[:, 1], x[:, 2], 1.0 - x[:, 2])
        if not bad:
            break
    x[:, 2] *= (1.0 - 1e-9)
    x[:, 2] = np.maximum(x[:, 2], 1e-6)
    return x


def _lp_radii(centers, n):
    c = -np.ones(n)
    A_ub = []
    b_ub = []
    for i in range(n):
        for w in (centers[i, 0], 1.0 - centers[i, 0],
                  centers[i, 1], 1.0 - centers[i, 1]):
            row = np.zeros(n)
            row[i] = 1.0
            A_ub.append(row)
            b_ub.append(max(w, 0.0))
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(centers[i, 0] - centers[j, 0],
                         centers[i, 1] - centers[j, 1])
            row = np.zeros(n)
            row[i] = 1.0
            row[j] = 1.0
            A_ub.append(row)
            b_ub.append(max(d, 0.0))
    bounds = [(1e-6, None)] * n
    try:
        res = linprog(c, A_ub=np.array(A_ub), b_ub=np.array(b_ub),
                      bounds=bounds, method='highs')
        if res.success:
            return np.maximum(res.x, 1e-6)
    except Exception:
        pass
    return None


def _slsqp_polish(x_init, n, maxiter):
    def obj(v):
        return -np.sum(v[2::3])

    def obj_grad(v):
        g = np.zeros_like(v)
        g[2::3] = -1.0
        return g

    bounds = []
    for i in range(n):
        bounds.append((0.0, 1.0))
        bounds.append((0.0, 1.0))
        bounds.append((1e-4, 0.5))

    cons = []
    for i in range(n):
        for kind in range(4):
            def make_wall(i, kind):
                def f(v):
                    X = v.reshape(n, 3)
                    if kind == 0:
                        return X[i, 0] - X[i, 2]
                    elif kind == 1:
                        return 1.0 - X[i, 0] - X[i, 2]
                    elif kind == 2:
                        return X[i, 1] - X[i, 2]
                    else:
                        return 1.0 - X[i, 1] - X[i, 2]
                def jac(v):
                    g = np.zeros(3 * n)
                    if kind == 0:
                        g[3 * i] = 1.0
                    elif kind == 1:
                        g[3 * i] = -1.0
                    elif kind == 2:
                        g[3 * i + 1] = 1.0
                    else:
                        g[3 * i + 1] = -1.0
                    g[3 * i + 2] = -1.0
                    return g
                return f, jac
            f, j = make_wall(i, kind)
            cons.append({'type': 'ineq', 'fun': f, 'jac': j})

    for i in range(n):
        for j in range(i + 1, n):
            def make_pair(i, j):
                def f(v):
                    X = v.reshape(n, 3)
                    dx = X[i, 0] - X[j, 0]
                    dy = X[i, 1] - X[j, 1]
                    return dx * dx + dy * dy - (X[i, 2] + X[j, 2]) ** 2
                def jac(v):
                    X = v.reshape(n, 3)
                    dx = X[i, 0] - X[j, 0]
                    dy = X[i, 1] - X[j, 1]
                    s = X[i, 2] + X[j, 2]
                    g = np.zeros(3 * n)
                    g[3 * i] = 2.0 * dx
                    g[3 * i + 1] = 2.0 * dy
                    g[3 * i + 2] = -2.0 * s
                    g[3 * j] = -2.0 * dx
                    g[3 * j + 1] = -2.0 * dy
                    g[3 * j + 2] = -2.0 * s
                    return g
                return f, jac
            f, j = make_pair(i, j)
            cons.append({'type': 'ineq', 'fun': f, 'jac': j})

    v0 = x_init.reshape(-1).copy()
    v0[2::3] = np.clip(v0[2::3], 1e-4, 0.5)
    v0[0::3] = np.clip(v0[0::3], 0.0, 1.0)
    v0[1::3] = np.clip(v0[1::3], 0.0, 1.0)
    try:
        res = minimize(obj, v0, jac=obj_grad, method='SLSQP',
                       bounds=bounds, constraints=cons,
                       options={'maxiter': maxiter, 'ftol': 1e-14})
        return res.x.reshape(n, 3)
    except Exception:
        return x_init


def _score(x):
    return float(np.sum(x[:, 2]))


def _resolve_pairs(x, inflate, iters, rng):
    """Inflate radii and push centers apart to remove overlaps."""
    c = x.copy()
    n = len(c)
    c[:, 2] = np.minimum(c[:, 2] * inflate, 0.49)
    c[:, 0] = np.clip(c[:, 0], c[:, 2], 1.0 - c[:, 2])
    c[:, 1] = np.clip(c[:, 1], c[:, 2], 1.0 - c[:, 2])
    for _ in range(iters):
        moved = False
        for i in range(n):
            for j in range(i + 1, n):
                dx = c[j, 0] - c[i, 0]
                dy = c[j, 1] - c[i, 1]
                d = np.hypot(dx, dy)
                s = c[i, 2] + c[j, 2]
                if d < s:
                    if d < 1e-12:
                        ang = rng.uniform(0, 2 * np.pi)
                        dx, dy, d = np.cos(ang), np.sin(ang), 1.0
                    overlap = s - d
                    ux, uy = dx / d, dy / d
                    shift = overlap * 0.5 * 1.02
                    c[i, 0] -= ux * shift
                    c[i, 1] -= uy * shift
                    c[j, 0] += ux * shift
                    c[j, 1] += uy * shift
                    moved = True
        for i in range(n):
            r = c[i, 2]
            if c[i, 0] < r:
                c[i, 0] = r
                moved = True
            if c[i, 0] > 1.0 - r:
                c[i, 0] = 1.0 - r
                moved = True
            if c[i, 1] < r:
                c[i, 1] = r
                moved = True
            if c[i, 1] > 1.0 - r:
                c[i, 1] = 1.0 - r
                moved = True
        if not moved:
            break
    return c


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 32
    rng = np.random.default_rng(987654321)
    # generous hard cap, but leave margin
    HARD = min(budget_seconds - 0.9, 0.9 * budget_seconds)

    def elapsed():
        return time.process_time() - t0

    best = None
    best_score = -1.0

    if start is not None:
        try:
            s = _feasible_fix(start)
            best = s
            best_score = _score(s)
        except Exception:
            pass

    # Always re-polish start with SLSQP for extra gain
    if best is not None and elapsed() < HARD * 0.35:
        try:
            pol = _slsqp_polish(best, n, maxiter=2000)
            pol = _feasible_fix(pol)
            if _score(pol) > best_score:
                best, best_score = pol, _score(pol)
        except Exception:
            pass

    def consider(cand):
        nonlocal best, best_score
        cand = _feasible_fix(cand)
        sc = _score(cand)
        if sc > best_score:
            best, best_score = cand, sc
            return True
        return False

    # Iterated local search: perturb best, resolve via "inflation + push" and LP
    stall = 0
    while best is not None and elapsed() < HARD:
        try:
            # mix perturbations: some small, some larger
            if stall < 3:
                scale = rng.uniform(0.005, 0.02)
            else:
                scale = rng.uniform(0.02, 0.06)

            cand = best.copy()
            # perturb subset of circles
            k = rng.integers(max(2, n // 6), max(4, n // 2))
            idx = rng.choice(n, size=min(k, n), replace=False)
            cand[idx, 0] += rng.normal(0, scale, len(idx))
            cand[idx, 1] += rng.normal(0, scale, len(idx))

            # aggressive inflation to escape local optima
            inflate = rng.uniform(1.02, 1.10)
            cand = _resolve_pairs(cand, inflate, iters=200, rng=rng)

            # re-solve LP radii given new centers
            rlp = _lp_radii(cand[:, :2], n)
            if rlp is None:
                continue
            newc = np.column_stack([cand[:, 0], cand[:, 1], rlp])

            # SLSQP polish
            pol = _slsqp_polish(newc, n, maxiter=1500)
            pol = _feasible_fix(pol)

            if consider(pol):
                stall = 0
            else:
                stall += 1
        except Exception:
            break

    if best is None:
        # fallback: hexagon-ish grid
        pts = []
        for j in range(6):
            y = (j + 0.5) / 6
            off = 0.5 if j % 2 == 0 else 1.0
            for i in range(6 if j % 2 == 0 else 5):
                pts.append(((i + off) / 6, y))
        pts = np.array(pts[:n])
        r = _lp_radii(pts, n)
        if r is None:
            r = np.full(n, 0.05)
        best = _feasible_fix(np.column_stack([pts, r]))

    return _feasible_fix(best)

