                    elif kind == 1:
                        g[3 * i] = -1.0
                    elif kind == 2:
                        g[3 * i + 1] = 1.0
                    else:
                        g[3 * i + 1] = -1.0
                    g[3 * i + 2] = -1.0
                    return g
                return f, jac
            f, j = make_wall(i, kind)
