def _score(x):
    return float(np.sum(x[:, 2]))


def _compress(x, n, inflate, iters, rng):
    """Inflate radii, resolve overlaps by pushing centers apart, re-solve LP."""
    c = x.copy()
    c[:, 2] = np.maximum(c[:, 2] * inflate, 1e-6)
    c[:, 0] = np.clip(c[:, 0], c[:, 2], 1.0 - c[:, 2])
    c[:, 1] = np.clip(c[:, 1], c[:, 2], 1.0 - c[:, 2])
    for _ in range(iters):
        moved = False
        for i in range(n):
            for j in range(i + 1, n):
                dx = c[j, 0] - c[i, 0]
                dy = c[j, 1] - c[i, 1]
                d = np.hypot(dx, dy)
                s = c[i, 2] + c[j, 2]
                if d < s:
                    if d < 1e-12:
                        ang = rng.uniform(0, 2 * np.pi)
                        dx, dy, d = np.cos(ang), np.sin(ang), 1.0
                    overlap = s - d
                    ux, uy = dx / d, dy / d
                    shift = overlap * 0.5
                    c[i, 0] -= ux * shift
                    c[i, 1] -= uy * shift
                    c[j, 0] += ux * shift
                    c[j, 1] += uy * shift
                    moved = True
        for i in range(n):
            r = c[i, 2]
            if c[i, 0] < r:
                c[i, 0] = r; moved = True
            if c[i, 0] > 1.0 - r:
                c[i, 0] = 1.0 - r; moved = True
            if c[i, 1] < r:
                c[i, 1] = r; moved = True
            if c[i, 1] > 1.0 - r:
                c[i, 1] = 1.0 - r; moved = True
        if not moved:
            break
    rlp = _lp_radii(c[:, :2], n)
    if rlp is None:
        return _feasible_fix(c)
    out = np.column_stack([c[:, 0], c[:, 1], rlp])
    return _feasible_fix(out)


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 32
    rng = np.random.default_rng(987654321)
    HARD = min(budget_seconds * 0.80, budget_seconds - 1.5)

    def elapsed():
        return time.process_time() - t0

    best = None
    best_score = -1.0

    def consider(cand):
        nonlocal best, best_score
        cand = _feasible_fix(cand)
        s = _score(cand)
        if s > best_score:
            best_score = s
            best = cand
            return True
        return False

    if start is not None:
        try:
            consider(_feasible_fix(start))
        except Exception:
            pass

    def hex_init(rows, cols):
        pts = []
        for j in range(rows):
            y = (j + 0.5) / rows
            off = 0.5 if j % 2 == 0 else 1.0
            cnt = cols if j % 2 == 0 else cols - 1
            for i in range(cnt):
                x = (i + off) / cols
                pts.append((x, y))
        return pts

    def grid_init(g):
        pts = []
        for j in range(g):
            for i in range(g):
                pts.append(((i + 0.5) / g, (j + 0.5) / g))
        return pts

    inits = []
    for rows, cols in [(6, 6), (5, 7), (7, 5), (6, 7), (8, 4), (4, 8)]:
        p = hex_init(rows, cols)
        if len(p) >= n:
            inits.append(np.array(p[:n]))
    for g in (6, 7):
        p = grid_init(g)
        if len(p) >= n:
            inits.append(np.array(p[:n]))

    def make_cand(centers):
        rlp = _lp_radii(centers, n)
        if rlp is None:
            rlp = np.full(n, 0.05)
        return _feasible_fix(np.column_stack([centers, rlp]))

    # Polish start
    if best is not None and elapsed() < HARD:
        pol = _feasible_fix(_slsqp_polish(best, n, maxiter=2000))
        consider(pol)

    # Try structured inits (only if time)
    for centers in inits:
        if elapsed() > 0.35 * budget_seconds:
            break
        try:
            cand = make_cand(centers)
            consider(cand)
            if elapsed() < 0.4 * budget_seconds:
                pol = _feasible_fix(_slsqp_polish(cand, n, maxiter=1200))
                consider(pol)
        except Exception:
            pass

    # Main improvement loop: compress-around-best + polish
    while best is not None and elapsed() < HARD:
        try:
            base = best.copy()
            # Choose a perturbation: sometimes compress (inflate radii),
            # sometimes jitter centers, sometimes both.
            mode = rng.integers(0, 3)
            if mode == 0:
                inflate = rng.uniform(1.01, 1.06)
                cand = _compress(base, n, inflate, 200, rng)
            elif mode == 1:
                base[:, 0] += rng.normal(0, rng.uniform(0.005, 0.03), n)
                base[:, 1] += rng.normal(0, rng.uniform(0.005, 0.03), n)
                cand = make_cand(base[:, :2])
            else:
                inflate = rng.uniform(1.02, 1.08)
                base = _compress(base, n, inflate, 200, rng)
                base[:, 0] += rng.normal(0, rng.uniform(0.003, 0.02), n)
                base[:, 1] += rng.normal(0, rng.uniform(0.003, 0.02), n)
                cand = make_cand(base[:, :2])

            if elapsed() < HARD - 0.4:
                pol = _feasible_fix(_slsqp_polish(cand, n, maxiter=1500))
                if consider(pol):
                    continue
            consider(cand)
        except Exception:
            break

    if best is None:
        if start is not None:
            return _feasible_fix(start)
        p = hex_init(6, 6)
        return make_cand(np.array(p[:n]))

    return best

import numpy as np
import time
from scipy.optimize import minimize, linprog


def _feasible_fix(x, n):
    x = np.array(x, dtype=float).reshape(n, 3)
    x[:, 2] = np.maximum(x[:, 2], 1e-6)
    x[:, 0] = np.clip(x[:, 0], x[:, 2], 1.0 - x[:, 2])
    x[:, 1] = np.clip(x[:, 1], x[:, 2], 1.0 - x[:, 2])
    for _ in range(100):
        changed = False
        for i in range(n):
            for j in range(i + 1, n):
                dx = x[i, 0] - x[j, 0]
                dy = x[i, 1] - x[j, 1]
                d = np.hypot(dx, dy)
                s = x[i, 2] + x[j, 2]
                if d < s:
                    changed = True
                    excess = s - d + 1e-11
                    x[i, 2] -= excess / 2
                    x[j, 2] -= excess / 2
        x[:, 2] = np.maximum(x[:, 2], 1e-6)
        x[:, 0] = np.clip(x[:, 0], x[:, 2], 1.0 - x[:, 2])
        x[:, 1] = np.clip(x[:, 1], x[:, 2], 1.0 - x[:, 2])
        if not changed:
            break
    x[:, 2] *= (1.0 - 1e-9)
    return x


def _lp_radii(centers, n):
    c = -np.ones(n)
    A_ub = []
    b_ub = []
    for i in range(n):
        for w in (centers[i, 0], 1.0 - centers[i, 0],
                  centers[i, 1], 1.0 - centers[i, 1]):
            row = np.zeros(n)
            row[i] = 1.0
            A_ub.append(row)
            b_ub.append(max(w, 0.0))
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(centers[i, 0] - centers[j, 0],
                         centers[i, 1] - centers[j, 1])
            row = np.zeros(n)
            row[i] = 1.0
            row[j] = 1.0
            A_ub.append(row)
            b_ub.append(max(d, 0.0))
    bounds = [(1e-6, None)] * n
    try:
        res = linprog(c, A_ub=np.array(A_ub), b_ub=np.array(b_ub),
                      bounds=bounds, method='highs')
        if res.success:
            return np.maximum(res.x, 1e-6)
    except Exception:
        pass
    return None


def _slsqp_polish(x_init, n, maxiter):
    def obj(v):
        return -np.sum(v[2::3])

    def obj_grad(v):
        g = np.zeros_like(v)
        g[2::3] = -1.0
        return g

    bounds = []
    for i in range(n):
        bounds.append((0.0, 1.0))
        bounds.append((0.0, 1.0))
        bounds.append((1e-4, 0.5))

    cons = []
    for i in range(n):
        for kind in range(4):
            def make_wall(i, kind):
                def f(v):
                    X = v.reshape(n, 3)
                    if kind == 0:
                        return X[i, 0] - X[i, 2]
                    elif kind == 1:
                        return 1.0 - X[i, 0] - X[i, 2]
                    elif kind == 2:
                        return X[i, 1] - X[i, 2]
                    else:
                        return 1.0 - X[i, 1] - X[i, 2]
                def jac(v):
                    g = np.zeros(3 * n)
                    if kind == 0:
                        g[3 * i] = 1.0
                    elif kind == 1:
                        g[3 * i] = -1.0
                    elif kind == 2:
                        g[3 * i + 1] = 1.0
                    else:
                        g[3 * i + 1] = -1.0
                    g[3 * i + 2] = -1.0
                    return g
                return f, jac
            f, j = make_wall(i, kind)
            cons.append({'type': 'ineq', 'fun': f, 'jac': j})

    for i in range(n):
        for j in range(i + 1, n):
            def make_pair(i, j):
                def f(v):
                    X = v.reshape(n, 3)
                    dx = X[i, 0] - X[j, 0]
                    dy = X[i, 1] - X[j, 1]
                    return dx * dx + dy * dy - (X[i, 2] + X[j, 2]) ** 2
                def jac(v):
                    X = v.reshape(n, 3)
                    dx = X[i, 0] - X[j, 0]
                    dy = X[i, 1] - X[j, 1]
                    s = X[i, 2] + X[j, 2]
                    g = np.zeros(3 * n)
                    g[3 * i] = 2.0 * dx
                    g[3 * i + 1] = 2.0 * dy
                    g[3 * i + 2] = -2.0 * s
                    g[3 * j] = -2.0 * dx
                    g[3 * j + 1] = -2.0 * dy
                    g[3 * j + 2] = -2.0 * s
                    return g
                return f, jac
            f, j = make_pair(i, j)
            cons.append({'type': 'ineq', 'fun': f, 'jac': j})

    v0 = x_init.reshape(-1).copy()
    v0[2::3] = np.clip(v0[2::3], 1e-4, 0.5)
    v0[0::3] = np.clip(v0[0::3], 0.0, 1.0)
    v0[1::3] = np.clip(v0[1::3], 0.0, 1.0)
    try:
        res = minimize(obj, v0, jac=obj_grad, method='SLSQP',
                       bounds=bounds, constraints=cons,
                       options={'maxiter': maxiter, 'ftol': 1e-14})
        return res.x.reshape(n, 3)
    except Exception:
        return x_init


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 32
    rng = np.random.default_rng(12345)
    HARD = min(budget_seconds * 0.82, budget_seconds - 1.2)

    def elapsed():
        return time.process_time() - t0

    best = None
    best_score = -1.0

    def score(x):
        return float(np.sum(x[:, 2]))

    if start is not None:
        try:
            s = _feasible_fix(start, n)
            best = s
            best_score = score(s)
        except Exception:
            pass

    def hex_init(rows, cols):
        pts = []
        for j in range(rows):
            y = (j + 0.5) / rows
            off = 0.5 if j % 2 == 0 else 1.0
            cnt = cols if j % 2 == 0 else cols - 1
            for i in range(cnt):
                x = (i + off) / cols
                pts.append((x, y))
        return pts

    def grid_init(g):
        pts = []
        for j in range(g):
            for i in range(g):
                pts.append(((i + 0.5) / g, (j + 0.5) / g))
        return pts

    inits = []
    for rows, cols in [(6, 6), (5, 7), (7, 5), (6, 7), (8, 4)]:
        p = hex_init(rows, cols)
        if len(p) >= n:
            inits.append(np.array(p[:n]))
    for g in (6, 7):
        p = grid_init(g)
        if len(p) >= n:
            inits.append(np.array(p[:n]))

    def make_cand(centers):
        rlp = _lp_radii(centers, n)
        if rlp is None:
            rlp = np.full(n, 0.05)
        c = np.column_stack([centers, rlp])
        return _feasible_fix(c, n)

    def consider(cand):
        nonlocal best, best_score
        cand = _feasible_fix(cand, n)
        if score(cand) > best_score:
            best_score = score(cand)
            best = cand

    # Polish the start first
    if best is not None and elapsed() < HARD:
        pol = _slsqp_polish(best, n, maxiter=1500)
        pol = _feasible_fix(pol, n)
        if score(pol) > best_score:
            best_score = score(pol)
            best = pol

    for centers in inits:
        if elapsed() > 0.5 * budget_seconds:
            break
        try:
            cand = make_cand(centers)
            consider(cand)
            if elapsed() < 0.5 * budget_seconds:
                pol = _slsqp_polish(cand, n, maxiter=1200)
                pol = _feasible_fix(pol, n)
                if score(pol) > best_score:
                    best_score = score(pol)
                    best = pol
        except Exception:
            pass

    # Random restarts / perturbations around best
    while best is not None and elapsed() < HARD:
        try:
            cand = best.copy()
            scale = rng.uniform(0.01, 0.05)
            cand[:, 0] += rng.normal(0, scale, n)
            cand[:, 1] += rng.normal(0, scale, n)
            cand = _feasible_fix(cand, n)
            newc = make_cand(cand[:, :2])
            pol = _slsqp_polish(newc, n, maxiter=1200)
            pol = _feasible_fix(pol, n)
            if score(pol) > best_score:
                best_score = score(pol)
                best = pol
        except Exception:
            break

    # Rattler relocation loop: for each circle, try a grid of candidate centers
    if best is not None:
        order = list(range(n))
        rng.shuffle(order)
        for i in order:
            if elapsed() > HARD:
                break
            try:
                others = np.delete(best, i, axis=0)
                gx = np.linspace(0.02, 0.98, 50)
                gy = np.linspace(0.02, 0.98, 50)
                best_center = best[i, :2].copy()
                best_val = -1.0
                # Evaluate LP value with circle i at each grid point
                for xv in gx:
                    if elapsed() > HARD:
                        break
                    for yv in gy:
                        centers = np.vstack([others[:, :2], [[xv, yv]]])
                        rlp = _lp_radii(centers, n)
                        if rlp is None:
                            continue
                        val = float(np.sum(rlp))
                        if val > best_val:
                            best_val = val
                            best_center = np.array([xv, yv])
                if best_val < 0:
                    continue
                cand = best.copy()
                cand[i, 0] = best_center[0]
                cand[i, 1] = best_center[1]
                cand = _feasible_fix(cand, n)
                pol = _slsqp_polish(cand, n, maxiter=800)
                pol = _feasible_fix(pol, n)
                if score(pol) > best_score + 1e-12:
                    best_score = score(pol)
                    best = pol
            except Exception:
                continue

    if best is None:
        if start is not None:
            return _feasible_fix(start, n)
        p = hex_init(6, 6)
        return make_cand(np.array(p[:n]))

    return best

import numpy as np
import time
from scipy.optimize import minimize, linprog, least_squares


