                       bounds=bounds, constraints=cons,
                       options={'maxiter': maxiter, 'ftol': 1e-14})
        return res.x.reshape(n, 3)
    except Exception:
        return x_init


def _kkt_newton(x, n):
    """Solve square KKT system on the active set with least_squares."""
    X = x.copy()
    tol = 1e-6
    # Build active set
    pairs = []
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(X[i, 0] - X[j, 0], X[i, 1] - X[j, 1])
            if d - (X[i, 2] + X[j, 2]) < tol:
                pairs.append((i, j))
    walls = []  # (i, kind) kind: 0=x-r>=0, 1=1-x-r>=0, 2=y-r>=0, 3=1-y-r>=0
    for i in range(n):
        if X[i, 0] - X[i, 2] < tol:
            walls.append((i, 0))
        if 1.0 - X[i, 0] - X[i, 2] < tol:
            walls.append((i, 1))
        if X[i, 1] - X[i, 2] < tol:
            walls.append((i, 2))
        if 1.0 - X[i, 1] - X[i, 2] < tol:
            walls.append((i, 3))

    m = len(pairs) + len(walls)
    # z = (x,y,r, lambda) ; size 3n + m
    # Equations: m active constraints + 3n stationarity + 1 normalization
    # Total = m + 3n + 1. Unknowns = 3n + m. Mismatch of 1 -> drop one equation.
    # Use: m active constraints + 3n stationarity, with one stationarity dropped
    # (since sum of stationarity equations is redundant given the others).
    # Actually: 3n stationarity + m constraints = 3n+m equations, 3n+m unknowns.
    # The stationarity for r gives sum lambda = n (since d(sum r)/dr_i = 1).
    # That's automatically consistent. The system is square.

    def resid(z):
        xx = z[0:3 * n].reshape(n, 3)
        lam = z[3 * n:]
        F = []
        # active constraints = 0
        for k, (i, j) in enumerate(pairs):
            d = np.hypot(xx[i, 0] - xx[j, 0], xx[i, 1] - xx[j, 1])
            F.append(d - (xx[i, 2] + xx[j, 2]))
        for k, (i, kind) in enumerate(walls):
            if kind == 0:
                F.append(xx[i, 0] - xx[i, 2])
            elif kind == 1:
                F.append(1.0 - xx[i, 0] - xx[i, 2])
            elif kind == 2:
                F.append(xx[i, 1] - xx[i, 2])
            else:
                F.append(1.0 - xx[i, 1] - xx[i, 2])
        # stationarity: grad(sum r) - sum_k lam_k grad(g_k) = 0
        # grad(sum r) = (0,0,1) per circle
        G = np.zeros((n, 3))
        G[:, 2] = 1.0
        for k, (i, j) in enumerate(pairs):
            lk = lam[k]
            dx = xx[i, 0] - xx[j, 0]
            dy = xx[i, 1] - xx[j, 1]
            d = np.hypot(dx, dy) + 1e-300
            ux = dx / d
            uy = dy / d
            # g = d - r_i - r_j, grad wrt i: (ux, uy, -1), wrt j: (-ux,-uy,-1)
            G[i, 0] -= lk * ux
            G[i, 1] -= lk * uy
            G[i, 2] -= lk * (-1.0)
            G[j, 0] -= lk * (-ux)
            G[j, 1] -= lk * (-uy)
            G[j, 2] -= lk * (-1.0)
        for k, (i, kind) in enumerate(walls):
            lk = lam[len(pairs) + k]
            if kind == 0:
                G[i, 0] -= lk * 1.0
                G[i, 2] -= lk * (-1.0)
            elif kind == 1:
                G[i, 0] -= lk * (-1.0)
                G[i, 2] -= lk * (-1.0)
            elif kind == 2:
                G[i, 1] -= lk * 1.0
                G[i, 2] -= lk * (-1.0)
            else:
                G[i, 1] -= lk * (-1.0)
                G[i, 2] -= lk * (-1.0)
        F.extend(G.reshape(-1).tolist())
        return np.array(F)

    z0 = np.concatenate([X.reshape(-1), np.full(m, 0.1)])
    try:
        res = least_squares(resid, z0, method='lm',
                            xtol=1e-15, ftol=1e-15, gtol=1e-15,
                            max_nfev=2000)
        z = res.x
        Xn = z[0:3 * n].reshape(n, 3)
        r = resid(z)
        maxres = float(np.max(np.abs(r))) if r.size else 0.0
        return Xn, maxres
    except Exception:
        return None, 1e9


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 32
    rng = np.random.default_rng(12345)
    HARD = min(budget_seconds * 0.82, budget_seconds - 1.2)

    def elapsed():
        return time.process_time() - t0

    best = None
    best_score = -1.0

    def score(x):
        return float(np.sum(x[:, 2]))

    if start is not None:
        try:
            s = _feasible_fix(start, n)
            best = s
            best_score = score(s)
        except Exception:
            pass

    def hex_init(rows, cols):
        pts = []
        for j in range(rows):
            y = (j + 0.5) / rows
            off = 0.5 if j % 2 == 0 else 1.0
            cnt = cols if j % 2 == 0 else cols - 1
            for i in range(cnt):
                x = (i + off) / cols
                pts.append((x, y))
        return pts

    def grid_init(g):
        pts = []
        for j in range(g):
            for i in range(g):
                pts.append(((i + 0.5) / g, (j + 0.5) / g))
        return pts

    inits = []
    for rows, cols in [(6, 6), (5, 7), (7, 5), (6, 7), (8, 4)]:
        p = hex_init(rows, cols)
        if len(p) >= n:
            inits.append(np.array(p[:n]))
    for g in (6, 7):
        p = grid_init(g)
        if len(p) >= n:
            inits.append(np.array(p[:n]))

    def make_cand(centers):
        rlp = _lp_radii(centers, n)
        if rlp is None:
            rlp = np.full(n, 0.05)
        c = np.column_stack([centers, rlp])
        return _feasible_fix(c, n)

    def consider(cand):
        nonlocal best, best_score
        cand = _feasible_fix(cand, n)
        if score(cand) > best_score:
            best_score = score(cand)
            best = cand

    # Polish the start first
    if best is not None and elapsed() < HARD:
        pol = _slsqp_polish(best, n, maxiter=1500)
        pol = _feasible_fix(pol, n)
        if score(pol) > best_score:
            best_score = score(pol)
            best = pol

    for centers in inits:
        if elapsed() > 0.5 * budget_seconds:
            break
        try:
            cand = make_cand(centers)
            consider(cand)
            if elapsed() < 0.5 * budget_seconds:
                pol = _slsqp_polish(cand, n, maxiter=1200)
                pol = _feasible_fix(pol, n)
                if score(pol) > best_score:
                    best_score = score(pol)
                    best = pol
        except Exception:
            pass

    # Random restarts / perturbations around best
    while best is not None and elapsed() < HARD:
        try:
            cand = best.copy()
            scale = rng.uniform(0.01, 0.05)
            cand[:, 0] += rng.normal(0, scale, n)
            cand[:, 1] += rng.normal(0, scale, n)
            cand = _feasible_fix(cand, n)
            newc = make_cand(cand[:, :2])
            pol = _slsqp_polish(newc, n, maxiter=1200)
            pol = _feasible_fix(pol, n)
            if score(pol) > best_score:
                best_score = score(pol)
                best = pol
        except Exception:
            break

    if best is None:
        if start is not None:
            return _feasible_fix(start, n)
        p = hex_init(6, 6)
        return make_cand(np.array(p[:n]))

    # KKT Newton polish on the active set
    if elapsed() < HARD:
        try:
            Xn, maxres = _kkt_newton(best, n)
            if Xn is not None and maxres < 1e-12:
                Xn = _feasible_fix(Xn, n)
                if score(Xn) >= best_score - 1e-12:
                    if score(Xn) > best_score:
