                d = np.hypot(x[i, 0] - x[j, 0], x[i, 1] - x[j, 1])
                s = x[i, 2] + x[j, 2]
                if d < s + safety:
                    excess = s - d + safety
                    x[i, 2] -= excess * 0.5
                    x[j, 2] -= excess * 0.5
                    bad = True
        x[:, 2] = np.maximum(x[:, 2], 1e-6)
        x[:, 0] = np.clip(x[:, 0], x[:, 2], 1.0 - x[:, 2])
        x[:, 1] = np.clip(x[:, 1], x[:, 2], 1.0 - x[:, 2])
        if not bad:
            break
    x[:, 2] *= (1.0 - 1e-9)
    return x


