def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 32
    rng = np.random.default_rng(987654321)
    deadline = t0 + budget_seconds - 0.8

    def elapsed():
        return time.process_time() - t0

    best = None
    best_score = -1.0

    def score(x):
        return float(np.sum(x[:, 2]))

    def consider(x):
        nonlocal best, best_score
        x = _feasible(x, n)
        s = score(x)
        if s > best_score:
            best_score = s
            best = x
            return True
        return False

    if start is not None:
        try:
            consider(start)
        except Exception:
            pass

    if best is None:
        pts = []
        for j in range(6):
            y = (j + 0.5) / 6
            cnt = 6 if j % 2 == 0 else 5
            for i in range(cnt):
                x = (i + 0.5) / 6 if j % 2 == 0 else (i + 1.0) / 6
                pts.append((x, y))
        pts = pts[:n]
        while len(pts) < n:
            pts.append((0.5, 0.5))
        x0 = np.column_stack([np.array(pts), np.full(n, 0.08)])
        consider(x0)

    def full_polish(xc, maxiter=800):
        pol = _slsqp(_feasible(xc, n), n, maxiter)
        return _feasible(pol, n)

    # Heavy initial polish of start
    if elapsed() < deadline:
        p = full_polish(best, 1000)
        consider(p)

    # Local search: perturb, LP-recover radii on centers, SLSQP polish
    it = 0
    while elapsed() < deadline:
        it += 1
        cand = best.copy()
        # Mix of scales: small for refinement, larger for exploration
        if rng.random() < 0.7:
            scale = rng.uniform(0.003, 0.015)
        else:
            scale = rng.uniform(0.015, 0.06)
        cand[:, 0] += rng.normal(0, scale, n)
        cand[:, 1] += rng.normal(0, scale, n)
        cand = _feasible(cand, n)

        # Try LP on centers first (fast, often helps)
        rlp = _lp_radii(cand[:, :2], n)
        if rlp is not None:
            c2 = _feasible(np.column_stack([cand[:, :2], rlp]), n)
            if score(c2) > score(cand):
                cand = c2

        if elapsed() >= deadline:
            break
        pol = full_polish(cand, 300)
        if consider(pol):
            # extra refinement on improvement
            if elapsed() < deadline:
                p2 = full_polish(best, 500)
                consider(p2)

    # Final safety: shrink radii slightly and re-check
    best = _feasible(best, n)
    return best

