            x = (i + 0.5) / 6 if j % 2 == 0 else (i + 1.0) / 6
            pts.append((x, y))
    while len(pts) < n:
        pts.append((0.5, 0.5))
    return np.array([[p[0], p[1], 0.08] for p in pts[:n]])


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 32
    rng = np.random.default_rng(987654321)
    deadline = 0.88 * budget_seconds

    def elapsed():
        return time.process_time() - t0

    best = None
    best_score = -1.0

    def consider(cand):
        nonlocal best, best_score
        if cand is None:
            return
        cand = _feasible_fix(cand, n)
        sc = float(np.sum(cand[:, 2]))
        if sc > best_score:
            best_score = sc
            best = cand.copy()

    # Seed with start
    if start is not None:
        try:
            s = np.asarray(start, dtype=float).reshape(n, 3)
            consider(s)
        except Exception:
            pass

    # Hexagonal inits
    for rows in (6, 7):
        consider(_lp_set_radii(_hex_init(n, rows), n))

    # SLSQP polish on best
    if best is not None and elapsed() < deadline:
        pol = _slsqp_polish(best, n, maxiter=500)
        consider(_lp_set_radii(pol, n))

    # Local perturbation search
    while elapsed() < deadline:
        base = best if best is not None else _hex_init(n, 6)
        cand = base.copy()
        # perturb centers
        scale = rng.uniform(0.003, 0.035)
        cand[:, 0] += rng.normal(0, scale, n)
        cand[:, 1] += rng.normal(0, scale, n)
        # occasionally perturb radii too
        if rng.random() < 0.3:
            cand[:, 2] *= np.exp(rng.normal(0, 0.05, n))
        cand = _lp_set_radii(cand, n)
        pol = _slsqp_polish(cand, n, maxiter=300)
        if pol is not None:
            pol = _lp_set_radii(pol, n)
            consider(pol)
        if elapsed() >= deadline:
            break
        # re-polish best
        pol2 = _slsqp_polish(best, n, maxiter=250)
        if pol2 is not None:
            consider(_lp_set_radii(pol2, n))

    if best is None:
        if start is not None:
            return _feasible_fix(start, n)
        return _feasible_fix(_hex_init(n, 6), n)

    # Final safety shrink
    best = _feasible_fix(best, n)
    best[:, 2] *= (1.0 - 1e-10)
    return best

import numpy as np
import time
from scipy.optimize import minimize, linprog


def _feasible_fix(x, n=32):
    x = np.array(x, dtype=float).reshape(n, 3)
    x[:, 2] = np.maximum(x[:, 2], 1e-6)
    x[:, 0] = np.clip(x[:, 0], x[:, 2], 1.0 - x[:, 2])
    x[:, 1] = np.clip(x[:, 1], x[:, 2], 1.0 - x[:, 2])
    for _ in range(200):
        changed = False
        for i in range(n):
            for j in range(i + 1, n):
                dx = x[i, 0] - x[j, 0]
                dy = x[i, 1] - x[j, 1]
                d = np.hypot(dx, dy)
                s = x[i, 2] + x[j, 2]
                if d < s + 1e-12:
                    changed = True
                    excess = s - d + 1e-10
                    x[i, 2] -= excess / 2
                    x[j, 2] -= excess / 2
        x[:, 2] = np.maximum(x[:, 2], 1e-6)
        x[:, 0] = np.clip(x[:, 0], x[:, 2], 1.0 - x[:, 2])
        x[:, 1] = np.clip(x[:, 1], x[:, 2], 1.0 - x[:, 2])
        if not changed:
            break
    x[:, 2] *= (1.0 - 1e-8)
    return x


def _lp_radii(centers, n):
    c = -np.ones(n)
    A_ub = []
    b_ub = []
    for i in range(n):
        for w in (centers[i, 0], 1.0 - centers[i, 0],
                  centers[i, 1], 1.0 - centers[i, 1]):
            row = np.zeros(n)
            row[i] = 1.0
            A_ub.append(row)
            b_ub.append(max(w, 0.0))
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(centers[i, 0] - centers[j, 0],
                         centers[i, 1] - centers[j, 1])
            row = np.zeros(n)
            row[i] = 1.0
            row[j] = 1.0
            A_ub.append(row)
            b_ub.append(max(d, 0.0))
    try:
        res = linprog(c, A_ub=np.array(A_ub), b_ub=np.array(b_ub),
                      bounds=[(1e-6, None)] * n, method='highs')
        if res.success:
            return np.maximum(res.x, 1e-6)
    except Exception:
        pass
    return None


def _slsqp_polish(x_init, n, maxiter, ftol=1e-14):
    def obj(v):
        return -np.sum(v[2::3])

    def obj_grad(v):
        g = np.zeros_like(v)
        g[2::3] = -1.0
        return g

    bounds = []
    for i in range(n):
        bounds.append((0.0, 1.0))
        bounds.append((0.0, 1.0))
        bounds.append((1e-4, 0.5))

    cons = []
    for i in range(n):
        for kind in range(4):
            def make_wall(i, kind):
                def f(v):
                    X = v.reshape(n, 3)
                    if kind == 0:
                        return X[i, 0] - X[i, 2]
                    elif kind == 1:
                        return 1.0 - X[i, 0] - X[i, 2]
                    elif kind == 2:
                        return X[i, 1] - X[i, 2]
                    else:
                        return 1.0 - X[i, 1] - X[i, 2]
                def jac(v):
                    g = np.zeros(3 * n)
                    if kind == 0:
                        g[3 * i] = 1.0
                    elif kind == 1:
                        g[3 * i] = -1.0
                    elif kind == 2:
                        g[3 * i + 1] = 1.0
                    else:
                        g[3 * i + 1] = -1.0
                    g[3 * i + 2] = -1.0
                    return g
                return f, jac
            f, j = make_wall(i, kind)
            cons.append({'type': 'ineq', 'fun': f, 'jac': j})

    for i in range(n):
        for j in range(i + 1, n):
            def make_pair(i, j):
                def f(v):
                    X = v.reshape(n, 3)
                    dx = X[i, 0] - X[j, 0]
                    dy = X[i, 1] - X[j, 1]
                    return dx * dx + dy * dy - (X[i, 2] + X[j, 2]) ** 2
                def jac(v):
                    X = v.reshape(n, 3)
                    dx = X[i, 0] - X[j, 0]
                    dy = X[i, 1] - X[j, 1]
                    s = X[i, 2] + X[j, 2]
                    g = np.zeros(3 * n)
                    g[3 * i] = 2.0 * dx
                    g[3 * i + 1] = 2.0 * dy
                    g[3 * i + 2] = -2.0 * s
                    g[3 * j] = -2.0 * dx
                    g[3 * j + 1] = -2.0 * dy
                    g[3 * j + 2] = -2.0 * s
                    return g
                return f, jac
            f, j = make_pair(i, j)
            cons.append({'type': 'ineq', 'fun': f, 'jac': j})

    v0 = x_init.reshape(-1).copy()
    v0[2::3] = np.clip(v0[2::3], 1e-4, 0.5)
    v0[0::3] = np.clip(v0[0::3], 0.0, 1.0)
    v0[1::3] = np.clip(v0[1::3], 0.0, 1.0)
    try:
        res = minimize(obj, v0, jac=obj_grad, method='SLSQP',
                       bounds=bounds, constraints=cons,
                       options={'maxiter': maxiter, 'ftol': ftol})
        return res.x.reshape(n, 3)
    except Exception:
        return x_init


def _bilevel_ascent(centers, n, iters, eta, t0, budget):
    c = np.array(centers, dtype=float).copy()
    best_c = c.copy()
    best_val = -1.0
    best_r = None
    vel = np.zeros_like(c)
    for it in range(iters):
        if time.process_time() - t0 > budget:
            break
        r = _lp_radii(c, n)
        if r is None:
            break
        val = float(np.sum(r))
        if val > best_val:
            best_val = val
            best_c = c.copy()
            best_r = r.copy()
        # gradient of LP optimum w.r.t. centers via duals is expensive;
        # use a cheaper proxy: push touching pairs apart.
        grad = np.zeros_like(c)
        for i in range(n):
            for j in range(i + 1, n):
                dx = c[i, 0] - c[j, 0]
                dy = c[i, 1] - c[j, 1]
                d = np.hypot(dx, dy)
                s = r[i] + r[j]
                if d < s + 1e-3 and d > 1e-9:
                    ux, uy = dx / d, dy / d
                    grad[i, 0] += ux
                    grad[i, 1] += uy
                    grad[j, 0] -= ux
                    grad[j, 1] -= uy
        gmax = np.max(np.abs(grad))
        if gmax < 1e-14:
            grad = np.random.default_rng(it + int(t0*1000)).normal(0, 1e-3, c.shape)
            gmax = np.max(np.abs(grad)) + 1e-12
        step = eta * grad / gmax
        vel = 0.6 * vel + step
        c = c + vel
        c[:, 0] = np.clip(c[:, 0], 1e-6, 1.0 - 1e-6)
        c[:, 1] = np.clip(c[:, 1], 1e-6, 1.0 - 1e-6)
    if best_r is None:
        best_r = _lp_radii(best_c, n)
        if best_r is None:
            best_r = np.full(n, 0.05)
    return _feasible_fix(np.column_stack([best_c, best_r]), n)


def _hex_init(n, rows):
    pts = []
    for j in range(rows):
        y = (j + 0.5) / rows
        cnt = int(np.ceil(n / rows)) + 1
        off = 0.5 if j % 2 == 0 else 0.0
        for i in range(cnt):
            x = (i + 0.5 + off * 0.5) / (cnt + 0.5)
            if 0.0 < x < 1.0:
                pts.append((x, y))
    while len(pts) < n:
        pts.append((0.5, 0.5))
    return np.array(pts[:n])


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 32
    rng = np.random.default_rng(20240522)

    best = None
    best_score = -1.0

    def consider(cand):
        nonlocal best, best_score
        try:
            cand = _feasible_fix(cand, n)
        except Exception:
            return False
        sc = float(np.sum(cand[:, 2]))
        if sc > best_score:
            best_score = sc
            best = cand
            return True
        return False

    if start is not None:
        consider(start)

    # Baseline LP on current centers, then SLSQP polish
    if best is not None:
        pol = _slsqp_polish(best, n, maxiter=800)
        consider(pol)

    # Bilevel ascents from hex seeds
    for rows in (5, 6, 7):
        if time.process_time() - t0 > 0.35 * budget_seconds:
            break
        centers = _hex_init(n, rows)
        r0 = _lp_radii(centers, n)
        if r0 is None:
            r0 = np.full(n, 0.07)
        cand = _feasible_fix(np.column_stack([centers, r0]), n)
        consider(cand)
        ba = _bilevel_ascent(centers, n, iters=200, eta=0.001,
                             t0=t0, budget=0.35 * budget_seconds)
        consider(ba)

    # Iterated local search around best
    it_no = 0
    while best is not None and time.process_time() - t0 < 0.85 * budget_seconds:
        it_no += 1
        cand = best.copy()
        k = int(rng.integers(3, 12))
        idx = rng.choice(n, size=k, replace=False)
        scale = float(rng.uniform(0.005, 0.05))
        cand[idx, 0] += rng.normal(0, scale, k)
        cand[idx, 1] += rng.normal(0, scale, k)
        cand[:, 0] = np.clip(cand[:, 0], 0.0, 1.0)
        cand[:, 1] = np.clip(cand[:, 1], 0.0, 1.0)
        ba = _bilevel_ascent(cand[:, :2], n, iters=40, eta=0.001,
                             t0=t0, budget=0.85 * budget_seconds)
        if float(np.sum(ba[:, 2])) > best_score:
            consider(ba)
            if time.process_time() - t0 < 0.85 * budget_seconds:
                pol = _slsqp_polish(best, n, maxiter=400)
                consider(pol)

    # Final polish with more iterations
    if best is not None and time.process_time() - t0 < 0.97 * budget_seconds:
        pol = _slsqp_polish(best, n, maxiter=1500)
        consider(pol)

    if best is None:
        if start is not None:
            return _feasible_fix(start, n)
        centers = _hex_init(n, 6)
        return _feasible_fix(np.column_stack([centers, np.full(n, 0.07)]), n)

    return _feasible_fix(best, n)

