        x[:, 1] = np.clip(x[:, 1], x[:, 2], 1.0 - x[:, 2])
        if not changed:
            break
    x[:, 2] *= (1.0 - shrink)
    return x


def _lp_radii(centers, n):
    c = -np.ones(n)
    A_ub = []
    b_ub = []
    for i in range(n):
        for w in (centers[i, 0], 1.0 - centers[i, 0],
                  centers[i, 1], 1.0 - centers[i, 1]):
            row = np.zeros(n)
            row[i] = 1.0
            A_ub.append(row)
            b_ub.append(max(w, 0.0))
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(centers[i, 0] - centers[j, 0],
                         centers[i, 1] - centers[j, 1])
            row = np.zeros(n)
            row[i] = 1.0
            row[j] = 1.0
            A_ub.append(row)
            b_ub.append(max(d, 0.0))
    try:
        res = linprog(c, A_ub=np.array(A_ub), b_ub=np.array(b_ub),
                      bounds=[(1e-7, None)] * n, method='highs')
        if res.success:
            return np.maximum(res.x, 1e-7)
    except Exception:
        pass
    return None


def _lp_set_radii(x, n):
    x = np.array(x, dtype=float).reshape(n, 3)
    centers = np.clip(x[:, :2].copy(), 0.0, 1.0)
    for _ in range(4):
        r = _lp_radii(centers, n)
        if r is None:
            break
        centers[:, 0] = np.clip(centers[:, 0], r, 1.0 - r)
        centers[:, 1] = np.clip(centers[:, 1], r, 1.0 - r)
    r = _lp_radii(centers, n)
    if r is None:
        return x
    return np.column_stack([centers, r])


def _slsqp_polish(x_init, n, maxiter, ftol=1e-14):
    def obj(v):
        return -np.sum(v[2::3])

    def obj_grad(v):
        g = np.zeros_like(v)
        g[2::3] = -1.0
        return g

    bounds = []
    for i in range(n):
        bounds.append((0.0, 1.0))
        bounds.append((0.0, 1.0))
        bounds.append((1e-4, 0.5))

    cons = []
    for i in range(n):
        for kind in range(4):
            def make_wall(i, kind):
                def f(v):
                    X = v.reshape(n, 3)
                    if kind == 0:
                        return X[i, 0] - X[i, 2]
                    elif kind == 1:
                        return 1.0 - X[i, 0] - X[i, 2]
                    elif kind == 2:
                        return X[i, 1] - X[i, 2]
                    else:
                        return 1.0 - X[i, 1] - X[i, 2]
                def jac(v):
                    g = np.zeros(3 * n)
                    if kind == 0:
                        g[3 * i] = 1.0
                    elif kind == 1:
                        g[3 * i] = -1.0
                    elif kind == 2:
                        g[3 * i + 1] = 1.0
                    else:
                        g[3 * i + 1] = -1.0
                    g[3 * i + 2] = -1.0
                    return g
                return f, jac
            f, j = make_wall(i, kind)
            cons.append({'type': 'ineq', 'fun': f, 'jac': j})

    for i in range(n):
        for j in range(i + 1, n):
            def make_pair(i, j):
                def f(v):
                    X = v.reshape(n, 3)
                    dx = X[i, 0] - X[j, 0]
                    dy = X[i, 1] - X[j, 1]
                    return dx * dx + dy * dy - (X[i, 2] + X[j, 2]) ** 2
                def jac(v):
                    X = v.reshape(n, 3)
                    dx = X[i, 0] - X[j, 0]
                    dy = X[i, 1] - X[j, 1]
                    s = X[i, 2] + X[j, 2]
                    g = np.zeros(3 * n)
                    g[3 * i] = 2.0 * dx
                    g[3 * i + 1] = 2.0 * dy
                    g[3 * i + 2] = -2.0 * s
                    g[3 * j] = -2.0 * dx
                    g[3 * j + 1] = -2.0 * dy
                    g[3 * j + 2] = -2.0 * s
                    return g
                return f, jac
            f, j = make_pair(i, j)
            cons.append({'type': 'ineq', 'fun': f, 'jac': j})

    v0 = x_init.reshape(-1).copy()
    v0[2::3] = np.clip(v0[2::3], 1e-4, 0.5)
    v0[0::3] = np.clip(v0[0::3], 0.0, 1.0)
    v0[1::3] = np.clip(v0[1::3], 0.0, 1.0)
    try:
        res = minimize(obj, v0, jac=obj_grad, method='SLSQP',
                       bounds=bounds, constraints=cons,
                       options={'maxiter': maxiter, 'ftol': ftol})
        return res.x.reshape(n, 3)
    except Exception:
        return x_init


def _hex_init(n, rows):
    pts = []
    for j in range(rows):
        y = (j + 0.5) / rows
        cnt = 6 if j % 2 == 0 else 5
        for i in range(cnt):
            x = (i + 0.5) / 6 if j % 2 == 0 else (i + 1.0) / 6
            pts.append((x, y))
    while len(pts) < n:
        pts.append((0.5, 0.5))
    return np.array([[p[0], p[1], 0.08] for p in pts[:n]])


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 32
    rng = np.random.default_rng(20240611)
    deadline = 0.85 * budget_seconds

    def elapsed():
        return time.process_time() - t0

    best = None
    best_score = -1.0

    def score(x):
        return float(np.sum(x[:, 2]))

    def consider(cand):
        nonlocal best, best_score
        if cand is None:
            return
        cand = _feasible_fix(cand, n)
        sc = score(cand)
        if sc > best_score:
            best_score = sc
            best = cand.copy()

    if start is not None:
        try:
            consider(np.asarray(start, dtype=float).reshape(n, 3))
        except Exception:
            pass

    for rows in (6, 7):
        consider(_lp_set_radii(_hex_init(n, rows), n))

    if best is None:
        best = _feasible_fix(_hex_init(n, 6), n)
        best_score = score(best)

    # Strong first polish
    if elapsed() < deadline:
        pol = _slsqp_polish(best, n, maxiter=1200, ftol=1e-16)
        consider(_lp_set_radii(pol, n))
        consider(pol)

    # Local perturbation search — several scales in parallel
    scales = [0.002, 0.005, 0.012, 0.025, 0.05]
    it = 0
    while elapsed() < deadline:
        it += 1
        base = best
        cand = base.copy()
        scale = scales[it % len(scales)] * rng.uniform(0.7, 1.3)
        cand[:, 0] += rng.normal(0, scale, n)
        cand[:, 1] += rng.normal(0, scale, n)
        # shrink radii a bit to allow rearrangement
        cand[:, 2] *= rng.uniform(0.90, 0.995)
        cand = _lp_set_radii(cand, n)
        rem = deadline - elapsed()
        maxit = 400 if rem > 2.0 else 200
        pol = _slsqp_polish(cand, n, maxiter=maxit)
        pol = _lp_set_radii(pol, n)
        consider(pol)
        if it % 3 == 0 and elapsed() < deadline:
            pol2 = _slsqp_polish(best, n, maxiter=250)
            consider(_lp_set_radii(pol2, n))

    best = _feasible_fix(best, n, shrink=1e-9)
    return best

