            for j in range(i + 1, n):
                dx = x[i, 0] - x[j, 0]
                dy = x[i, 1] - x[j, 1]
                d = np.hypot(dx, dy)
                s = x[i, 2] + x[j, 2]
                if d < s:
                    changed = True
                    excess = s - d + 1e-11
                    x[i, 2] -= excess / 2
                    x[j, 2] -= excess / 2
        x[:, 2] = np.maximum(x[:, 2], 1e-6)
        x[:, 0] = np.clip(x[:, 0], x[:, 2], 1.0 - x[:, 2])
        x[:, 1] = np.clip(x[:, 1], x[:, 2], 1.0 - x[:, 2])
        if not changed:
            break
    x[:, 2] *= (1.0 - 1e-12)
    return x


def _lp_radii(centers, n):
    c = -np.ones(n)
    A_ub = []
    b_ub = []
    for i in range(n):
        for w in (centers[i, 0], 1.0 - centers[i, 0],
                  centers[i, 1], 1.0 - centers[i, 1]):
            row = np.zeros(n)
            row[i] = 1.0
            A_ub.append(row)
            b_ub.append(max(w, 0.0))
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(centers[i, 0] - centers[j, 0],
                         centers[i, 1] - centers[j, 1])
            row = np.zeros(n)
            row[i] = 1.0
            row[j] = 1.0
            A_ub.append(row)
            b_ub.append(max(d, 0.0))
    bounds = [(1e-6, None)] * n
    try:
        res = linprog(c, A_ub=np.array(A_ub), b_ub=np.array(b_ub),
                      bounds=bounds, method='highs',
                      options={'primal_feasibility_tolerance': 1e-10,
                               'dual_feasibility_tolerance': 1e-10})
        if res.success:
            return np.maximum(res.x, 1e-6)
    except Exception:
        pass
    return None


def _slsqp_polish(x_init, n, maxiter, ftol=1e-14):
    def obj(v):
        return -np.sum(v[2::3])

    def obj_grad(v):
        g = np.zeros_like(v)
        g[2::3] = -1.0
        return g

    bounds = []
    for i in range(n):
        bounds.append((0.0, 1.0))
        bounds.append((0.0, 1.0))
        bounds.append((1e-4, 0.5))

    cons = []
    for i in range(n):
        for kind in range(4):
            def make_wall(i, kind):
                def f(v):
                    X = v.reshape(n, 3)
                    if kind == 0:
                        return X[i, 0] - X[i, 2]
                    elif kind == 1:
                        return 1.0 - X[i, 0] - X[i, 2]
                    elif kind == 2:
                        return X[i, 1] - X[i, 2]
                    else:
                        return 1.0 - X[i, 1] - X[i, 2]
                def jac(v):
                    g = np.zeros(3 * n)
                    if kind == 0:
                        g[3 * i] = 1.0
                    elif kind == 1:
                        g[3 * i] = -1.0
                    elif kind == 2:
                        g[3 * i + 1] = 1.0
                    else:
                        g[3 * i + 1] = -1.0
                    g[3 * i + 2] = -1.0
                    return g
                return f, jac
            f, j = make_wall(i, kind)
            cons.append({'type': 'ineq', 'fun': f, 'jac': j})

    for i in range(n):
        for j in range(i + 1, n):
            def make_pair(i, j):
                def f(v):
                    X = v.reshape(n, 3)
                    dx = X[i, 0] - X[j, 0]
                    dy = X[i, 1] - X[j, 1]
                    return dx * dx + dy * dy - (X[i, 2] + X[j, 2]) ** 2
                def jac(v):
                    X = v.reshape(n, 3)
                    dx = X[i, 0] - X[j, 0]
                    dy = X[i, 1] - X[j, 1]
                    s = X[i, 2] + X[j, 2]
                    g = np.zeros(3 * n)
                    g[3 * i] = 2.0 * dx
                    g[3 * i + 1] = 2.0 * dy
                    g[3 * i + 2] = -2.0 * s
                    g[3 * j] = -2.0 * dx
                    g[3 * j + 1] = -2.0 * dy
                    g[3 * j + 2] = -2.0 * s
                    return g
                return f, jac
            f, j = make_pair(i, j)
            cons.append({'type': 'ineq', 'fun': f, 'jac': j})

    v0 = x_init.reshape(-1).copy()
    v0[2::3] = np.clip(v0[2::3], 1e-4, 0.5)
    v0[0::3] = np.clip(v0[0::3], 0.0, 1.0)
    v0[1::3] = np.clip(v0[1::3], 0.0, 1.0)
    try:
        res = minimize(obj, v0, jac=obj_grad, method='SLSQP',
                       bounds=bounds, constraints=cons,
                       options={'maxiter': maxiter, 'ftol': ftol})
        return res.x.reshape(n, 3)
    except Exception:
        return x_init


def _slp_step(x, n, delta=2e-3):
    tol = 1e-6
    A_ub = []
    b_ub = []
    for i in range(n):
        for j in range(i + 1, n):
            dx = x[i, 0] - x[j, 0]
            dy = x[i, 1] - x[j, 1]
            d = np.hypot(dx, dy)
            gap = d - x[i, 2] - x[j, 2]
            if gap < tol:
                if d < 1e-12:
                    continue
                ux = dx / d
                uy = dy / d
                row = np.zeros(3 * n)
                row[3 * i] = -ux
                row[3 * i + 1] = -uy
                row[3 * i + 2] = 1.0
                row[3 * j] = ux
                row[3 * j + 1] = uy
                row[3 * j + 2] = 1.0
                A_ub.append(row)
                b_ub.append(0.0)
    for i in range(n):
        if abs(x[i, 0] - x[i, 2]) < tol:
            row = np.zeros(3 * n)
            row[3 * i] = -1.0
            row[3 * i + 2] = 1.0
            A_ub.append(row); b_ub.append(0.0)
        if abs(1.0 - x[i, 0] - x[i, 2]) < tol:
            row = np.zeros(3 * n)
            row[3 * i] = 1.0
            row[3 * i + 2] = 1.0
            A_ub.append(row); b_ub.append(0.0)
        if abs(x[i, 1] - x[i, 2]) < tol:
            row = np.zeros(3 * n)
            row[3 * i + 1] = -1.0
            row[3 * i + 2] = 1.0
            A_ub.append(row); b_ub.append(0.0)
        if abs(1.0 - x[i, 1] - x[i, 2]) < tol:
            row = np.zeros(3 * n)
            row[3 * i + 1] = 1.0
            row[3 * i + 2] = 1.0
            A_ub.append(row); b_ub.append(0.0)
    if not A_ub:
        return None, 0.0
    c = np.zeros(3 * n)
    c[2::3] = -1.0
    bounds = [(-delta, delta)] * (3 * n)
    try:
        res = linprog(c, A_ub=np.array(A_ub), b_ub=np.array(b_ub),
                      bounds=bounds, method='highs',
                      options={'primal_feasibility_tolerance': 1e-10,
                               'dual_feasibility_tolerance': 1e-10})
        if res.success:
            return res.x, -res.fun
    except Exception:
        pass
    return None, 0.0


def _ls_compress(centers, n, rng, growth=1.005, max_sweeps=200):
    """Lubachevsky-Stillinger compression: grow radii, resolve overlaps."""
    c = np.array(centers, dtype=float).copy()
    r = np.full(n, 0.01)
    last_good_c = c.copy()
    last_good_r = r.copy()
    for _ in range(20000):
        r_new = r * growth
        # check feasibility of growth by relaxation
        cc = c.copy()
        ok = True
        for sweep in range(max_sweeps):
            max_overlap = 0.0
            # pair pushes
            for i in range(n):
                for j in range(i + 1, n):
                    dx = cc[i, 0] - cc[j, 0]
                    dy = cc[i, 1] - cc[j, 1]
                    d = np.hypot(dx, dy)
                    s = r_new[i] + r_new[j]
                    if d < s:
                        ov = s - d
                        if ov > max_overlap:
                            max_overlap = ov
                        if d < 1e-12:
                            ang = rng.uniform(0, 2 * np.pi)
                            ux, uy = np.cos(ang), np.sin(ang)
                        else:
                            ux = dx / d
                            uy = dy / d
                        push = 0.5 * ov
                        cc[i, 0] += push * ux
                        cc[i, 1] += push * uy
                        cc[j, 0] -= push * ux
                        cc[j, 1] -= push * uy
            # wall pushes
            for i in range(n):
                if cc[i, 0] - r_new[i] < 0:
                    cc[i, 0] = r_new[i]
                if cc[i, 0] + r_new[i] > 1:
                    cc[i, 0] = 1 - r_new[i]
                if cc[i, 1] - r_new[i] < 0:
                    cc[i, 1] = r_new[i]
                if cc[i, 1] + r_new[i] > 1:
                    cc[i, 1] = 1 - r_new[i]
            if max_overlap < 1e-9:
                break
        else:
            ok = False
        if not ok:
            break
        last_good_c = cc.copy()
        last_good_r = r_new.copy()
        c = cc
        r = r_new
    return last_good_c, last_good_r


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 32
    rng = np.random.default_rng(12345)
    HARD = min(budget_seconds * 0.82, budget_seconds - 1.2)

    def elapsed():
        return time.process_time() - t0

    best = None
    best_score = -1.0

    def score(x):
        return float(np.sum(x[:, 2]))

    if start is not None:
        try:
            s = _feasible_fix(start, n)
            best = s
            best_score = score(s)
        except Exception:
            pass

    def hex_init(rows, cols):
        pts = []
        for j in range(rows):
            y = (j + 0.5) / rows
            off = 0.5 if j % 2 == 0 else 1.0
            cnt = cols if j % 2 == 0 else cols - 1
            for i in range(cnt):
                x = (i + off) / cols
                pts.append((x, y))
        return pts

    def grid_init(g):
        pts = []
        for j in range(g):
            for i in range(g):
                pts.append(((i + 0.5) / g, (j + 0.5) / g))
        return pts

    inits = []
    for rows, cols in [(6, 6), (5, 7), (7, 5), (6, 7), (8, 4)]:
        p = hex_init(rows, cols)
        if len(p) >= n:
            inits.append(np.array(p[:n]))
    for g in (6, 7):
        p = grid_init(g)
        if len(p) >= n:
            inits.append(np.array(p[:n]))

    def make_cand(centers):
        rlp = _lp_radii(centers, n)
        if rlp is None:
            rlp = np.full(n, 0.05)
        c = np.column_stack([centers, rlp])
        return _feasible_fix(c, n)

    def consider(cand):
        nonlocal best, best_score
        cand = _feasible_fix(cand, n)
        if score(cand) > best_score:
            best_score = score(cand)
            best = cand

    # Polish the start first
    if best is not None and elapsed() < HARD:
        pol = _slsqp_polish(best, n, maxiter=3000, ftol=1e-16)
        pol = _feasible_fix(pol, n)
        if score(pol) > best_score:
            best_score = score(pol)
            best = pol

    # LS compression runs from random seeds
    ls_count = 0
    while elapsed() < HARD - 1.0:
        try:
            seed_c = rng.uniform(0.15, 0.85, (n, 2))
            cc, rr = _ls_compress(seed_c, n, rng)
            cand = make_cand(cc)
            pol = _slsqp_polish(cand, n, maxiter=1500)
            pol = _feasible_fix(pol, n)
            if score(pol) > best_score:
                best_score = score(pol)
                best = pol
            ls_count += 1
        except Exception:
            break

    # One LS run seeded from p0049's centers with jitter
    if start is not None and elapsed() < HARD - 0.5:
        try:
            base_c = np.array(start, dtype=float)[:, :2].copy()
            base_c += rng.normal(0, 0.02, base_c.shape)
            base_c = np.clip(base_c, 0.05, 0.95)
            cc, rr = _ls_compress(base_c, n, rng)
            cand = make_cand(cc)
            pol = _slsqp_polish(cand, n, maxiter=1500)
            pol = _feasible_fix(pol, n)
            if score(pol) > best_score:
                best_score = score(pol)
                best = pol
        except Exception:
            pass

    # Fallback hex/grid seeds if time remains
    for centers in inits:
        if elapsed() > HARD - 0.5:
            break
        try:
            cand = make_cand(centers)
            consider(cand)
        except Exception:
            pass

    if best is None:
        if start is not None:
            return _feasible_fix(start, n)
        p = hex_init(6, 6)
        return make_cand(np.array(p[:n]))

    # Final LP re-solve at final centers
    try:
        centers = best[:, :2].copy()
        r = _lp_radii(centers, n)
        if r is not None:
            cand = np.column_stack([centers, r])
            cand = _feasible_fix(cand, n)
            if score(cand) > best_score:
                best = cand
                best_score = score(cand)
    except Exception:
        pass

    # SLP tangent-space improvement loop
    margin = 1.0
    it = 0
    while best is not None and it < 40 and elapsed() < budget_seconds - margin:
        it += 1
        try:
            v, opt = _slp_step(best, n, delta=2e-3)
        except Exception:
            break
        if v is None or opt < 1e-12:
            break
        try:
            x_new = best.reshape(-1) + 0.5 * v
            x_new = x_new.reshape(n, 3)
            x_new = _feasible_fix(x_new, n)
            pol = _slsqp_polish(x_new, n, maxiter=2000)
            pol = _feasible_fix(pol, n)
            if score(pol) > best_score:
                best = pol
                best_score = score(pol)
            else:
                x_new2 = best.reshape(-1) + 0.25 * v
                x_new2 = _feasible_fix(x_new2.reshape(n, 3), n)
                pol2 = _slsqp_polish(x_new2, n, maxiter=2000)
                pol2 = _feasible_fix(pol2, n)
                if score(pol2) > best_score:
                    best = pol2
                    best_score = score(pol2)
                else:
                    break
        except Exception:
            break

    return best

import numpy as np
import time
from scipy.optimize import minimize, linprog


def _feasible_fix(x, n):
    x = np.array(x, dtype=float).reshape(n, 3)
    x[:, 2] = np.maximum(x[:, 2], 1e-6)
    x[:, 0] = np.clip(x[:, 0], x[:, 2], 1.0 - x[:, 2])
    x[:, 1] = np.clip(x[:, 1], x[:, 2], 1.0 - x[:, 2])
    for _ in range(100):
        changed = False
        for i in range(n):
            for j in range(i + 1, n):
                dx = x[i, 0] - x[j, 0]
                dy = x[i, 1] - x[j, 1]
                d = np.hypot(dx, dy)
                s = x[i, 2] + x[j, 2]
                if d < s:
                    changed = True
                    excess = s - d + 1e-11
                    x[i, 2] -= excess / 2
                    x[j, 2] -= excess / 2
        x[:, 2] = np.maximum(x[:, 2], 1e-6)
        x[:, 0] = np.clip(x[:, 0], x[:, 2], 1.0 - x[:, 2])
        x[:, 1] = np.clip(x[:, 1], x[:, 2], 1.0 - x[:, 2])
        if not changed:
            break
    x[:, 2] *= (1.0 - 1e-12)
    return x


def _lp_radii(centers, n):
    c = -np.ones(n)
    A_ub = []
    b_ub = []
    for i in range(n):
        for w in (centers[i, 0], 1.0 - centers[i, 0],
                  centers[i, 1], 1.0 - centers[i, 1]):
            row = np.zeros(n)
            row[i] = 1.0
            A_ub.append(row)
            b_ub.append(max(w, 0.0))
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(centers[i, 0] - centers[j, 0],
                         centers[i, 1] - centers[j, 1])
            row = np.zeros(n)
            row[i] = 1.0
            row[j] = 1.0
            A_ub.append(row)
            b_ub.append(max(d, 0.0))
    bounds = [(1e-6, None)] * n
    try:
        res = linprog(c, A_ub=np.array(A_ub), b_ub=np.array(b_ub),
                      bounds=bounds, method='highs',
                      options={'primal_feasibility_tolerance': 1e-10,
                               'dual_feasibility_tolerance': 1e-10})
        if res.success:
            return np.maximum(res.x, 1e-6)
    except Exception:
        pass
    return None


def _slsqp_polish(x_init, n, maxiter, ftol=1e-14):
    def obj(v):
        return -np.sum(v[2::3])

    def obj_grad(v):
        g = np.zeros_like(v)
        g[2::3] = -1.0
        return g

    bounds = []
    for i in range(n):
        bounds.append((0.0, 1.0))
        bounds.append((0.0, 1.0))
        bounds.append((1e-4, 0.5))

    cons = []
    for i in range(n):
        for kind in range(4):
            def make_wall(i, kind):
                def f(v):
                    X = v.reshape(n, 3)
                    if kind == 0:
                        return X[i, 0] - X[i, 2]
                    elif kind == 1:
                        return 1.0 - X[i, 0] - X[i, 2]
                    elif kind == 2:
                        return X[i, 1] - X[i, 2]
                    else:
                        return 1.0 - X[i, 1] - X[i, 2]
                def jac(v):
                    g = np.zeros(3 * n)
                    if kind == 0:
                        g[3 * i] = 1.0
                    elif kind == 1:
                        g[3 * i] = -1.0
                    elif kind == 2:
                        g[3 * i + 1] = 1.0
                    else:
                        g[3 * i + 1] = -1.0
                    g[3 * i + 2] = -1.0
                    return g
                return f, jac
            f, j = make_wall(i, kind)
            cons.append({'type': 'ineq', 'fun': f, 'jac': j})

    for i in range(n):
        for j in range(i + 1, n):
            def make_pair(i, j):
                def f(v):
                    X = v.reshape(n, 3)
                    dx = X[i, 0] - X[j, 0]
                    dy = X[i, 1] - X[j, 1]
                    return dx * dx + dy * dy - (X[i, 2] + X[j, 2]) ** 2
                def jac(v):
                    X = v.reshape(n, 3)
                    dx = X[i, 0] - X[j, 0]
                    dy = X[i, 1] - X[j, 1]
                    s = X[i, 2] + X[j, 2]
                    g = np.zeros(3 * n)
                    g[3 * i] = 2.0 * dx
                    g[3 * i + 1] = 2.0 * dy
                    g[3 * i + 2] = -2.0 * s
                    g[3 * j] = -2.0 * dx
                    g[3 * j + 1] = -2.0 * dy
                    g[3 * j + 2] = -2.0 * s
                    return g
                return f, jac
            f, j = make_pair(i, j)
            cons.append({'type': 'ineq', 'fun': f, 'jac': j})

    v0 = x_init.reshape(-1).copy()
    v0[2::3] = np.clip(v0[2::3], 1e-4, 0.5)
    v0[0::3] = np.clip(v0[0::3], 0.0, 1.0)
    v0[1::3] = np.clip(v0[1::3], 0.0, 1.0)
    try:
        res = minimize(obj, v0, jac=obj_grad, method='SLSQP',
                       bounds=bounds, constraints=cons,
                       options={'maxiter': maxiter, 'ftol': ftol})
        return res.x.reshape(n, 3)
    except Exception:
        return x_init


def _slp_step(x, n, delta=2e-3):
    tol = 1e-6
    A_ub = []
    b_ub = []
    for i in range(n):
        for j in range(i + 1, n):
            dx = x[i, 0] - x[j, 0]
            dy = x[i, 1] - x[j, 1]
            d = np.hypot(dx, dy)
            gap = d - x[i, 2] - x[j, 2]
            if gap < tol:
                if d < 1e-12:
                    continue
                ux = dx / d
                uy = dy / d
                row = np.zeros(3 * n)
                row[3 * i] = -ux
                row[3 * i + 1] = -uy
                row[3 * i + 2] = 1.0
                row[3 * j] = ux
                row[3 * j + 1] = uy
                row[3 * j + 2] = 1.0
                A_ub.append(row)
                b_ub.append(0.0)
    for i in range(n):
        if abs(x[i, 0] - x[i, 2]) < tol:
            row = np.zeros(3 * n)
            row[3 * i] = -1.0
            row[3 * i + 2] = 1.0
            A_ub.append(row); b_ub.append(0.0)
        if abs(1.0 - x[i, 0] - x[i, 2]) < tol:
            row = np.zeros(3 * n)
            row[3 * i] = 1.0
            row[3 * i + 2] = 1.0
            A_ub.append(row); b_ub.append(0.0)
        if abs(x[i, 1] - x[i, 2]) < tol:
            row = np.zeros(3 * n)
            row[3 * i + 1] = -1.0
            row[3 * i + 2] = 1.0
            A_ub.append(row); b_ub.append(0.0)
        if abs(1.0 - x[i, 1] - x[i, 2]) < tol:
            row = np.zeros(3 * n)
            row[3 * i + 1] = 1.0
            row[3 * i + 2] = 1.0
            A_ub.append(row); b_ub.append(0.0)
    if not A_ub:
        return None, 0.0
    c = np.zeros(3 * n)
    c[2::3] = -1.0
    bounds = [(-delta, delta)] * (3 * n)
    try:
        res = linprog(c, A_ub=np.array(A_ub), b_ub=np.array(b_ub),
                      bounds=bounds, method='highs',
                      options={'primal_feasibility_tolerance': 1e-10,
                               'dual_feasibility_tolerance': 1e-10})
        if res.success:
            return res.x, -res.fun
    except Exception:
        pass
    return None, 0.0


def _best_insert_center(centers, radii, m):
    """Find best center for circle m given other circles fixed.
    Returns (cx, cy, r) maximizing r."""
    others = np.delete(np.arange(len(centers)), m)
    oc = centers[others]
    orr = radii[others]
    # candidate grid
    g = 30
    xs = (np.arange(g) + 0.5) / g
    ys = (np.arange(g) + 0.5) / g
    best_r = -1.0
    best_xy = (0.5, 0.5)
    for yy in ys:
        for xx in xs:
            wall = min(xx, 1.0 - xx, yy, 1.0 - yy)
            if wall <= best_r:
                continue
            d = np.hypot(oc[:, 0] - xx, oc[:, 1] - yy) - orr
            fit = min(wall, d.min() if len(d) else wall)
            if fit > best_r:
                best_r = fit
                best_xy = (xx, yy)
    # also try original position
    ox, oy = centers[m]
    wall = min(ox, 1.0 - ox, oy, 1.0 - oy)
    d = np.hypot(oc[:, 0] - ox, oc[:, 1] - oy) - orr
    fit = min(wall, d.min() if len(d) else wall)
    if fit > best_r:
        best_r = fit
        best_xy = (ox, oy)
    # farthest point from existing centers
    if len(oc) > 0:
        fg = 15
        fxs = (np.arange(fg) + 0.5) / fg
        best_far = -1.0
        far_xy = (0.5, 0.5)
        for yy in fxs:
            for xx in fxs:
                dd = np.hypot(oc[:, 0] - xx, oc[:, 1] - yy).min()
                if dd > best_far:
                    best_far = dd
                    far_xy = (xx, yy)
        xx, yy = far_xy
        wall = min(xx, 1.0 - xx, yy, 1.0 - yy)
        d = np.hypot(oc[:, 0] - xx, oc[:, 1] - yy) - orr
        fit = min(wall, d.min() if len(d) else wall)
        if fit > best_r:
            best_r = fit
            best_xy = (xx, yy)
    return best_xy[0], best_xy[1], max(best_r, 1e-6)


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 32
    rng = np.random.default_rng(12345)
    HARD = min(budget_seconds * 0.82, budget_seconds - 1.2)

    def elapsed():
        return time.process_time() - t0

    best = None
    best_score = -1.0

    def score(x):
        return float(np.sum(x[:, 2]))

    if start is not None:
        try:
            s = _feasible_fix(start, n)
            best = s
            best_score = score(s)
        except Exception:
            pass

    def hex_init(rows, cols):
        pts = []
        for j in range(rows):
            y = (j + 0.5) / rows
            off = 0.5 if j % 2 == 0 else 1.0
            cnt = cols if j % 2 == 0 else cols - 1
            for i in range(cnt):
                x = (i + off) / cols
                pts.append((x, y))
        return pts

    def grid_init(g):
        pts = []
        for j in range(g):
            for i in range(g):
                pts.append(((i + 0.5) / g, (j + 0.5) / g))
        return pts

    inits = []
    for rows, cols in [(6, 6), (5, 7), (7, 5), (6, 7), (8, 4)]:
        p = hex_init(rows, cols)
        if len(p) >= n:
            inits.append(np.array(p[:n]))
    for g in (6, 7):
        p = grid_init(g)
        if len(p) >= n:
            inits.append(np.array(p[:n]))

    def make_cand(centers):
        rlp = _lp_radii(centers, n)
        if rlp is None:
            rlp = np.full(n, 0.05)
        c = np.column_stack([centers, rlp])
        return _feasible_fix(c, n)

    def consider(cand):
        nonlocal best, best_score
        cand = _feasible_fix(cand, n)
        if score(cand) > best_score:
            best_score = score(cand)
            best = cand

    # Polish the start first
    if best is not None and elapsed() < HARD:
        pol = _slsqp_polish(best, n, maxiter=3000, ftol=1e-16)
        pol = _feasible_fix(pol, n)
        if score(pol) > best_score:
            best_score = score(pol)
            best = pol

    for centers in inits:
        if elapsed() > 0.5 * budget_seconds:
            break
        try:
            cand = make_cand(centers)
            consider(cand)
            if elapsed() < 0.5 * budget_seconds:
                pol = _slsqp_polish(cand, n, maxiter=1200)
                pol = _feasible_fix(pol, n)
                if score(pol) > best_score:
                    best_score = score(pol)
                    best = pol
        except Exception:
            pass

    # Random restarts / perturbations around best
    while best is not None and elapsed() < HARD:
        try:
            cand = best.copy()
            scale = rng.uniform(0.01, 0.05)
            cand[:, 0] += rng.normal(0, scale, n)
            cand[:, 1] += rng.normal(0, scale, n)
            cand = _feasible_fix(cand, n)
            newc = make_cand(cand[:, :2])
            pol = _slsqp_polish(newc, n, maxiter=1200)
            pol = _feasible_fix(pol, n)
            if score(pol) > best_score:
                best_score = score(pol)
                best = pol
        except Exception:
            break

    # SLP tangent-space improvement loop
    margin = 1.5
    it = 0
    while best is not None and it < 40 and elapsed() < budget_seconds - margin:
        it += 1
        try:
            v, opt = _slp_step(best, n, delta=2e-3)
        except Exception:
            break
        if v is None or opt < 1e-12:
            break
        try:
            x_new = best.reshape(-1) + 0.5 * v
            x_new = x_new.reshape(n, 3)
            x_new = _feasible_fix(x_new, n)
            pol = _slsqp_polish(x_new, n, maxiter=2000)
            pol = _feasible_fix(pol, n)
            if score(pol) > best_score:
                best = pol
                best_score = score(pol)
            else:
                x_new2 = best.reshape(-1) + 0.25 * v
                x_new2 = _feasible_fix(x_new2.reshape(n, 3), n)
                pol2 = _slsqp_polish(x_new2, n, maxiter=2000)
                pol2 = _feasible_fix(pol2, n)
                if score(pol2) > best_score:
                    best = pol2
                    best_score = score(pol2)
                else:
                    break
        except Exception:
            break

    # ---- Leave-one-out topology change loop ----
    while best is not None and elapsed() < HARD:
        try:
            radii = best[:, 2]
            order = np.argsort(radii)
            # choose among 5 smallest with some randomness
            k = min(5, n)
            if rng.random() < 0.5:
                m = int(order[0])
            else:
                m = int(order[rng.integers(0, k)])
            # 31-circle subproblem
            sub = np.delete(best, m, axis=0)
            sub = _feasible_fix(sub, n - 1)
            r31 = _lp_radii(sub[:, :2], n - 1)
            if r31 is not None:
                sub = np.column_stack([sub[:, :2], r31])
                sub = _feasible_fix(sub, n - 1)
            sub = _slsqp_polish(sub, n - 1, maxiter=1000)
            sub = _feasible_fix(sub, n - 1)
            # find best insertion for circle m
            cx, cy, cr = _best_insert_center(sub[:, :2], sub[:, 2], 0)
            newc = np.vstack([sub, np.array([[cx, cy, cr]])])
            # re-solve LP on all 32
            r32 = _lp_radii(newc[:, :2], n)
            if r32 is not None:
                newc = np.column_stack([newc[:, :2], r32])
            newc = _feasible_fix(newc, n)
            pol = _slsqp_polish(newc, n, maxiter=1500)
            pol = _feasible_fix(pol, n)
            if score(pol) > best_score:
                best = pol
                best_score = score(pol)
        except Exception:
            break

    if best is None:
        if start is not None:
            return _feasible_fix(start, n)
        p = hex_init(6, 6)
        return make_cand(np.array(p[:n]))

    # Final LP re-solve at final centers
    try:
        centers = best[:, :2].copy()
        r = _lp_radii(centers, n)
        if r is not None:
            cand = np.column_stack([centers, r])
            cand = _feasible_fix(cand, n)
            if score(cand) > best_score:
                best = cand
                best_score = score(cand)
    except Exception:
        pass

    return best

import numpy as np
import time
from scipy.optimize import minimize, linprog


def _feasible_fix(x, n):
    x = np.array(x, dtype=float).reshape(n, 3)
    x[:, 2] = np.maximum(x[:, 2], 1e-7)
    x[:, 0] = np.clip(x[:, 0], x[:, 2], 1.0 - x[:, 2])
    x[:, 1] = np.clip(x[:, 1], x[:, 2], 1.0 - x[:, 2])
    for _ in range(200):
        changed = False
        for i in range(n):
            for j in range(i + 1, n):
                dx = x[i, 0] - x[j, 0]
                dy = x[i, 1] - x[j, 1]
                d = np.hypot(dx, dy)
                s = x[i, 2] + x[j, 2]
                if d < s:
                    changed = True
                    excess = s - d + 1e-12
                    if d > 1e-12:
                        ux = dx / d
                        uy = dy / d
                        x[i, 0] += ux * excess * 0.5
                        x[i, 1] += uy * excess * 0.5
                        x[j, 0] -= ux * excess * 0.5
                        x[j, 1] -= uy * excess * 0.5
                    x[i, 2] -= excess * 0.25
                    x[j, 2] -= excess * 0.25
        x[:, 2] = np.maximum(x[:, 2], 1e-7)
        x[:, 0] = np.clip(x[:, 0], x[:, 2], 1.0 - x[:, 2])
        x[:, 1] = np.clip(x[:, 1], x[:, 2], 1.0 - x[:, 2])
        if not changed:
            break
    x[:, 2] *= (1.0 - 1e-13)
    return x


def _lp_radii(centers, n):
    c = -np.ones(n)
    A_ub = []
    b_ub = []
    for i in range(n):
        for w in (centers[i, 0], 1.0 - centers[i, 0],
                  centers[i, 1], 1.0 - centers[i, 1]):
            row = np.zeros(n)
            row[i] = 1.0
            A_ub.append(row)
            b_ub.append(max(w, 0.0))
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(centers[i, 0] - centers[j, 0],
                         centers[i, 1] - centers[j, 1])
            row = np.zeros(n)
            row[i] = 1.0
            row[j] = 1.0
            A_ub.append(row)
            b_ub.append(max(d, 0.0))
    bounds = [(1e-7, None)] * n
    try:
        res = linprog(c, A_ub=np.array(A_ub), b_ub=np.array(b_ub),
                      bounds=bounds, method='highs',
                      options={'primal_feasibility_tolerance': 1e-10,
                               'dual_feasibility_tolerance': 1e-10})
        if res.success:
            return np.maximum(res.x, 1e-7)
    except Exception:
        pass
    return None


def _slsqp_polish(x_init, n, maxiter, ftol=1e-15):
    def obj(v):
        return -np.sum(v[2::3])

    def obj_grad(v):
        g = np.zeros_like(v)
        g[2::3] = -1.0
        return g

    bounds = []
    for i in range(n):
        bounds.append((0.0, 1.0))
        bounds.append((0.0, 1.0))
        bounds.append((1e-5, 0.5))

    cons = []
    for i in range(n):
        for kind in range(4):
            def make_wall(i, kind):
                def f(v):
                    X = v.reshape(n, 3)
                    if kind == 0:
                        return X[i, 0] - X[i, 2]
                    elif kind == 1:
                        return 1.0 - X[i, 0] - X[i, 2]
                    elif kind == 2:
                        return X[i, 1] - X[i, 2]
                    else:
                        return 1.0 - X[i, 1] - X[i, 2]
                def jac(v):
                    g = np.zeros(3 * n)
                    if kind == 0:
                        g[3 * i] = 1.0
                    elif kind == 1:
                        g[3 * i] = -1.0
                    elif kind == 2:
                        g[3 * i + 1] = 1.0
                    else:
                        g[3 * i + 1] = -1.0
                    g[3 * i + 2] = -1.0
                    return g
                return f, jac
            f, j = make_wall(i, kind)
            cons.append({'type': 'ineq', 'fun': f, 'jac': j})

    for i in range(n):
        for j in range(i + 1, n):
            def make_pair(i, j):
                def f(v):
                    X = v.reshape(n, 3)
                    dx = X[i, 0] - X[j, 0]
                    dy = X[i, 1] - X[j, 1]
                    return dx * dx + dy * dy - (X[i, 2] + X[j, 2]) ** 2
                def jac(v):
                    X = v.reshape(n, 3)
                    dx = X[i, 0] - X[j, 0]
                    dy = X[i, 1] - X[j, 1]
                    s = X[i, 2] + X[j, 2]
                    g = np.zeros(3 * n)
                    g[3 * i] = 2.0 * dx
                    g[3 * i + 1] = 2.0 * dy
                    g[3 * i + 2] = -2.0 * s
                    g[3 * j] = -2.0 * dx
                    g[3 * j + 1] = -2.0 * dy
                    g[3 * j + 2] = -2.0 * s
                    return g
                return f, jac
            f, j = make_pair(i, j)
            cons.append({'type': 'ineq', 'fun': f, 'jac': j})

    v0 = x_init.reshape(-1).copy()
    v0[2::3] = np.clip(v0[2::3], 1e-5, 0.5)
    v0[0::3] = np.clip(v0[0::3], 0.0, 1.0)
    v0[1::3] = np.clip(v0[1::3], 0.0, 1.0)
    try:
        res = minimize(obj, v0, jac=obj_grad, method='SLSQP',
                       bounds=bounds, constraints=cons,
                       options={'maxiter': maxiter, 'ftol': ftol})
        return res.x.reshape(n, 3)
    except Exception:
        return x_init


def _slp_step(x, n, delta=2e-3):
    tol = 1e-6
    A_ub = []
    b_ub = []
    for i in range(n):
        for j in range(i + 1, n):
            dx = x[i, 0] - x[j, 0]
            dy = x[i, 1] - x[j, 1]
            d = np.hypot(dx, dy)
            gap = d - x[i, 2] - x[j, 2]
            if gap < tol:
                if d < 1e-12:
                    continue
                ux = dx / d
                uy = dy / d
                row = np.zeros(3 * n)
                row[3 * i] = -ux
                row[3 * i + 1] = -uy
                row[3 * i + 2] = 1.0
                row[3 * j] = ux
                row[3 * j + 1] = uy
                row[3 * j + 2] = 1.0
                A_ub.append(row)
                b_ub.append(0.0)
    for i in range(n):
        if abs(x[i, 0] - x[i, 2]) < tol:
            row = np.zeros(3 * n)
            row[3 * i] = -1.0
            row[3 * i + 2] = 1.0
            A_ub.append(row); b_ub.append(0.0)
        if abs(1.0 - x[i, 0] - x[i, 2]) < tol:
            row = np.zeros(3 * n)
            row[3 * i] = 1.0
            row[3 * i + 2] = 1.0
            A_ub.append(row); b_ub.append(0.0)
        if abs(x[i, 1] - x[i, 2]) < tol:
            row = np.zeros(3 * n)
            row[3 * i + 1] = -1.0
            row[3 * i + 2] = 1.0
            A_ub.append(row); b_ub.append(0.0)
        if abs(1.0 - x[i, 1] - x[i, 2]) < tol:
            row = np.zeros(3 * n)
            row[3 * i + 1] = 1.0
            row[3 * i + 2] = 1.0
            A_ub.append(row); b_ub.append(0.0)
    if not A_ub:
        return None, 0.0
    c = np.zeros(3 * n)
    c[2::3] = -1.0
    bounds = [(-delta, delta)] * (3 * n)
    try:
        res = linprog(c, A_ub=np.array(A_ub), b_ub=np.array(b_ub),
                      bounds=bounds, method='highs',
                      options={'primal_feasibility_tolerance': 1e-10,
                               'dual_feasibility_tolerance': 1e-10})
        if res.success:
            return res.x, -res.fun
    except Exception:
        pass
    return None, 0.0


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 32
    rng = np.random.default_rng(987654321)
    HARD = min(budget_seconds * 0.85, budget_seconds - 0.8)

    def elapsed():
        return time.process_time() - t0

    best = None
    best_score = -1.0

    def score(x):
        return float(np.sum(x[:, 2]))

    if start is not None:
        try:
            s = _feasible_fix(start, n)
            best = s
            best_score = score(s)
        except Exception:
            pass

    def hex_init(rows, cols):
        pts = []
        for j in range(rows):
            y = (j + 0.5) / rows
            off = 0.5 if j % 2 == 0 else 1.0
            cnt = cols if j % 2 == 0 else cols - 1
            for i in range(cnt):
                x = (i + off) / cols
                pts.append((x, y))
        return pts

    def grid_init(g):
        pts = []
        for j in range(g):
            for i in range(g):
                pts.append(((i + 0.5) / g, (j + 0.5) / g))
        return pts

    def make_cand(centers):
        rlp = _lp_radii(centers, n)
        if rlp is None:
            rlp = np.full(n, 0.05)
        c = np.column_stack([centers, rlp])
        return _feasible_fix(c, n)

    def consider(cand):
        nonlocal best, best_score
        cand = _feasible_fix(cand, n)
        sc = score(cand)
        if sc > best_score:
            best_score = sc
            best = cand
            return True
        return False

    # Polish start
    if best is not None and elapsed() < HARD:
        pol = _slsqp_polish(best, n, maxiter=4000, ftol=1e-16)
        pol = _feasible_fix(pol, n)
        if score(pol) > best_score:
            best_score = score(pol)
            best = pol

    inits = []
    for rows, cols in [(6, 6), (5, 7), (7, 5), (6, 7), (8, 4), (7, 6)]:
        p = hex_init(rows, cols)
        if len(p) >= n:
            inits.append(np.array(p[:n]))
    for g in (6, 7):
        p = grid_init(g)
        if len(p) >= n:
            inits.append(np.array(p[:n]))

    # Only try fresh inits if we don't already have a strong start
    if best is None or best_score < 2.85:
        for centers in inits:
            if elapsed() > 0.35 * budget_seconds:
                break
            try:
                cand = make_cand(centers)
                consider(cand)
                if elapsed() < 0.35 * budget_seconds:
                    pol = _slsqp_polish(cand, n, maxiter=1500)
                    pol = _feasible_fix(pol, n)
                    consider(pol)
            except Exception:
                pass

    # SLP tangent-space improvement loop (main effort)
    margin = 1.0
    it = 0
    stall = 0
    while best is not None and it < 200 and elapsed() < HARD - margin:
        it += 1
        try:
            v, opt = _slp_step(best, n, delta=5e-3)
        except Exception:
            break
        if v is None or opt < 1e-13:
            # try random perturbation to escape
            cand = best.copy()
            k = rng.integers(1, 4)
            idx = rng.choice(n, size=k, replace=False)
            cand[idx, 0] += rng.normal(0, 0.02, k)
            cand[idx, 1] += rng.normal(0, 0.02, k)
            cand = _feasible_fix(cand, n)
            newc = make_cand(cand[:, :2])
            pol = _slsqp_polish(newc, n, maxiter=1500)
            pol = _feasible_fix(pol, n)
            if consider(pol):
                stall = 0
            else:
                stall += 1
                if stall > 3:
                    break
            continue
        improved = False
        for step in (1.0, 0.5, 0.25):
            try:
                x_new = (best.reshape(-1) + step * v).reshape(n, 3)
                x_new = _feasible_fix(x_new, n)
                pol = _slsqp_polish(x_new, n, maxiter=2500)
                pol = _feasible_fix(pol, n)
                if consider(pol):
                    improved = True
                    break
            except Exception:
                continue
        if not improved:
            stall += 1
            # random kick
            cand = best.copy()
            idx = rng.choice(n, size=rng.integers(1, 4), replace=False)
            cand[idx, 0] += rng.normal(0, 0.015, len(idx))
            cand[idx, 1] += rng.normal(0, 0.015, len(idx))
            cand = _feasible_fix(cand, n)
            newc = make_cand(cand[:, :2])
            pol = _slsqp_polish(newc, n, maxiter=1500)
            pol = _feasible_fix(pol, n)
            if consider(pol):
                stall = 0
            if stall > 5:
                break
        else:
            stall = 0

    if best is None:
        if start is not None:
            return _feasible_fix(start, n)
        p = hex_init(6, 6)
        return make_cand(np.array(p[:n]))

    # Final LP re-solve
    try:
        centers = best[:, :2].copy()
        r = _lp_radii(centers, n)
        if r is not None:
            cand = np.column_stack([centers, r])
            cand = _feasible_fix(cand, n)
            if score(cand) > best_score:
                best = cand
                best_score = score(cand)
    except Exception:
        pass

    # Final safety: ensure strict feasibility with margin
    best = _feasible_fix(best, n)
    return best

import numpy as np
import time
from scipy.optimize import minimize, linprog


def _feasible_fix(x, n):
    x = np.array(x, dtype=float).reshape(n, 3)
    x[:, 2] = np.maximum(x[:, 2], 1e-6)
    x[:, 0] = np.clip(x[:, 0], x[:, 2], 1.0 - x[:, 2])
    x[:, 1] = np.clip(x[:, 1], x[:, 2], 1.0 - x[:, 2])
    for _ in range(200):
        changed = False
        # vectorized pair check
        dx = x[:, None, 0] - x[None, :, 0]
        dy = x[:, None, 1] - x[None, :, 1]
        d = np.hypot(dx, dy)
        s = x[:, None, 2] + x[None, :, 2]
        np.fill_diagonal(d, 1e9)
        np.fill_diagonal(s, 0.0)
        viol = s - d
        mask = viol > 1e-12
        if mask.any():
            changed = True
            # reduce radii proportionally for each violating pair
            for i in range(n):
                idx = np.where(mask[i])[0]
                for j in idx:
                    if i < j:
                        ov = viol[i, j] + 1e-11
                        x[i, 2] -= ov / 2
                        x[j, 2] -= ov / 2
            x[:, 2] = np.maximum(x[:, 2], 1e-6)
            x[:, 0] = np.clip(x[:, 0], x[:, 2], 1.0 - x[:, 2])
            x[:, 1] = np.clip(x[:, 1], x[:, 2], 1.0 - x[:, 2])
        if not changed:
            break
    x[:, 2] *= (1.0 - 1e-12)
    return x


def _lp_radii(centers, n):
    c = -np.ones(n)
    A_ub = []
    b_ub = []
    for i in range(n):
        for w in (centers[i, 0], 1.0 - centers[i, 0],
                  centers[i, 1], 1.0 - centers[i, 1]):
            row = np.zeros(n)
            row[i] = 1.0
            A_ub.append(row)
            b_ub.append(max(w, 0.0))
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(centers[i, 0] - centers[j, 0],
                         centers[i, 1] - centers[j, 1])
            row = np.zeros(n)
            row[i] = 1.0
            row[j] = 1.0
            A_ub.append(row)
            b_ub.append(max(d, 0.0))
    bounds = [(1e-6, None)] * n
    try:
        res = linprog(c, A_ub=np.array(A_ub), b_ub=np.array(b_ub),
                      bounds=bounds, method='highs',
                      options={'primal_feasibility_tolerance': 1e-10,
                               'dual_feasibility_tolerance': 1e-10})
        if res.success:
            return np.maximum(res.x, 1e-6)
    except Exception:
        pass
    return None


def _slsqp_polish(x_init, n, maxiter, ftol=1e-14):
    def obj(v):
        return -np.sum(v[2::3])

    def obj_grad(v):
        g = np.zeros_like(v)
        g[2::3] = -1.0
        return g

    bounds = []
    for i in range(n):
        bounds.append((0.0, 1.0))
        bounds.append((0.0, 1.0))
        bounds.append((1e-4, 0.5))

    cons = []
    for i in range(n):
        for kind in range(4):
            def make_wall(i, kind):
                def f(v):
                    X = v.reshape(n, 3)
                    if kind == 0:
                        return X[i, 0] - X[i, 2]
                    elif kind == 1:
                        return 1.0 - X[i, 0] - X[i, 2]
                    elif kind == 2:
                        return X[i, 1] - X[i, 2]
                    else:
                        return 1.0 - X[i, 1] - X[i, 2]
                def jac(v):
                    g = np.zeros(3 * n)
                    if kind == 0:
                        g[3 * i] = 1.0
                    elif kind == 1:
                        g[3 * i] = -1.0
                    elif kind == 2:
                        g[3 * i + 1] = 1.0
                    else:
                        g[3 * i + 1] = -1.0
                    g[3 * i + 2] = -1.0
                    return g
                return f, jac
            f, j = make_wall(i, kind)
            cons.append({'type': 'ineq', 'fun': f, 'jac': j})

    for i in range(n):
        for j in range(i + 1, n):
            def make_pair(i, j):
                def f(v):
                    X = v.reshape(n, 3)
                    dx = X[i, 0] - X[j, 0]
                    dy = X[i, 1] - X[j, 1]
                    return dx * dx + dy * dy - (X[i, 2] + X[j, 2]) ** 2
                def jac(v):
                    X = v.reshape(n, 3)
                    dx = X[i, 0] - X[j, 0]
                    dy = X[i, 1] - X[j, 1]
                    s = X[i, 2] + X[j, 2]
                    g = np.zeros(3 * n)
                    g[3 * i] = 2.0 * dx
                    g[3 * i + 1] = 2.0 * dy
                    g[3 * i + 2] = -2.0 * s
                    g[3 * j] = -2.0 * dx
                    g[3 * j + 1] = -2.0 * dy
                    g[3 * j + 2] = -2.0 * s
                    return g
                return f, jac
            f, j = make_pair(i, j)
            cons.append({'type': 'ineq', 'fun': f, 'jac': j})

    v0 = x_init.reshape(-1).copy()
    v0[2::3] = np.clip(v0[2::3], 1e-4, 0.5)
    v0[0::3] = np.clip(v0[0::3], 0.0, 1.0)
    v0[1::3] = np.clip(v0[1::3], 0.0, 1.0)
    try:
        res = minimize(obj, v0, jac=obj_grad, method='SLSQP',
                       bounds=bounds, constraints=cons,
                       options={'maxiter': maxiter, 'ftol': ftol})
        return res.x.reshape(n, 3)
    except Exception:
        return x_init


def _slp_step(x, n, delta=2e-3):
    """Linearized SLP step: move centers & radii to increase sum(r) while
    keeping first-order contact constraints."""
    tol = 5e-6
    A_ub = []
    b_ub = []
    for i in range(n):
        for j in range(i + 1, n):
            dx = x[i, 0] - x[j, 0]
            dy = x[i, 1] - x[j, 1]
            d = np.hypot(dx, dy)
            gap = d - x[i, 2] - x[j, 2]
            if gap < tol and d > 1e-12:
                ux = dx / d
                uy = dy / d
                row = np.zeros(3 * n)
                row[3 * i] = -ux
                row[3 * i + 1] = -uy
                row[3 * i + 2] = 1.0
                row[3 * j] = ux
                row[3 * j + 1] = uy
                row[3 * j + 2] = 1.0
                A_ub.append(row)
                b_ub.append(gap)
    for i in range(n):
        g = x[i, 0] - x[i, 2]
        if g < tol:
            row = np.zeros(3 * n)
            row[3 * i] = -1.0
            row[3 * i + 2] = 1.0
            A_ub.append(row); b_ub.append(g)
        g = 1.0 - x[i, 0] - x[i, 2]
        if g < tol:
            row = np.zeros(3 * n)
            row[3 * i] = 1.0
            row[3 * i + 2] = 1.0
            A_ub.append(row); b_ub.append(g)
        g = x[i, 1] - x[i, 2]
        if g < tol:
            row = np.zeros(3 * n)
            row[3 * i + 1] = -1.0
            row[3 * i + 2] = 1.0
            A_ub.append(row); b_ub.append(g)
        g = 1.0 - x[i, 1] - x[i, 2]
        if g < tol:
            row = np.zeros(3 * n)
            row[3 * i + 1] = 1.0
            row[3 * i + 2] = 1.0
            A_ub.append(row); b_ub.append(g)
    if not A_ub:
        return None
    c = np.zeros(3 * n)
    c[2::3] = -1.0
    bounds = [(-delta, delta)] * (3 * n)
    try:
        res = linprog(c, A_ub=np.array(A_ub), b_ub=np.array(b_ub),
                      bounds=bounds, method='highs',
                      options={'primal_feasibility_tolerance': 1e-10,
                               'dual_feasibility_tolerance': 1e-10})
        if res.success:
            return res.x
    except Exception:
        pass
    return None


def _slp_improve(x, n, deadline, elapsed, max_iters=400):
    """Iteratively apply SLP steps, then re-project via LP radii."""
    best = x.copy()
    best_s = float(np.sum(x[:, 2]))
    cur = x.copy()
    for _ in range(max_iters):
        if elapsed() > deadline:
            break
        step = _slp_step(cur, n, delta=5e-3)
        if step is None:
            break
        cand = cur + step.reshape(n, 3)
        cand = _feasible_fix(cand, n)
        # re-project radii to LP-optimal at new centers
        rlp = _lp_radii(cand[:, :2], n)
        if rlp is not None:
            cand2 = np.column_stack([cand[:, :2], rlp])
            cand2 = _feasible_fix(cand2, n)
            if float(np.sum(cand2[:, 2])) > float(np.sum(cand[:, 2])):
                cand = cand2
        s = float(np.sum(cand[:, 2]))
        if s > best_s + 1e-10:
            best_s = s
            best = cand
            cur = cand
        else:
            # tiny kick in random direction, then continue
            cur = cand
            if s < best_s - 1e-6:
                cur = best.copy()
                break
    return best


def _score(x):
    return float(np.sum(x[:, 2]))


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 32
    rng = np.random.default_rng(2024)
    HARD = min(9.0, 0.9 * budget_seconds)

    def elapsed():
        return time.process_time() - t0

    best = None
    best_score = -1.0

    if start is not None:
        try:
            s = _feasible_fix(start, n)
            best = s
            best_score = _score(s)
        except Exception:
            pass

    def hex_init(rows, cols):
        pts = []
        for j in range(rows):
            y = (j + 0.5) / rows
            off = 0.5 if j % 2 == 0 else 1.0
            cnt = cols if j % 2 == 0 else cols - 1
            for i in range(cnt):
                x = (i + off) / cols
                pts.append((x, y))
        return pts

    def grid_init(g):
        pts = []
        for j in range(g):
            for i in range(g):
                pts.append(((i + 0.5) / g, (j + 0.5) / g))
        return pts

    inits = []
    for rows, cols in [(6, 6), (5, 7), (7, 5), (6, 7)]:
        p = hex_init(rows, cols)
        if len(p) >= n:
            inits.append(np.array(p[:n]))
    for g in (6, 7):
        p = grid_init(g)
        if len(p) >= n:
            inits.append(np.array(p[:n]))

    def make_cand(centers):
        rlp = _lp_radii(centers, n)
        if rlp is None:
            rlp = np.full(n, 0.05)
        c = np.column_stack([centers, rlp])
        return _feasible_fix(c, n)

    def consider(cand, deadline):
        nonlocal best, best_score
        cand = _feasible_fix(cand, n)
        if _score(cand) > best_score:
            best_score = _score(cand)
            best = cand
        if elapsed() < deadline:
            pol = _slsqp_polish(cand, n, maxiter=1500)
            pol = _feasible_fix(pol, n)
            if _score(pol) > best_score:
                best_score = _score(pol)
                best = pol

    # 1) Aggressive SLP-based improvement of the start
    if best is not None and elapsed() < HARD:
        d1 = min(0.45 * budget_seconds, HARD)
        imp = _slp_improve(best, n, d1, elapsed)
        if _score(imp) > best_score:
            best = imp
            best_score = _score(imp)
        if elapsed() < d1:
            pol = _slsqp_polish(best, n, maxiter=2000)
            pol = _feasible_fix(pol, n)
            if _score(pol) > best_score:
                best = pol
                best_score = _score(pol)
        # another SLP round after SLSQP
        if elapsed() < HARD:
            d2 = min(0.65 * budget_seconds, HARD)
            imp = _slp_improve(best, n, d2, elapsed)
            if _score(imp) > best_score:
                best = imp
                best_score = _score(imp)

    # 2) Try structured initial configurations (only if time remains)
    for idx, centers in enumerate(inits):
        if elapsed() > 0.70 * budget_seconds or elapsed() > HARD:
            break
        try:
            cand = make_cand(centers)
            consider(cand, min(0.70 * budget_seconds, HARD))
        except Exception:
            pass

    # 3) Randomized perturbation of the best + SLP polish
    if best is not None:
        while elapsed() < HARD:
            try:
                cand = best.copy()
                scale = rng.uniform(0.005, 0.04)
                cand[:, 0] += rng.normal(0, scale, n)
                cand[:, 1] += rng.normal(0, scale, n)
                cand = _feasible_fix(cand, n)
                cand = make_cand(cand[:, :2])
                imp = _slp_improve(cand, n,
                                   min(elapsed() + 0.3, HARD), elapsed,
                                   max_iters=60)
                if _score(imp) > best_score:
                    best = imp
                    best_score = _score(imp)
                if elapsed() < HARD - 0.3:
                    pol = _slsqp_polish(imp, n, maxiter=800)
                    pol = _feasible_fix(pol, n)
                    if _score(pol) > best_score:
                        best = pol
                        best_score = _score(pol)
            except Exception:
                break

    if best is None:
        if start is not None:
            return _feasible_fix(start, n)
        centers = np.array(grid_init(6)[:n])
        return _feasible_fix(np.column_stack([centers, np.full(n, 0.07)]), n)

    # final safety shrink so exact checker passes
    best = best.copy()
    best[:, 2] *= (1.0 - 1e-9)
    best = _feasible_fix(best, n)
    return best

import numpy as np
import time
from scipy.optimize import minimize, linprog


def _feasible_fix(x, n):
    x = np.array(x, dtype=float).reshape(n, 3)
    x[:, 2] = np.maximum(x[:, 2], 1e-6)
    x[:, 0] = np.clip(x[:, 0], x[:, 2], 1.0 - x[:, 2])
    x[:, 1] = np.clip(x[:, 1], x[:, 2], 1.0 - x[:, 2])
    for _ in range(100):
        changed = False
        for i in range(n):
            for j in range(i + 1, n):
                dx = x[i, 0] - x[j, 0]
                dy = x[i, 1] - x[j, 1]
                d = np.hypot(dx, dy)
                s = x[i, 2] + x[j, 2]
                if d < s:
                    changed = True
                    excess = s - d + 1e-11
                    x[i, 2] -= excess / 2
                    x[j, 2] -= excess / 2
        x[:, 2] = np.maximum(x[:, 2], 1e-6)
        x[:, 0] = np.clip(x[:, 0], x[:, 2], 1.0 - x[:, 2])
        x[:, 1] = np.clip(x[:, 1], x[:, 2], 1.0 - x[:, 2])
        if not changed:
            break
    x[:, 2] *= (1.0 - 1e-12)
    return x


def _lp_radii(centers, n):
    c = -np.ones(n)
    A_ub = []
    b_ub = []
    for i in range(n):
        for w in (centers[i, 0], 1.0 - centers[i, 0],
                  centers[i, 1], 1.0 - centers[i, 1]):
            row = np.zeros(n)
            row[i] = 1.0
            A_ub.append(row)
            b_ub.append(max(w, 0.0))
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(centers[i, 0] - centers[j, 0],
                         centers[i, 1] - centers[j, 1])
            row = np.zeros(n)
            row[i] = 1.0
            row[j] = 1.0
            A_ub.append(row)
            b_ub.append(max(d, 0.0))
    bounds = [(1e-6, None)] * n
    try:
        res = linprog(c, A_ub=np.array(A_ub), b_ub=np.array(b_ub),
                      bounds=bounds, method='highs',
                      options={'primal_feasibility_tolerance': 1e-10,
                               'dual_feasibility_tolerance': 1e-10})
        if res.success:
            return np.maximum(res.x, 1e-6)
    except Exception:
        pass
    return None


def _slsqp_polish(x_init, n, maxiter, ftol=1e-14):
    def obj(v):
        return -np.sum(v[2::3])

    def obj_grad(v):
        g = np.zeros_like(v)
        g[2::3] = -1.0
        return g

    bounds = []
    for i in range(n):
        bounds.append((0.0, 1.0))
        bounds.append((0.0, 1.0))
        bounds.append((1e-4, 0.5))

    cons = []
    for i in range(n):
        for kind in range(4):
            def make_wall(i, kind):
                def f(v):
                    X = v.reshape(n, 3)
                    if kind == 0:
                        return X[i, 0] - X[i, 2]
                    elif kind == 1:
                        return 1.0 - X[i, 0] - X[i, 2]
                    elif kind == 2:
                        return X[i, 1] - X[i, 2]
                    else:
                        return 1.0 - X[i, 1] - X[i, 2]
                def jac(v):
                    g = np.zeros(3 * n)
                    if kind == 0:
                        g[3 * i] = 1.0
                    elif kind == 1:
                        g[3 * i] = -1.0
                    elif kind == 2:
                        g[3 * i + 1] = 1.0
                    else:
                        g[3 * i + 1] = -1.0
                    g[3 * i + 2] = -1.0
                    return g
                return f, jac
            f, j = make_wall(i, kind)
            cons.append({'type': 'ineq', 'fun': f, 'jac': j})

    for i in range(n):
        for j in range(i + 1, n):
            def make_pair(i, j):
                def f(v):
                    X = v.reshape(n, 3)
                    dx = X[i, 0] - X[j, 0]
                    dy = X[i, 1] - X[j, 1]
                    return dx * dx + dy * dy - (X[i, 2] + X[j, 2]) ** 2
                def jac(v):
                    X = v.reshape(n, 3)
                    dx = X[i, 0] - X[j, 0]
                    dy = X[i, 1] - X[j, 1]
                    s = X[i, 2] + X[j, 2]
                    g = np.zeros(3 * n)
                    g[3 * i] = 2.0 * dx
                    g[3 * i + 1] = 2.0 * dy
                    g[3 * i + 2] = -2.0 * s
                    g[3 * j] = -2.0 * dx
                    g[3 * j + 1] = -2.0 * dy
                    g[3 * j + 2] = -2.0 * s
                    return g
                return f, jac
            f, j = make_pair(i, j)
            cons.append({'type': 'ineq', 'fun': f, 'jac': j})

    v0 = x_init.reshape(-1).copy()
    v0[2::3] = np.clip(v0[2::3], 1e-4, 0.5)
    v0[0::3] = np.clip(v0[0::3], 0.0, 1.0)
    v0[1::3] = np.clip(v0[1::3], 0.0, 1.0)
    try:
        res = minimize(obj, v0, jac=obj_grad, method='SLSQP',
                       bounds=bounds, constraints=cons,
                       options={'maxiter': maxiter, 'ftol': ftol})
        return res.x.reshape(n, 3)
    except Exception:
        return x_init


def _slp_step(x, n, delta=2e-3):
    """Solve tangent-space LP over v=[dcx,dcy,dr] for active constraints.
    Returns (v, opt) or (None, 0)."""
    tol = 1e-6
    A_ub = []
    b_ub = []
    for i in range(n):
        for j in range(i + 1, n):
            dx = x[i, 0] - x[j, 0]
            dy = x[i, 1] - x[j, 1]
            d = np.hypot(dx, dy)
            gap = d - x[i, 2] - x[j, 2]
            if gap < tol:
                if d < 1e-12:
                    continue
                ux = dx / d
                uy = dy / d
                row = np.zeros(3 * n)
                row[3 * i] = -ux
                row[3 * i + 1] = -uy
                row[3 * i + 2] = 1.0
                row[3 * j] = ux
                row[3 * j + 1] = uy
                row[3 * j + 2] = 1.0
                A_ub.append(row)
                b_ub.append(0.0)
    for i in range(n):
        if abs(x[i, 0] - x[i, 2]) < tol:
            row = np.zeros(3 * n)
            row[3 * i] = -1.0
            row[3 * i + 2] = 1.0
            A_ub.append(row); b_ub.append(0.0)
        if abs(1.0 - x[i, 0] - x[i, 2]) < tol:
            row = np.zeros(3 * n)
            row[3 * i] = 1.0
            row[3 * i + 2] = 1.0
            A_ub.append(row); b_ub.append(0.0)
        if abs(x[i, 1] - x[i, 2]) < tol:
            row = np.zeros(3 * n)
            row[3 * i + 1] = -1.0
            row[3 * i + 2] = 1.0
            A_ub.append(row); b_ub.append(0.0)
        if abs(1.0 - x[i, 1] - x[i, 2]) < tol:
            row = np.zeros(3 * n)
            row[3 * i + 1] = 1.0
            row[3 * i + 2] = 1.0
            A_ub.append(row); b_ub.append(0.0)
    if not A_ub:
        return None, 0.0
    c = np.zeros(3 * n)
    c[2::3] = -1.0
    bounds = [(-delta, delta)] * (3 * n)
    try:
        res = linprog(c, A_ub=np.array(A_ub), b_ub=np.array(b_ub),
                      bounds=bounds, method='highs',
                      options={'primal_feasibility_tolerance': 1e-10,
                               'dual_feasibility_tolerance': 1e-10})
        if res.success:
            return res.x, -res.fun
    except Exception:
        pass
    return None, 0.0


def _active_matrix(x, n, tol=1e-6):
    """Build equality matrix A (rows = active constraints) so that A v = 0."""
    rows = []
    for i in range(n):
        for j in range(i + 1, n):
            dx = x[i, 0] - x[j, 0]
            dy = x[i, 1] - x[j, 1]
            d = np.hypot(dx, dy)
            gap = d - x[i, 2] - x[j, 2]
            if gap < tol and d > 1e-12:
                ux = dx / d
                uy = dy / d
                row = np.zeros(3 * n)
                row[3 * i] = -ux
                row[3 * i + 1] = -uy
                row[3 * i + 2] = 1.0
                row[3 * j] = ux
                row[3 * j + 1] = uy
                row[3 * j + 2] = 1.0
                rows.append(row)
    for i in range(n):
        if abs(x[i, 0] - x[i, 2]) < tol:
            row = np.zeros(3 * n)
            row[3 * i] = -1.0
            row[3 * i + 2] = 1.0
            rows.append(row)
        if abs(1.0 - x[i, 0] - x[i, 2]) < tol:
            row = np.zeros(3 * n)
            row[3 * i] = 1.0
            row[3 * i + 2] = 1.0
            rows.append(row)
        if abs(x[i, 1] - x[i, 2]) < tol:
            row = np.zeros(3 * n)
            row[3 * i + 1] = -1.0
            row[3 * i + 2] = 1.0
            rows.append(row)
        if abs(1.0 - x[i, 1] - x[i, 2]) < tol:
            row = np.zeros(3 * n)
            row[3 * i + 1] = 1.0
            row[3 * i + 2] = 1.0
            rows.append(row)
    if not rows:
        return None
    return np.array(rows)


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 32
    rng = np.random.default_rng(12345)
    HARD = min(budget_seconds * 0.82, budget_seconds - 1.2)

    def elapsed():
        return time.process_time() - t0

    best = None
    best_score = -1.0

    def score(x):
        return float(np.sum(x[:, 2]))

    if start is not None:
        try:
            s = _feasible_fix(start, n)
            best = s
            best_score = score(s)
        except Exception:
            pass

    def hex_init(rows, cols):
        pts = []
        for j in range(rows):
            y = (j + 0.5) / rows
            off = 0.5 if j % 2 == 0 else 1.0
            cnt = cols if j % 2 == 0 else cols - 1
            for i in range(cnt):
                x = (i + off) / cols
                pts.append((x, y))
        return pts

    def grid_init(g):
        pts = []
        for j in range(g):
            for i in range(g):
                pts.append(((i + 0.5) / g, (j + 0.5) / g))
        return pts

    inits = []
    for rows, cols in [(6, 6), (5, 7), (7, 5), (6, 7), (8, 4)]:
        p = hex_init(rows, cols)
        if len(p) >= n:
            inits.append(np.array(p[:n]))
    for g in (6, 7):
        p = grid_init(g)
        if len(p) >= n:
            inits.append(np.array(p[:n]))

    def make_cand(centers):
        rlp = _lp_radii(centers, n)
        if rlp is None:
            rlp = np.full(n, 0.05)
        c = np.column_stack([centers, rlp])
        return _feasible_fix(c, n)

    def consider(cand):
        nonlocal best, best_score
        cand = _feasible_fix(cand, n)
        if score(cand) > best_score:
            best_score = score(cand)
            best = cand

    if best is not None and elapsed() < HARD:
        pol = _slsqp_polish(best, n, maxiter=3000, ftol=1e-16)
        pol = _feasible_fix(pol, n)
        if score(pol) > best_score:
            best_score = score(pol)
            best = pol

    for centers in inits:
        if elapsed() > 0.5 * budget_seconds:
            break
        try:
            cand = make_cand(centers)
            consider(cand)
            if elapsed() < 0.5 * budget_seconds:
                pol = _slsqp_polish(cand, n, maxiter=1200)
                pol = _feasible_fix(pol, n)
                if score(pol) > best_score:
                    best_score = score(pol)
                    best = pol
        except Exception:
            pass

    while best is not None and elapsed() < HARD:
        try:
            cand = best.copy()
            scale = rng.uniform(0.01, 0.05)
            cand[:, 0] += rng.normal(0, scale, n)
            cand[:, 1] += rng.normal(0, scale, n)
            cand = _feasible_fix(cand, n)
            newc = make_cand(cand[:, :2])
            pol = _slsqp_polish(newc, n, maxiter=1200)
            pol = _feasible_fix(pol, n)
            if score(pol) > best_score:
                best_score = score(pol)
                best = pol
        except Exception:
            break

    if best is None:
        if start is not None:
            return _feasible_fix(start, n)
        p = hex_init(6, 6)
        return make_cand(np.array(p[:n]))

    try:
        centers = best[:, :2].copy()
        r = _lp_radii(centers, n)
        if r is not None:
            cand = np.column_stack([centers, r])
            cand = _feasible_fix(cand, n)
            if score(cand) > best_score:
                best = cand
                best_score = score(cand)
    except Exception:
        pass

    margin = 1.5
    it = 0
    while best is not None and it < 40 and elapsed() < budget_seconds - margin:
        it += 1
        try:
            v, opt = _slp_step(best, n, delta=2e-3)
        except Exception:
            break
        if v is None or opt < 1e-12:
            break
        try:
            x_new = best.reshape(-1) + 0.5 * v
            x_new = x_new.reshape(n, 3)
            x_new = _feasible_fix(x_new, n)
            pol = _slsqp_polish(x_new, n, maxiter=2000)
            pol = _feasible_fix(pol, n)
            if score(pol) > best_score:
                best = pol
                best_score = score(pol)
            else:
                x_new2 = best.reshape(-1) + 0.25 * v
                x_new2 = _feasible_fix(x_new2.reshape(n, 3), n)
                pol2 = _slsqp_polish(x_new2, n, maxiter=2000)
                pol2 = _feasible_fix(pol2, n)
                if score(pol2) > best_score:
                    best = pol2
                    best_score = score(pol2)
                else:
                    break
        except Exception:
            break

    # NEW: null-space random-walk moves
    n_attempts = 0
    n_improved = 0
    while best is not None and elapsed() < budget_seconds - 0.8:
        n_attempts += 1
        try:
            A = _active_matrix(best, n, tol=1e-6)
            if A is None or A.shape[0] == 0:
                break
            try:
                _, sv, Vt = np.linalg.svd(A, full_matrices=True)
            except Exception:
                break
            # null space: rows of Vt with singular value < 1e-8
            null_mask = np.ones(Vt.shape[0], dtype=bool)
            k = min(len(sv), Vt.shape[0])
            null_mask[:k] = sv < 1e-8
            N = Vt[null_mask].T  # shape (3n, d)
            if N.shape[1] == 0:
                break
            u = rng.normal(size=N.shape[1])
            nu = np.linalg.norm(u)
            if nu < 1e-12:
                continue
            u /= nu
            s = rng.uniform(0.005, 0.03)
            step = (N @ u) * s
            x_new = best.reshape(-1) + step
            x_new = _feasible_fix(x_new.reshape(n, 3), n)
            pol = _slsqp_polish(x_new, n, maxiter=2000)
            pol = _feasible_fix(pol, n)
            if score(pol) > best_score + 1e-12:
                best = pol
                best_score = score(pol)
                n_improved += 1
        except Exception:
            break

    print("null-space attempts:", n_attempts, "improved:", n_improved,
          "score:", best_score)

    return best

import numpy as np
import time
from scipy.optimize import minimize, linprog


def _feasible_fix(x, n, shrink=1e-12):
    x = np.array(x, dtype=float).reshape(n, 3)
    x[:, 2] = np.maximum(x[:, 2], 1e-7)
    x[:, 0] = np.clip(x[:, 0], x[:, 2], 1.0 - x[:, 2])
    x[:, 1] = np.clip(x[:, 1], x[:, 2], 1.0 - x[:, 2])
    for _ in range(300):
        changed = False
        for i in range(n):
            for j in range(i + 1, n):
                dx = x[i, 0] - x[j, 0]
                dy = x[i, 1] - x[j, 1]
                d = np.hypot(dx, dy)
                s = x[i, 2] + x[j, 2]
                if d < s:
                    changed = True
                    excess = s - d + 1e-12
                    if d > 1e-12:
                        ux = dx / d
                        uy = dy / d
                        x[i, 0] += ux * excess * 0.5
                        x[i, 1] += uy * excess * 0.5
                        x[j, 0] -= ux * excess * 0.5
                        x[j, 1] -= uy * excess * 0.5
                    x[i, 2] -= excess * 0.25
                    x[j, 2] -= excess * 0.25
        x[:, 2] = np.maximum(x[:, 2], 1e-7)
        x[:, 0] = np.clip(x[:, 0], x[:, 2], 1.0 - x[:, 2])
        x[:, 1] = np.clip(x[:, 1], x[:, 2], 1.0 - x[:, 2])
        if not changed:
            break
    x[:, 2] *= (1.0 - shrink)
    return x


def _lp_radii(centers, n):
    c = -np.ones(n)
    A_ub = []
    b_ub = []
    for i in range(n):
        for w in (centers[i, 0], 1.0 - centers[i, 0],
                  centers[i, 1], 1.0 - centers[i, 1]):
            row = np.zeros(n)
            row[i] = 1.0
            A_ub.append(row)
            b_ub.append(max(w, 0.0))
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(centers[i, 0] - centers[j, 0],
                         centers[i, 1] - centers[j, 1])
            row = np.zeros(n)
            row[i] = 1.0
            row[j] = 1.0
            A_ub.append(row)
            b_ub.append(max(d, 0.0))
    bounds = [(1e-7, None)] * n
    try:
        res = linprog(c, A_ub=np.array(A_ub), b_ub=np.array(b_ub),
                      bounds=bounds, method='highs',
                      options={'primal_feasibility_tolerance': 1e-10,
                               'dual_feasibility_tolerance': 1e-10})
        if res.success:
            return np.maximum(res.x, 1e-7)
    except Exception:
        pass
    return None


def _slsqp_polish(x_init, n, maxiter, ftol=1e-15):
    def obj(v):
        return -np.sum(v[2::3])

    def obj_grad(v):
        g = np.zeros_like(v)
        g[2::3] = -1.0
        return g

    bounds = []
    for i in range(n):
        bounds.append((0.0, 1.0))
        bounds.append((0.0, 1.0))
        bounds.append((1e-5, 0.5))

    cons = []
    for i in range(n):
        for kind in range(4):
            def make_wall(i, kind):
                def f(v):
                    X = v.reshape(n, 3)
                    if kind == 0:
                        return X[i, 0] - X[i, 2]
                    elif kind == 1:
                        return 1.0 - X[i, 0] - X[i, 2]
                    elif kind == 2:
                        return X[i, 1] - X[i, 2]
                    else:
                        return 1.0 - X[i, 1] - X[i, 2]
                def jac(v):
                    g = np.zeros(3 * n)
                    if kind == 0:
                        g[3 * i] = 1.0
                    elif kind == 1:
                        g[3 * i] = -1.0
                    elif kind == 2:
                        g[3 * i + 1] = 1.0
                    else:
                        g[3 * i + 1] = -1.0
                    g[3 * i + 2] = -1.0
                    return g
                return f, jac
            f, j = make_wall(i, kind)
            cons.append({'type': 'ineq', 'fun': f, 'jac': j})

    for i in range(n):
        for j in range(i + 1, n):
            def make_pair(i, j):
                def f(v):
                    X = v.reshape(n, 3)
                    dx = X[i, 0] - X[j, 0]
                    dy = X[i, 1] - X[j, 1]
                    return dx * dx + dy * dy - (X[i, 2] + X[j, 2]) ** 2
                def jac(v):
                    X = v.reshape(n, 3)
                    dx = X[i, 0] - X[j, 0]
                    dy = X[i, 1] - X[j, 1]
                    s = X[i, 2] + X[j, 2]
                    g = np.zeros(3 * n)
                    g[3 * i] = 2.0 * dx
                    g[3 * i + 1] = 2.0 * dy
                    g[3 * i + 2] = -2.0 * s
                    g[3 * j] = -2.0 * dx
                    g[3 * j + 1] = -2.0 * dy
                    g[3 * j + 2] = -2.0 * s
                    return g
                return f, jac
            f, j = make_pair(i, j)
            cons.append({'type': 'ineq', 'fun': f, 'jac': j})

    v0 = x_init.reshape(-1).copy()
    v0[2::3] = np.clip(v0[2::3], 1e-5, 0.5)
    v0[0::3] = np.clip(v0[0::3], 0.0, 1.0)
    v0[1::3] = np.clip(v0[1::3], 0.0, 1.0)
    try:
        res = minimize(obj, v0, jac=obj_grad, method='SLSQP',
                       bounds=bounds, constraints=cons,
                       options={'maxiter': maxiter, 'ftol': ftol})
        return res.x.reshape(n, 3)
    except Exception:
        return x_init


def _slp_step(x, n, delta=2e-3):
    tol = 1e-6
    A_ub = []
    b_ub = []
    for i in range(n):
        for j in range(i + 1, n):
            dx = x[i, 0] - x[j, 0]
            dy = x[i, 1] - x[j, 1]
            d = np.hypot(dx, dy)
            gap = d - x[i, 2] - x[j, 2]
            if gap < tol:
                if d < 1e-12:
                    continue
                ux = dx / d
                uy = dy / d
                row = np.zeros(3 * n)
                row[3 * i] = -ux
                row[3 * i + 1] = -uy
                row[3 * i + 2] = 1.0
                row[3 * j] = ux
                row[3 * j + 1] = uy
                row[3 * j + 2] = 1.0
                A_ub.append(row)
                b_ub.append(0.0)
    for i in range(n):
        if abs(x[i, 0] - x[i, 2]) < tol:
            row = np.zeros(3 * n)
            row[3 * i] = -1.0
            row[3 * i + 2] = 1.0
            A_ub.append(row); b_ub.append(0.0)
        if abs(1.0 - x[i, 0] - x[i, 2]) < tol:
            row = np.zeros(3 * n)
            row[3 * i] = 1.0
            row[3 * i + 2] = 1.0
            A_ub.append(row); b_ub.append(0.0)
        if abs(x[i, 1] - x[i, 2]) < tol:
            row = np.zeros(3 * n)
            row[3 * i + 1] = -1.0
            row[3 * i + 2] = 1.0
            A_ub.append(row); b_ub.append(0.0)
        if abs(1.0 - x[i, 1] - x[i, 2]) < tol:
            row = np.zeros(3 * n)
            row[3 * i + 1] = 1.0
            row[3 * i + 2] = 1.0
            A_ub.append(row); b_ub.append(0.0)
    if not A_ub:
        return None, 0.0
    c = np.zeros(3 * n)
    c[2::3] = -1.0
    bounds = [(-delta, delta)] * (3 * n)
    try:
        res = linprog(c, A_ub=np.array(A_ub), b_ub=np.array(b_ub),
                      bounds=bounds, method='highs',
                      options={'primal_feasibility_tolerance': 1e-10,
                               'dual_feasibility_tolerance': 1e-10})
        if res.success:
            return res.x, -res.fun
    except Exception:
        pass
    return None, 0.0


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 32
    rng = np.random.default_rng(12345)
    HARD = min(budget_seconds * 0.85, budget_seconds - 0.8)

    def elapsed():
        return time.process_time() - t0

    best = None
    best_score = -1.0

    def score(x):
        return float(np.sum(x[:, 2]))

    if start is not None:
        try:
            s = _feasible_fix(start, n)
            best = s
            best_score = score(s)
        except Exception:
            pass

    def hex_init(rows, cols):
        pts = []
        for j in range(rows):
            y = (j + 0.5) / rows
            off = 0.5 if j % 2 == 0 else 1.0
            cnt = cols if j % 2 == 0 else cols - 1
            for i in range(cnt):
                x = (i + off) / cols
                pts.append((x, y))
        return pts

    def grid_init(g):
        pts = []
        for j in range(g):
            for i in range(g):
                pts.append(((i + 0.5) / g, (j + 0.5) / g))
        return pts

    def make_cand(centers):
        rlp = _lp_radii(centers, n)
        if rlp is None:
            rlp = np.full(n, 0.05)
        c = np.column_stack([centers, rlp])
        return _feasible_fix(c, n)

    def consider(cand):
        nonlocal best, best_score
        cand = _feasible_fix(cand, n)
        sc = score(cand)
        if sc > best_score:
            best_score = sc
            best = cand
            return True
        return False

    # Polish start
    if best is not None and elapsed() < HARD:
        pol = _slsqp_polish(best, n, maxiter=4000, ftol=1e-16)
        pol = _feasible_fix(pol, n)
        if score(pol) > best_score:
            best_score = score(pol)
            best = pol

    inits = []
    for rows, cols in [(6, 6), (5, 7), (7, 5), (6, 7), (8, 4), (7, 6)]:
        p = hex_init(rows, cols)
        if len(p) >= n:
            inits.append(np.array(p[:n]))
    for g in (6, 7):
        p = grid_init(g)
        if len(p) >= n:
            inits.append(np.array(p[:n]))

    if best is None or best_score < 2.85:
        for centers in inits:
            if elapsed() > 0.35 * budget_seconds:
                break
            try:
                cand = make_cand(centers)
                consider(cand)
                if elapsed() < 0.35 * budget_seconds:
                    pol = _slsqp_polish(cand, n, maxiter=1500)
                    pol = _feasible_fix(pol, n)
                    consider(pol)
            except Exception:
                pass

    # SLP tangent-space improvement loop
    margin = 1.0
    it = 0
    stall = 0
    while best is not None and it < 200 and elapsed() < HARD - margin:
        it += 1
        try:
            v, opt = _slp_step(best, n, delta=5e-3)
        except Exception:
            break
        if v is None or opt < 1e-13:
            cand = best.copy()
            k = rng.integers(1, 4)
            idx = rng.choice(n, size=k, replace=False)
            cand[idx, 0] += rng.normal(0, 0.02, k)
            cand[idx, 1] += rng.normal(0, 0.02, k)
            cand = _feasible_fix(cand, n)
            newc = make_cand(cand[:, :2])
            pol = _slsqp_polish(newc, n, maxiter=1500)
            pol = _feasible_fix(pol, n)
            if consider(pol):
                stall = 0
            else:
                stall += 1
                if stall > 3:
                    break
            continue
        improved = False
        for step in (1.0, 0.5, 0.25):
            try:
                x_new = (best.reshape(-1) + step * v).reshape(n, 3)
                x_new = _feasible_fix(x_new, n)
                pol = _slsqp_polish(x_new, n, maxiter=2500)
                pol = _feasible_fix(pol, n)
                if consider(pol):
                    improved = True
                    break
            except Exception:
                continue
        if not improved:
            stall += 1
            cand = best.copy()
            idx = rng.choice(n, size=rng.integers(1, 4), replace=False)
            cand[idx, 0] += rng.normal(0, 0.015, len(idx))
            cand[idx, 1] += rng.normal(0, 0.015, len(idx))
            cand = _feasible_fix(cand, n)
            newc = make_cand(cand[:, :2])
            pol = _slsqp_polish(newc, n, maxiter=1500)
            pol = _feasible_fix(pol, n)
            if consider(pol):
                stall = 0
            if stall > 5:
                break
        else:
            stall = 0

    if best is None:
        if start is not None:
            return _feasible_fix(start, n)
        p = hex_init(6, 6)
        return make_cand(np.array(p[:n]))

    # Final LP re-solve
    try:
        centers = best[:, :2].copy()
        r = _lp_radii(centers, n)
        if r is not None:
            cand = np.column_stack([centers, r])
            cand = _feasible_fix(cand, n)
            if score(cand) > best_score:
                best = cand
                best_score = score(cand)
    except Exception:
        pass

    best = _feasible_fix(best, n)
    return best

import numpy as np
import time
from scipy.optimize import minimize, linprog


def _feasible_fix(x, n):
