                dy = x[i, 1] - x[j, 1]
                d = np.hypot(dx, dy)
                s = x[i, 2] + x[j, 2]
                if d < s:
                    changed = True
                    excess = s - d + 1e-11
                    x[i, 2] -= excess / 2
                    x[j, 2] -= excess / 2
        x[:, 2] = np.maximum(x[:, 2], 1e-6)
        x[:, 0] = np.clip(x[:, 0], x[:, 2], 1.0 - x[:, 2])
        x[:, 1] = np.clip(x[:, 1], x[:, 2], 1.0 - x[:, 2])
        if not changed:
            break
    x[:, 2] *= (1.0 - 1e-12)
    return x


def _lp_radii(centers, n):
    c = -np.ones(n)
    A_ub = []
    b_ub = []
    for i in range(n):
