                    return dx * dx + dy * dy - (X[i, 2] + X[j, 2]) ** 2
                def jac(v):
                    X = v.reshape(n, 3)
                    dx = X[i, 0] - X[j, 0]
                    dy = X[i, 1] - X[j, 1]
                    s = X[i, 2] + X[j, 2]
                    g = np.zeros(3 * n)
                    g[3 * i] = 2.0 * dx
                    g[3 * i + 1] = 2.0 * dy
                    g[3 * i + 2] = -2.0 * s
                    g[3 * j] = -2.0 * dx
                    g[3 * j + 1] = -2.0 * dy
                    g[3 * j + 2] = -2.0 * s
                    return g
                return f, jac
            f, j = make_pair(i, j)
            cons.append({'type': 'ineq', 'fun': f, 'jac': j})

    v0 = x_init.reshape(-1).copy()
    v0[2::3] = np.clip(v0[2::3], 1e-4, 0.5)
    v0[0::3] = np.clip(v0[0::3], 0.0, 1.0)
    v0[1::3] = np.clip(v0[1::3], 0.0, 1.0)
    try:
        res = minimize(obj, v0, jac=obj_grad, method='SLSQP',
                       bounds=bounds, constraints=cons,
                       options={'maxiter': maxiter, 'ftol': ftol})
        return res.x.reshape(n, 3)
    except Exception:
        return x_init


def _slp_step(x, n, delta=2e-3):
    tol = 1e-6
    A_ub = []
    b_ub = []
    for i in range(n):
        for j in range(i + 1, n):
            dx = x[i, 0] - x[j, 0]
            dy = x[i, 1] - x[j, 1]
            d = np.hypot(dx, dy)
            gap = d - x[i, 2] - x[j, 2]
            if gap < tol:
                if d < 1e-12:
                    continue
                ux = dx / d
                uy = dy / d
                row = np.zeros(3 * n)
                row[3 * i] = -ux
                row[3 * i + 1] = -uy
                row[3 * i + 2] = 1.0
                row[3 * j] = ux
                row[3 * j + 1] = uy
                row[3 * j + 2] = 1.0
                A_ub.append(row)
                b_ub.append(0.0)
    for i in range(n):
        if abs(x[i, 0] - x[i, 2]) < tol:
            row = np.zeros(3 * n)
            row[3 * i] = -1.0
            row[3 * i + 2] = 1.0
            A_ub.append(row); b_ub.append(0.0)
        if abs(1.0 - x[i, 0] - x[i, 2]) < tol:
            row = np.zeros(3 * n)
            row[3 * i] = 1.0
            row[3 * i + 2] = 1.0
            A_ub.append(row); b_ub.append(0.0)
        if abs(x[i, 1] - x[i, 2]) < tol:
            row = np.zeros(3 * n)
            row[3 * i + 1] = -1.0
            row[3 * i + 2] = 1.0
            A_ub.append(row); b_ub.append(0.0)
        if abs(1.0 - x[i, 1] - x[i, 2]) < tol:
            row = np.zeros(3 * n)
            row[3 * i + 1] = 1.0
            row[3 * i + 2] = 1.0
            A_ub.append(row); b_ub.append(0.0)
    if not A_ub:
        return None, 0.0
    c = np.zeros(3 * n)
    c[2::3] = -1.0
    bounds = [(-delta, delta)] * (3 * n)
    try:
        res = linprog(c, A_ub=np.array(A_ub), b_ub=np.array(b_ub),
                      bounds=bounds, method='highs')
        if res.success:
            return res.x, -res.fun
    except Exception:
        pass
    return None, 0.0


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 32
    rng = np.random.default_rng(12345)
    HARD = min(budget_seconds * 0.85, budget_seconds - 1.0)

    def elapsed():
        return time.process_time() - t0

    best = None
    best_score = -1.0

    def score(x):
        return float(np.sum(x[:, 2]))

    if start is not None:
        try:
            s = _feasible_fix(start, n)
            best = s
            best_score = score(s)
        except Exception:
            pass

    def hex_init(rows, cols):
        pts = []
        for j in range(rows):
            y = (j + 0.5) / rows
            off = 0.5 if j % 2 == 0 else 1.0
            cnt = cols if j % 2 == 0 else cols - 1
            for i in range(cnt):
                x = (i + off) / cols
                pts.append((x, y))
        return pts

    def grid_init(g):
        pts = []
        for j in range(g):
            for i in range(g):
                pts.append(((i + 0.5) / g, (j + 0.5) / g))
        return pts

    def make_cand(centers):
        rlp = _lp_radii(centers, n)
        if rlp is None:
            rlp = np.full(n, 0.05)
        c = np.column_stack([centers, rlp])
        return _feasible_fix(c, n)

    # Multi-start
    inits = []
    for rows, cols in [(6, 6), (5, 7), (7, 5), (6, 7), (8, 4), (4, 8), (5, 6), (6, 5)]:
        p = hex_init(rows, cols)
        if len(p) >= n:
            inits.append(np.array(p[:n]))
    for g in (6, 7):
        p = grid_init(g)
        if len(p) >= n:
            inits.append(np.array(p[:n]))

    # Initial lattice multi-starts
    for centers in inits:
        if elapsed() > 0.35 * budget_seconds:
            break
        try:
            cand = make_cand(centers)
            pol = _slsqp_polish(cand, n, 300)
            pol = _feasible_fix(pol, n)
            if score(pol) > best_score:
                best_score = score(pol)
                best = pol
        except Exception:
            pass

    # SLP + SLSQP refinement loop
    while elapsed() < 0.7 * budget_seconds:
        try:
            if best is None:
                break
            cur = best.copy()
            # SLP step
            v, opt = _slp_step(cur, n, delta=1e-3)
            if v is not None and opt > 1e-9:
                vv = v.reshape(n, 3)
                trial = cur + vv
                trial = _feasible_fix(trial, n)
                # re-solve LP radii at new centers
                rlp = _lp_radii(trial[:, :2], n)
                if rlp is not None:
                    trial = np.column_stack([trial[:, :2], rlp])
                pol = _slsqp_polish(trial, n, 200)
                pol = _feasible_fix(pol, n)
                if score(pol) > best_score:
                    best_score = score(pol)
                    best = pol
                    continue
            # random perturbation
            cand = best.copy()
            scale = rng.uniform(0.005, 0.03)
            cand[:, 0] += rng.normal(0, scale, n)
            cand[:, 1] += rng.normal(0, scale, n)
            cand = _feasible_fix(cand, n)
            rlp = _lp_radii(cand[:, :2], n)
            if rlp is not None:
                cand = np.column_stack([cand[:, :2], rlp])
            pol = _slsqp_polish(cand, n, 250)
            pol = _feasible_fix(pol, n)
            if score(pol) > best_score:
                best_score = score(pol)
                best = pol
        except Exception:
            break

    # Final intense polish
    if best is not None:
        while elapsed() < HARD:
            try:
                pol = _slsqp_polish(best, n, 500)
                pol = _feasible_fix(pol, n)
                if score(pol) > best_score:
                    best_score = score(pol)
                    best = pol
                else:
                    cand = best.copy()
                    cand[:, 0] += rng.normal(0, 0.008, n)
                    cand[:, 1] += rng.normal(0, 0.008, n)
                    cand = _feasible_fix(cand, n)
                    pol = _slsqp_polish(cand, n, 300)
                    pol = _feasible_fix(pol, n)
                    if score(pol) > best_score:
                        best_score = score(pol)
                        best = pol
            except Exception:
                break

    if best is None:
        if start is not None:
            return _feasible_fix(start, n)
        centers = np.array(grid_init(6)[:n])
        return _feasible_fix(np.column_stack([centers, np.full(n, 0.07)]), n)

    return _feasible_fix(best, n)

import numpy as np
import time
from scipy.optimize import minimize, linprog


def _feasible_fix(x, n):
    x = np.array(x, dtype=float).reshape(n, 3)
    x[:, 2] = np.maximum(x[:, 2], 1e-6)
    x[:, 0] = np.clip(x[:, 0], x[:, 2], 1.0 - x[:, 2])
    x[:, 1] = np.clip(x[:, 1], x[:, 2], 1.0 - x[:, 2])
    for _ in range(100):
        changed = False
        for i in range(n):
            for j in range(i + 1, n):
                dx = x[i, 0] - x[j, 0]
                dy = x[i, 1] - x[j, 1]
                d = np.hypot(dx, dy)
                s = x[i, 2] + x[j, 2]
                if d < s:
                    changed = True
                    excess = s - d + 1e-11
                    x[i, 2] -= excess / 2
                    x[j, 2] -= excess / 2
        x[:, 2] = np.maximum(x[:, 2], 1e-6)
        x[:, 0] = np.clip(x[:, 0], x[:, 2], 1.0 - x[:, 2])
        x[:, 1] = np.clip(x[:, 1], x[:, 2], 1.0 - x[:, 2])
        if not changed:
            break
    x[:, 2] *= (1.0 - 1e-12)
    return x


def _lp_radii(centers, n):
    c = -np.ones(n)
    A_ub = []
    b_ub = []
    for i in range(n):
        for w in (centers[i, 0], 1.0 - centers[i, 0],
                  centers[i, 1], 1.0 - centers[i, 1]):
            row = np.zeros(n)
            row[i] = 1.0
            A_ub.append(row)
            b_ub.append(max(w, 0.0))
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(centers[i, 0] - centers[j, 0],
                         centers[i, 1] - centers[j, 1])
            row = np.zeros(n)
            row[i] = 1.0
            row[j] = 1.0
            A_ub.append(row)
            b_ub.append(max(d, 0.0))
    bounds = [(1e-6, None)] * n
    try:
        res = linprog(c, A_ub=np.array(A_ub), b_ub=np.array(b_ub),
                      bounds=bounds, method='highs',
                      options={'primal_feasibility_tolerance': 1e-10,
                               'dual_feasibility_tolerance': 1e-10})
        if res.success:
            return np.maximum(res.x, 1e-6)
    except Exception:
        pass
    return None


def _slsqp_polish(x_init, n, maxiter, ftol=1e-14):
    def obj(v):
        return -np.sum(v[2::3])

    def obj_grad(v):
        g = np.zeros_like(v)
        g[2::3] = -1.0
        return g

    bounds = []
    for i in range(n):
        bounds.append((0.0, 1.0))
        bounds.append((0.0, 1.0))
        bounds.append((1e-4, 0.5))

    cons = []
    for i in range(n):
        for kind in range(4):
            def make_wall(i, kind):
                def f(v):
                    X = v.reshape(n, 3)
                    if kind == 0:
                        return X[i, 0] - X[i, 2]
                    elif kind == 1:
                        return 1.0 - X[i, 0] - X[i, 2]
                    elif kind == 2:
                        return X[i, 1] - X[i, 2]
                    else:
                        return 1.0 - X[i, 1] - X[i, 2]
                def jac(v):
                    g = np.zeros(3 * n)
                    if kind == 0:
                        g[3 * i] = 1.0
                    elif kind == 1:
                        g[3 * i] = -1.0
                    elif kind == 2:
                        g[3 * i + 1] = 1.0
                    else:
                        g[3 * i + 1] = -1.0
                    g[3 * i + 2] = -1.0
                    return g
                return f, jac
            f, j = make_wall(i, kind)
            cons.append({'type': 'ineq', 'fun': f, 'jac': j})

    for i in range(n):
        for j in range(i + 1, n):
            def make_pair(i, j):
                def f(v):
                    X = v.reshape(n, 3)
                    dx = X[i, 0] - X[j, 0]
                    dy = X[i, 1] - X[j, 1]
                    return dx * dx + dy * dy - (X[i, 2] + X[j, 2]) ** 2
                def jac(v):
                    X = v.reshape(n, 3)
                    dx = X[i, 0] - X[j, 0]
                    dy = X[i, 1] - X[j, 1]
                    s = X[i, 2] + X[j, 2]
                    g = np.zeros(3 * n)
                    g[3 * i] = 2.0 * dx
                    g[3 * i + 1] = 2.0 * dy
                    g[3 * i + 2] = -2.0 * s
                    g[3 * j] = -2.0 * dx
                    g[3 * j + 1] = -2.0 * dy
                    g[3 * j + 2] = -2.0 * s
                    return g
                return f, jac
            f, j = make_pair(i, j)
            cons.append({'type': 'ineq', 'fun': f, 'jac': j})

    v0 = x_init.reshape(-1).copy()
    v0[2::3] = np.clip(v0[2::3], 1e-4, 0.5)
    v0[0::3] = np.clip(v0[0::3], 0.0, 1.0)
    v0[1::3] = np.clip(v0[1::3], 0.0, 1.0)
    try:
        res = minimize(obj, v0, jac=obj_grad, method='SLSQP',
                       bounds=bounds, constraints=cons,
                       options={'maxiter': maxiter, 'ftol': ftol})
        return res.x.reshape(n, 3)
    except Exception:
        return x_init


def _slp_step(x, n, delta=2e-3):
    tol = 1e-6
    A_ub = []
    b_ub = []
    for i in range(n):
        for j in range(i + 1, n):
            dx = x[i, 0] - x[j, 0]
            dy = x[i, 1] - x[j, 1]
            d = np.hypot(dx, dy)
            gap = d - x[i, 2] - x[j, 2]
            if gap < tol:
                if d < 1e-12:
                    continue
                ux = dx / d
                uy = dy / d
                row = np.zeros(3 * n)
                row[3 * i] = -ux
                row[3 * i + 1] = -uy
                row[3 * i + 2] = 1.0
                row[3 * j] = ux
                row[3 * j + 1] = uy
                row[3 * j + 2] = 1.0
                A_ub.append(row)
                b_ub.append(0.0)
    for i in range(n):
        if abs(x[i, 0] - x[i, 2]) < tol:
            row = np.zeros(3 * n)
            row[3 * i] = -1.0
            row[3 * i + 2] = 1.0
            A_ub.append(row); b_ub.append(0.0)
        if abs(1.0 - x[i, 0] - x[i, 2]) < tol:
            row = np.zeros(3 * n)
            row[3 * i] = 1.0
            row[3 * i + 2] = 1.0
            A_ub.append(row); b_ub.append(0.0)
        if abs(x[i, 1] - x[i, 2]) < tol:
            row = np.zeros(3 * n)
            row[3 * i + 1] = -1.0
            row[3 * i + 2] = 1.0
            A_ub.append(row); b_ub.append(0.0)
        if abs(1.0 - x[i, 1] - x[i, 2]) < tol:
            row = np.zeros(3 * n)
            row[3 * i + 1] = 1.0
            row[3 * i + 2] = 1.0
            A_ub.append(row); b_ub.append(0.0)
    if not A_ub:
        return None, 0.0
    c = np.zeros(3 * n)
    c[2::3] = -1.0
    bounds = [(-delta, delta)] * (3 * n)
    try:
        res = linprog(c, A_ub=np.array(A_ub), b_ub=np.array(b_ub),
                      bounds=bounds, method='highs',
                      options={'primal_feasibility_tolerance': 1e-10,
                               'dual_feasibility_tolerance': 1e-10})
        if res.success:
            return res.x, -res.fun
    except Exception:
        pass
    return None, 0.0


def _active_matrix(x, n, tol=1e-6):
    rows = []
    for i in range(n):
        for j in range(i + 1, n):
            dx = x[i, 0] - x[j, 0]
            dy = x[i, 1] - x[j, 1]
            d = np.hypot(dx, dy)
            gap = d - x[i, 2] - x[j, 2]
            if gap < tol and d > 1e-12:
                ux = dx / d
                uy = dy / d
                row = np.zeros(3 * n)
                row[3 * i] = -ux
                row[3 * i + 1] = -uy
                row[3 * i + 2] = 1.0
                row[3 * j] = ux
                row[3 * j + 1] = uy
                row[3 * j + 2] = 1.0
                rows.append(row)
    for i in range(n):
        if abs(x[i, 0] - x[i, 2]) < tol:
            row = np.zeros(3 * n)
            row[3 * i] = -1.0
            row[3 * i + 2] = 1.0
            rows.append(row)
        if abs(1.0 - x[i, 0] - x[i, 2]) < tol:
            row = np.zeros(3 * n)
            row[3 * i] = 1.0
            row[3 * i + 2] = 1.0
            rows.append(row)
        if abs(x[i, 1] - x[i, 2]) < tol:
            row = np.zeros(3 * n)
            row[3 * i + 1] = -1.0
            row[3 * i + 2] = 1.0
            rows.append(row)
        if abs(1.0 - x[i, 1] - x[i, 2]) < tol:
            row = np.zeros(3 * n)
            row[3 * i + 1] = 1.0
            row[3 * i + 2] = 1.0
            rows.append(row)
    if not rows:
        return None
    return np.array(rows)


def _random_init(rng, n):
    # Poisson-disk-ish random init with variable sizes
    pts = []
    tries = 0
    while len(pts) < n and tries < 20000:
        tries += 1
        p = rng.uniform(0.03, 0.97, 2)
        ok = True
        for q in pts:
            if np.hypot(p[0] - q[0], p[1] - q[1]) < 0.14:
                ok = False
                break
        if ok:
            pts.append(p)
    while len(pts) < n:
        pts.append(rng.uniform(0.1, 0.9, 2))
    return np.array(pts[:n])


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 32
    rng = np.random.default_rng(20240517)
    HARD = min(budget_seconds * 0.80, budget_seconds - 1.0)

    def elapsed():
        return time.process_time() - t0

    def score(x):
        return float(np.sum(x[:, 2]))

    best = None
    best_score = -1.0

    if start is not None:
        try:
            s = _feasible_fix(start, n)
            best = s
            best_score = score(s)
        except Exception:
            pass

    def hex_init(rows, cols):
        pts = []
        for j in range(rows):
            y = (j + 0.5) / rows
            off = 0.5 if j % 2 == 0 else 1.0
            cnt = cols if j % 2 == 0 else cols - 1
            for i in range(cnt):
                x = (i + off) / cols
                pts.append((x, y))
        return pts

    def grid_init(g):
        pts = []
        for j in range(g):
            for i in range(g):
                pts.append(((i + 0.5) / g, (j + 0.5) / g))
        return pts

    def make_cand(centers):
        rlp = _lp_radii(centers, n)
        if rlp is None:
            rlp = np.full(n, 0.05)
        c = np.column_stack([centers, rlp])
        return _feasible_fix(c, n)

    def consider(cand):
        nonlocal best, best_score
        cand = _feasible_fix(cand, n)
        sc = score(cand)
        if sc > best_score:
            best_score = sc
            best = cand

    # Polish the start strongly first (cheap, big potential)
    if best is not None:
        pol = _slsqp_polish(best, n, maxiter=4000, ftol=1e-16)
        pol = _feasible_fix(pol, n)
        if score(pol) > best_score:
            best = pol
            best_score = score(pol)

    # Try a battery of fresh structured inits + random inits
    inits = []
    for rows, cols in [(6, 6), (5, 7), (7, 5), (6, 7), (8, 4), (4, 9), (9, 4)]:
        p = hex_init(rows, cols)
        if len(p) >= n:
            inits.append(np.array(p[:n]))
    for g in (6, 7):
        p = grid_init(g)
        if len(p) >= n:
            inits.append(np.array(p[:n]))
    for _ in range(6):
        inits.append(_random_init(rng, n))

    for k, centers in enumerate(inits):
        if elapsed() > 0.55 * budget_seconds:
            break
        try:
            cand = make_cand(centers)
            pol = _slsqp_polish(cand, n, maxiter=1500)
            pol = _feasible_fix(pol, n)
            consider(pol)
        except Exception:
            pass

    # Null-space random walk with stronger, more diversified steps
    n_attempts = 0
    n_improved = 0
    stall = 0
    while best is not None and elapsed() < HARD:
        n_attempts += 1
        try:
            A = _active_matrix(best, n, tol=1e-6)
            if A is None or A.shape[0] == 0:
                break
            try:
                _, sv, Vt = np.linalg.svd(A, full_matrices=True)
            except Exception:
                break
            k = min(len(sv), Vt.shape[0])
            null_mask = np.ones(Vt.shape[0], dtype=bool)
            null_mask[:k] = sv < 1e-8
            N = Vt[null_mask].T
            if N.shape[1] == 0:
                stall += 1
                if stall > 5:
                    break
                continue
            # occasionally use multiple random directions combined
            if rng.random() < 0.5:
                u = rng.normal(size=N.shape[1])
            else:
                u = np.zeros(N.shape[1])
                for _ in range(3):
                    u += rng.normal(size=N.shape[1])
            nu = np.linalg.norm(u)
            if nu < 1e-12:
                continue
            u /= nu
            s = rng.uniform(0.003, 0.04)
            step = (N @ u) * s
            x_new = best.reshape(-1) + step
            x_new = _feasible_fix(x_new.reshape(n, 3), n)
            pol = _slsqp_polish(x_new, n, maxiter=2500)
            pol = _feasible_fix(pol, n)
            if score(pol) > best_score + 1e-12:
                best = pol
                best_score = score(pol)
                n_improved += 1
                stall = 0
            else:
                stall += 1
                if stall > 30:
                    break
        except Exception:
            break

    # Final LP on centers to squeeze radii
    if best is not None:
        try:
            r = _lp_radii(best[:, :2].copy(), n)
            if r is not None:
                cand = _feasible_fix(np.column_stack([best[:, :2], r]), n)
                if score(cand) > best_score:
                    best = cand
                    best_score = score(cand)
        except Exception:
            pass

    print("attempts:", n_attempts, "improved:", n_improved, "score:", best_score)

    if best is None:
        if start is not None:
            return _feasible_fix(start, n)
        return make_cand(np.array(hex_init(6, 6)[:n]))

    # Final safety shrink
    best = best.copy()
    best[:, 2] *= (1.0 - 1e-9)
