            cand = _feasible_fix(cand, n)
            if score(cand) > best_score:
                best = cand
                best_score = score(cand)
    except Exception:
        pass

    # SLP tangent-space improvement loop
    margin = 1.5
    it = 0
    while best is not None and it < 40 and elapsed() < budget_seconds - margin:
        it += 1
        try:
            v, opt = _slp_step(best, n, delta=2e-3)
        except Exception:
            break
        if v is None or opt < 1e-12:
            break
        try:
            x_new = best.reshape(-1) + 0.5 * v
            x_new = x_new.reshape(n, 3)
            x_new = _feasible_fix(x_new, n)
            pol = _slsqp_polish(x_new, n, maxiter=2000)
            pol = _feasible_fix(pol, n)
            if score(pol) > best_score:
                best = pol
                best_score = score(pol)
            else:
                x_new2 = best.reshape(-1) + 0.25 * v
                x_new2 = _feasible_fix(x_new2.reshape(n, 3), n)
                pol2 = _slsqp_polish(x_new2, n, maxiter=2000)
                pol2 = _feasible_fix(pol2, n)
                if score(pol2) > best_score:
                    best = pol2
                    best_score = score(pol2)
                else:
                    break
        except Exception:
            break

    # ---- Symmetry-reduced search ----
    sym_margin = 0.6
    if elapsed() < budget_seconds - sym_margin:
        try:
            # Build 4-fold fundamental seed: 8 circles in [0,0.5]^2
            # Use a jittered 3x3-ish grid subset
            base_pts = []
            for j in range(3):
                for i in range(3):
                    base_pts.append(((i + 0.5) / 3.0 * 0.5,
                                     (j + 0.5) / 3.0 * 0.5))
            # pick 8 of 9
            base_pts = base_pts[:8]
            fund4 = np.array([(x, y, 0.05) for (x, y) in base_pts])
            fund4[:, 0] += rng.normal(0, 0.01, fund4.shape[0])
            fund4[:, 1] += rng.normal(0, 0.01, fund4.shape[0])
            fund4[:, 0] = np.clip(fund4[:, 0], 0.01, 0.49)
            fund4[:, 1] = np.clip(fund4[:, 1], 0.01, 0.49)
            fund4[:, 2] = 0.04

            for trial in range(3):
                if elapsed() > budget_seconds - sym_margin:
                    break
                if trial > 0:
                    f0 = fund4.copy()
                    f0[:, 0] += rng.normal(0, 0.02, f0.shape[0])
                    f0[:, 1] += rng.normal(0, 0.02, f0.shape[0])
                    f0[:, 0] = np.clip(f0[:, 0], 0.01, 0.49)
                    f0[:, 1] = np.clip(f0[:, 1], 0.01, 0.49)
                else:
                    f0 = fund4
                res4 = _sym_slsqp(f0, '4', maxiter=800)
                full4 = _expand_symmetric(res4, '4')
                full4 = _feasible_fix(full4, n)
                if score(full4) > best_score:
                    pol = _slsqp_polish(full4, n, maxiter=1500)
                    pol = _feasible_fix(pol, n)
                    if score(pol) > best_score:
                        best = pol
                        best_score = score(pol)
                    else:
                        best = full4
                        best_score = score(full4)
        except Exception:
            pass

    if elapsed() < budget_seconds - sym_margin:
        try:
            # 2-fold: 16 circles in [0,0.5]x[0,1]
            pts = []
            for j in range(4):
                for i in range(4):
                    pts.append(((i + 0.5) / 4.0 * 0.5, (j + 0.5) / 4.0))
            fund2 = np.array([(x, y, 0.05) for (x, y) in pts])
            fund2[:, 0] += rng.normal(0, 0.01, fund2.shape[0])
            fund2[:, 1] += rng.normal(0, 0.01, fund2.shape[0])
            fund2[:, 0] = np.clip(fund2[:, 0], 0.01, 0.49)
            fund2[:, 1] = np.clip(fund2[:, 1], 0.01, 0.99)
            fund2[:, 2] = 0.04

            for trial in range(2):
                if elapsed() > budget_seconds - sym_margin:
                    break
                if trial > 0:
                    f0 = fund2.copy()
                    f0[:, 0] += rng.normal(0, 0.02, f0.shape[0])
                    f0[:, 1] += rng.normal(0, 0.02, f0.shape[0])
                    f0[:, 0] = np.clip(f0[:, 0], 0.01, 0.49)
                    f0[:, 1] = np.clip(f0[:, 1], 0.01, 0.99)
                else:
                    f0 = fund2
                res2 = _sym_slsqp(f0, '2', maxiter=800)
                full2 = _expand_symmetric(res2, '2')
                full2 = _feasible_fix(full2, n)
                if score(full2) > best_score:
                    pol = _slsqp_polish(full2, n, maxiter=1500)
                    pol = _feasible_fix(pol, n)
                    if score(pol) > best_score:
                        best = pol
                        best_score = score(pol)
                    else:
                        best = full2
                        best_score = score(full2)
        except Exception:
            pass

    return best

import numpy as np
import time
from scipy.optimize import minimize, linprog


def _feasible_fix(x, n):
    x = np.array(x, dtype=float).reshape(n, 3)
    x[:, 2] = np.maximum(x[:, 2], 1e-6)
    x[:, 0] = np.clip(x[:, 0], x[:, 2], 1.0 - x[:, 2])
    x[:, 1] = np.clip(x[:, 1], x[:, 2], 1.0 - x[:, 2])
    for _ in range(100):
        changed = False
        for i in range(n):
            for j in range(i + 1, n):
                dx = x[i, 0] - x[j, 0]
                dy = x[i, 1] - x[j, 1]
                d = np.hypot(dx, dy)
                s = x[i, 2] + x[j, 2]
                if d < s:
                    changed = True
                    excess = s - d + 1e-11
                    x[i, 2] -= excess / 2
                    x[j, 2] -= excess / 2
        x[:, 2] = np.maximum(x[:, 2], 1e-6)
        x[:, 0] = np.clip(x[:, 0], x[:, 2], 1.0 - x[:, 2])
        x[:, 1] = np.clip(x[:, 1], x[:, 2], 1.0 - x[:, 2])
        if not changed:
            break
    x[:, 2] *= (1.0 - 1e-12)
    return x


def _lp_radii(centers, n):
    c = -np.ones(n)
    A_ub = []
    b_ub = []
    for i in range(n):
        for w in (centers[i, 0], 1.0 - centers[i, 0],
                  centers[i, 1], 1.0 - centers[i, 1]):
            row = np.zeros(n)
            row[i] = 1.0
            A_ub.append(row)
            b_ub.append(max(w, 0.0))
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(centers[i, 0] - centers[j, 0],
                         centers[i, 1] - centers[j, 1])
            row = np.zeros(n)
            row[i] = 1.0
            row[j] = 1.0
            A_ub.append(row)
            b_ub.append(max(d, 0.0))
    bounds = [(1e-6, None)] * n
    try:
        res = linprog(c, A_ub=np.array(A_ub), b_ub=np.array(b_ub),
                      bounds=bounds, method='highs',
                      options={'primal_feasibility_tolerance': 1e-10,
                               'dual_feasibility_tolerance': 1e-10})
        if res.success:
            return np.maximum(res.x, 1e-6)
    except Exception:
        pass
    return None


def _slsqp_polish(x_init, n, maxiter, ftol=1e-14):
    def obj(v):
        return -np.sum(v[2::3])

    def obj_grad(v):
        g = np.zeros_like(v)
        g[2::3] = -1.0
        return g

    bounds = []
    for i in range(n):
        bounds.append((0.0, 1.0))
        bounds.append((0.0, 1.0))
        bounds.append((1e-4, 0.5))

    cons = []
    for i in range(n):
        for kind in range(4):
            def make_wall(i, kind):
                def f(v):
                    X = v.reshape(n, 3)
                    if kind == 0:
                        return X[i, 0] - X[i, 2]
                    elif kind == 1:
                        return 1.0 - X[i, 0] - X[i, 2]
                    elif kind == 2:
                        return X[i, 1] - X[i, 2]
                    else:
                        return 1.0 - X[i, 1] - X[i, 2]
                def jac(v):
                    g = np.zeros(3 * n)
                    if kind == 0:
                        g[3 * i] = 1.0
                    elif kind == 1:
                        g[3 * i] = -1.0
                    elif kind == 2:
                        g[3 * i + 1] = 1.0
                    else:
                        g[3 * i + 1] = -1.0
                    g[3 * i + 2] = -1.0
                    return g
                return f, jac
            f, j = make_wall(i, kind)
            cons.append({'type': 'ineq', 'fun': f, 'jac': j})

    for i in range(n):
        for j in range(i + 1, n):
            def make_pair(i, j):
                def f(v):
                    X = v.reshape(n, 3)
                    dx = X[i, 0] - X[j, 0]
                    dy = X[i, 1] - X[j, 1]
                    return dx * dx + dy * dy - (X[i, 2] + X[j, 2]) ** 2
                def jac(v):
                    X = v.reshape(n, 3)
                    dx = X[i, 0] - X[j, 0]
                    dy = X[i, 1] - X[j, 1]
                    s = X[i, 2] + X[j, 2]
                    g = np.zeros(3 * n)
                    g[3 * i] = 2.0 * dx
                    g[3 * i + 1] = 2.0 * dy
                    g[3 * i + 2] = -2.0 * s
                    g[3 * j] = -2.0 * dx
                    g[3 * j + 1] = -2.0 * dy
                    g[3 * j + 2] = -2.0 * s
                    return g
                return f, jac
            f, j = make_pair(i, j)
            cons.append({'type': 'ineq', 'fun': f, 'jac': j})

    v0 = x_init.reshape(-1).copy()
    v0[2::3] = np.clip(v0[2::3], 1e-4, 0.5)
    v0[0::3] = np.clip(v0[0::3], 0.0, 1.0)
    v0[1::3] = np.clip(v0[1::3], 0.0, 1.0)
    try:
        res = minimize(obj, v0, jac=obj_grad, method='SLSQP',
                       bounds=bounds, constraints=cons,
                       options={'maxiter': maxiter, 'ftol': ftol})
        return res.x.reshape(n, 3)
    except Exception:
        return x_init


def _sub_slsqp(x, n, free_idx, maxiter=500):
    """Optimize x,y,r of free circles only; others fixed as obstacles."""
    m = len(free_idx)
    fset = set(free_idx)
    fixed_idx = [i for i in range(n) if i not in fset]
    fx = x[fixed_idx, 0].copy()
    fy = x[fixed_idx, 1].copy()
    fr = x[fixed_idx, 2].copy()

    def unpack(v):
        X = np.empty((n, 3))
        X[fixed_idx, 0] = fx
        X[fixed_idx, 1] = fy
        X[fixed_idx, 2] = fr
        X[free_idx, 0] = v[0::3]
        X[free_idx, 1] = v[1::3]
        X[free_idx, 2] = v[2::3]
        return X

    def obj(v):
        return -np.sum(v[2::3])

    def obj_grad(v):
        g = np.zeros_like(v)
        g[2::3] = -1.0
        return g

    bounds = []
    for _ in range(m):
        bounds.append((0.0, 1.0))
        bounds.append((0.0, 1.0))
        bounds.append((1e-4, 0.5))

    cons = []
    for a in range(m):
        for kind in range(4):
            def make_wall(a, kind):
                def f(v):
                    if kind == 0:
                        return v[3 * a] - v[3 * a + 2]
                    elif kind == 1:
                        return 1.0 - v[3 * a] - v[3 * a + 2]
                    elif kind == 2:
                        return v[3 * a + 1] - v[3 * a + 2]
                    else:
                        return 1.0 - v[3 * a + 1] - v[3 * a + 2]
                def jac(v):
                    g = np.zeros(3 * m)
                    if kind == 0:
                        g[3 * a] = 1.0
                    elif kind == 1:
                        g[3 * a] = -1.0
                    elif kind == 2:
                        g[3 * a + 1] = 1.0
                    else:
                        g[3 * a + 1] = -1.0
                    g[3 * a + 2] = -1.0
                    return g
                return f, jac
            f, j = make_wall(a, kind)
            cons.append({'type': 'ineq', 'fun': f, 'jac': j})

    for a in range(m):
        for b in range(a + 1, m):
            def make_pair(a, b):
                def f(v):
                    dx = v[3 * a] - v[3 * b]
                    dy = v[3 * a + 1] - v[3 * b + 1]
                    return dx * dx + dy * dy - (v[3 * a + 2] + v[3 * b + 2]) ** 2
                def jac(v):
                    dx = v[3 * a] - v[3 * b]
                    dy = v[3 * a + 1] - v[3 * b + 1]
                    s = v[3 * a + 2] + v[3 * b + 2]
                    g = np.zeros(3 * m)
                    g[3 * a] = 2.0 * dx
                    g[3 * a + 1] = 2.0 * dy
                    g[3 * a + 2] = -2.0 * s
                    g[3 * b] = -2.0 * dx
                    g[3 * b + 1] = -2.0 * dy
                    g[3 * b + 2] = -2.0 * s
                    return g
                return f, jac
            f, j = make_pair(a, b)
            cons.append({'type': 'ineq', 'fun': f, 'jac': j})

    for a in range(m):
        for k in range(len(fixed_idx)):
            def make_fp(a, k):
                def f(v):
                    dx = v[3 * a] - fx[k]
                    dy = v[3 * a + 1] - fy[k]
                    return dx * dx + dy * dy - (v[3 * a + 2] + fr[k]) ** 2
                def jac(v):
                    dx = v[3 * a] - fx[k]
                    dy = v[3 * a + 1] - fy[k]
                    s = v[3 * a + 2] + fr[k]
                    g = np.zeros(3 * m)
                    g[3 * a] = 2.0 * dx
                    g[3 * a + 1] = 2.0 * dy
                    g[3 * a + 2] = -2.0 * s
                    return g
                return f, jac
            f, j = make_fp(a, k)
            cons.append({'type': 'ineq', 'fun': f, 'jac': j})

    v0 = np.empty(3 * m)
    v0[0::3] = np.clip(x[free_idx, 0], 0.0, 1.0)
    v0[1::3] = np.clip(x[free_idx, 1], 0.0, 1.0)
    v0[2::3] = np.clip(x[free_idx, 2], 1e-4, 0.5)
    try:
        res = minimize(obj, v0, jac=obj_grad, method='SLSQP',
                       bounds=bounds, constraints=cons,
                       options={'maxiter': maxiter, 'ftol': 1e-14})
        return unpack(res.x)
    except Exception:
        return x


def _grow_slsqp(x, n, maxiter=400):
    """Directly maximize sum of radii with centers nearly frozen via strong
    radial gradient: SLSQP already does this; this is a warm extra polish."""
    return _slsqp_polish(x, n, maxiter=maxiter, ftol=1e-16)


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 32
    rng = np.random.default_rng(987654321)
    HARD = min(budget_seconds * 0.85, budget_seconds - 1.0)

    def elapsed():
        return time.process_time() - t0

    best = None
    best_score = -1.0

    def score(x):
        return float(np.sum(x[:, 2]))

    def consider(cand):
        nonlocal best, best_score
        cand = _feasible_fix(cand, n)
        s = score(cand)
        if s > best_score:
            best_score = s
            best = cand
            return True
        return False

    if start is not None:
        try:
            consider(np.array(start, dtype=float))
        except Exception:
            pass

    def hex_init(rows, cols):
        pts = []
        for j in range(rows):
            y = (j + 0.5) / rows
            off = 0.5 if j % 2 == 0 else 1.0
            cnt = cols if j % 2 == 0 else cols - 1
            for i in range(cnt):
                x = (i + off) / cols
                pts.append((x, y))
        return pts

    def grid_init(g):
        pts = []
        for j in range(g):
            for i in range(g):
                pts.append(((i + 0.5) / g, (j + 0.5) / g))
        return pts

    inits = []
    for rows, cols in [(6, 6), (5, 7), (7, 5), (6, 7), (8, 4)]:
        p = hex_init(rows, cols)
        if len(p) >= n:
            inits.append(np.array(p[:n]))
    for g in (6, 7):
        p = grid_init(g)
        if len(p) >= n:
            inits.append(np.array(p[:n]))

    def make_cand(centers):
        rlp = _lp_radii(centers, n)
        if rlp is None:
            rlp = np.full(n, 0.05)
        c = np.column_stack([centers, rlp])
        return _feasible_fix(c, n)

    # Initial global SLSQP polish of the start
    if best is not None and elapsed() < HARD:
        pol = _slsqp_polish(best, n, maxiter=4000, ftol=1e-16)
        consider(pol)

    # Explore from scratch only if we still have room and start wasn't great
    if best_score < 2.90:
        for centers in inits:
            if elapsed() > 0.4 * budget_seconds:
                break
            try:
                cand = make_cand(centers)
                pol = _slsqp_polish(cand, n, maxiter=1500)
                consider(pol)
            except Exception:
                pass

    # Main loop: aggressive LNS with sub-SLSQP and full SLSQP polish.
    # Key change: after each accepted LNS, run a full polish to escape plateaus.
    # Also try multi-cluster LNS and larger clusters occasionally.
    lns_iters = 0
    stall = 0
    while best is not None and elapsed() < HARD:
        lns_iters += 1
        try:
            # Occasionally pick a larger cluster to escape deep local opt
            if lns_iters % 5 == 0:
                m = int(rng.integers(9, 14))
            else:
                m = int(rng.integers(5, 9))
            px = rng.uniform(0.0, 1.0)
            py = rng.uniform(0.0, 1.0)
            d2 = (best[:, 0] - px) ** 2 + (best[:, 1] - py) ** 2
            free_idx = list(np.argsort(d2)[:m])

            cand = best.copy()
            # Perturb cluster radii slightly so the subproblem has slack
            cand[free_idx, 2] *= rng.uniform(0.85, 0.97)
            cand = _feasible_fix(cand, n)
            cand = _sub_slsqp(cand, n, free_idx, maxiter=800)
            cand = _feasible_fix(cand, n)

            if score(cand) > best_score + 1e-13:
                # Full polish to squeeze more
                pol = _slsqp_polish(cand, n, maxiter=2000, ftol=1e-16)
                pol = _feasible_fix(pol, n)
                if consider(pol):
                    stall = 0
                else:
                    consider(cand)
                    stall += 1
            else:
                stall += 1

            # If stalled, do a full global polish from best
            if stall >= 6 and elapsed() < HARD - 0.5:
                pol = _slsqp_polish(best, n, maxiter=3000, ftol=1e-16)
                consider(pol)
                stall = 0
        except Exception:
            break

    if best is None:
        if start is not None:
            return _feasible_fix(start, n)
        p = hex_init(6, 6)
        return make_cand(np.array(p[:n]))

    # Final LP re-fit of radii at fixed centers, then a final polish
    try:
        centers = best[:, :2].copy()
        r = _lp_radii(centers, n)
        if r is not None:
            cand = _feasible_fix(np.column_stack([centers, r]), n)
            if score(cand) > best_score:
                best = cand
                best_score = score(cand)
    except Exception:
        pass

    if elapsed() < budget_seconds - 0.5:
        pol = _slsqp_polish(best, n, maxiter=4000, ftol=1e-16)
        consider(pol)

    # Safety: shrink slightly to guarantee zero-tolerance feasibility
    best = _feasible_fix(best, n)
    best[:, 2] *= (1.0 - 1e-9)

    print("LNS iterations:", lns_iters, "score:", best_score)
    return best

