                        return X[i, 1] - X[i, 2]
                    else:
                        return 1.0 - X[i, 1] - X[i, 2]
                def jac(v):
                    g = np.zeros(3 * n)
                    if kind == 0:
                        g[3 * i] = 1.0
                    elif kind == 1:
                        g[3 * i] = -1.0
                    elif kind == 2:
                        g[3 * i + 1] = 1.0
                    else:
                        g[3 * i + 1] = -1.0
                    g[3 * i + 2] = -1.0
                    return g
                return f, jac
            f, j = make_wall(i, kind)
            cons.append({'type': 'ineq', 'fun': f, 'jac': j})

    for i in range(n):
        for j in range(i + 1, n):
            def make_pair(i, j):
                def f(v):
                    X = v.reshape(n, 3)
                    dx = X[i, 0] - X[j, 0]
                    dy = X[i, 1] - X[j, 1]
                    return dx * dx + dy * dy - (X[i, 2] + X[j, 2]) ** 2
                def jac(v):
                    X = v.reshape(n, 3)
                    dx = X[i, 0] - X[j, 0]
                    dy = X[i, 1] - X[j, 1]
                    s = X[i, 2] + X[j, 2]
                    g = np.zeros(3 * n)
                    g[3 * i] = 2.0 * dx
                    g[3 * i + 1] = 2.0 * dy
                    g[3 * i + 2] = -2.0 * s
                    g[3 * j] = -2.0 * dx
                    g[3 * j + 1] = -2.0 * dy
                    g[3 * j + 2] = -2.0 * s
                    return g
                return f, jac
            f, j = make_pair(i, j)
            cons.append({'type': 'ineq', 'fun': f, 'jac': j})

    v0 = x_init.reshape(-1).copy()
    v0[2::3] = np.clip(v0[2::3], 1e-4, 0.5)
    v0[0::3] = np.clip(v0[0::3], 0.0, 1.0)
    v0[1::3] = np.clip(v0[1::3], 0.0, 1.0)
    try:
        res = minimize(obj, v0, jac=obj_grad, method='SLSQP',
                       bounds=bounds, constraints=cons,
                       options={'maxiter': maxiter, 'ftol': ftol})
        return res.x.reshape(n, 3)
    except Exception:
        return x_init


def _slp_step(x, n, delta=2e-3):
    tol = 1e-6
    A_ub = []
    b_ub = []
    for i in range(n):
        for j in range(i + 1, n):
            dx = x[i, 0] - x[j, 0]
            dy = x[i, 1] - x[j, 1]
            d = np.hypot(dx, dy)
            gap = d - x[i, 2] - x[j, 2]
            if gap < tol:
                if d < 1e-12:
                    continue
                ux = dx / d
                uy = dy / d
                row = np.zeros(3 * n)
                row[3 * i] = -ux
                row[3 * i + 1] = -uy
                row[3 * i + 2] = 1.0
                row[3 * j] = ux
                row[3 * j + 1] = uy
                row[3 * j + 2] = 1.0
                A_ub.append(row)
                b_ub.append(0.0)
    for i in range(n):
        if abs(x[i, 0] - x[i, 2]) < tol:
            row = np.zeros(3 * n)
            row[3 * i] = -1.0
            row[3 * i + 2] = 1.0
            A_ub.append(row); b_ub.append(0.0)
        if abs(1.0 - x[i, 0] - x[i, 2]) < tol:
            row = np.zeros(3 * n)
            row[3 * i] = 1.0
            row[3 * i + 2] = 1.0
            A_ub.append(row); b_ub.append(0.0)
        if abs(x[i, 1] - x[i, 2]) < tol:
            row = np.zeros(3 * n)
            row[3 * i + 1] = -1.0
            row[3 * i + 2] = 1.0
            A_ub.append(row); b_ub.append(0.0)
        if abs(1.0 - x[i, 1] - x[i, 2]) < tol:
            row = np.zeros(3 * n)
            row[3 * i + 1] = 1.0
            row[3 * i + 2] = 1.0
            A_ub.append(row); b_ub.append(0.0)
    if not A_ub:
        return None, 0.0
    c = np.zeros(3 * n)
    c[2::3] = -1.0
    bounds = [(-delta, delta)] * (3 * n)
    try:
        res = linprog(c, A_ub=np.array(A_ub), b_ub=np.array(b_ub),
                      bounds=bounds, method='highs',
                      options={'primal_feasibility_tolerance': 1e-10,
                               'dual_feasibility_tolerance': 1e-10})
        if res.success:
            return res.x, -res.fun
    except Exception:
        pass
    return None, 0.0


def _drop_reinsert(x, n, rng):
    """Drop smallest circle, reopt 31, grid-search best spot for 32nd, reopt all 32."""
    idx = int(np.argmin(x[:, 2]))
    keep = np.delete(x, idx, axis=0)  # (n-1, 3)
    m = n - 1
    # LP radii for 31
    r = _lp_radii(keep[:, :2], m)
    if r is not None:
        keep = np.column_stack([keep[:, :2], r])
    keep = _feasible_fix(keep, m)
    pol = _slsqp_polish(keep, m, maxiter=1500)
    pol = _feasible_fix(pol, m)
    if np.sum(pol[:, 2]) > np.sum(keep[:, 2]):
        keep = pol
    # grid search for best insertion point
    G = 40
    gx = (np.arange(G) + 0.5) / G
    best_val = -1.0
    best_pt = (0.5, 0.5)
    cx = keep[:, 0]; cy = keep[:, 1]; cr = keep[:, 2]
    for xi in gx:
        for yi in gx:
            wall = min(xi, 1.0 - xi, yi, 1.0 - yi)
            d = np.hypot(cx - xi, cy - yi) - cr
            val = min(wall, float(np.min(d)))
            if val > best_val:
                best_val = val
                best_pt = (xi, yi)
    newc = np.vstack([keep, [best_pt[0], best_pt[1], max(best_val * 0.99, 1e-3)]])
    newc = _feasible_fix(newc, n)
    # LP radii for all 32
    r = _lp_radii(newc[:, :2], n)
    if r is not None:
        newc = np.column_stack([newc[:, :2], r])
    newc = _feasible_fix(newc, n)
    pol = _slsqp_polish(newc, n, maxiter=2000)
    pol = _feasible_fix(pol, n)
    if np.sum(pol[:, 2]) > np.sum(newc[:, 2]):
        newc = pol
    return newc


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 32
    rng = np.random.default_rng(12345)
    HARD = min(budget_seconds * 0.82, budget_seconds - 1.2)

    def elapsed():
        return time.process_time() - t0

    best = None
    best_score = -1.0

    def score(x):
        return float(np.sum(x[:, 2]))

    if start is not None:
        try:
            s = _feasible_fix(start, n)
            best = s
            best_score = score(s)
        except Exception:
            pass

    def hex_init(rows, cols):
        pts = []
        for j in range(rows):
            y = (j + 0.5) / rows
            off = 0.5 if j % 2 == 0 else 1.0
            cnt = cols if j % 2 == 0 else cols - 1
            for i in range(cnt):
                x = (i + off) / cols
                pts.append((x, y))
        return pts

    def grid_init(g):
        pts = []
        for j in range(g):
            for i in range(g):
                pts.append(((i + 0.5) / g, (j + 0.5) / g))
        return pts

    inits = []
    for rows, cols in [(6, 6), (5, 7), (7, 5), (6, 7), (8, 4)]:
        p = hex_init(rows, cols)
        if len(p) >= n:
            inits.append(np.array(p[:n]))
    for g in (6, 7):
        p = grid_init(g)
        if len(p) >= n:
            inits.append(np.array(p[:n]))

    def make_cand(centers):
        rlp = _lp_radii(centers, n)
        if rlp is None:
            rlp = np.full(n, 0.05)
        c = np.column_stack([centers, rlp])
        return _feasible_fix(c, n)

    def consider(cand):
        nonlocal best, best_score
        cand = _feasible_fix(cand, n)
        if score(cand) > best_score:
            best_score = score(cand)
            best = cand

    # Polish the start first
    if best is not None and elapsed() < HARD:
        pol = _slsqp_polish(best, n, maxiter=3000, ftol=1e-16)
        pol = _feasible_fix(pol, n)
        if score(pol) > best_score:
            best_score = score(pol)
            best = pol

    for centers in inits:
        if elapsed() > 0.5 * budget_seconds:
            break
        try:
            cand = make_cand(centers)
            consider(cand)
            if elapsed() < 0.5 * budget_seconds:
                pol = _slsqp_polish(cand, n, maxiter=1200)
                pol = _feasible_fix(pol, n)
                if score(pol) > best_score:
                    best_score = score(pol)
                    best = pol
        except Exception:
            pass

    # Random restarts / perturbations around best
    while best is not None and elapsed() < HARD:
        try:
            cand = best.copy()
            scale = rng.uniform(0.01, 0.05)
            cand[:, 0] += rng.normal(0, scale, n)
            cand[:, 1] += rng.normal(0, scale, n)
            cand = _feasible_fix(cand, n)
            newc = make_cand(cand[:, :2])
            pol = _slsqp_polish(newc, n, maxiter=1200)
            pol = _feasible_fix(pol, n)
            if score(pol) > best_score:
                best_score = score(pol)
                best = pol
        except Exception:
            break

    if best is None:
        if start is not None:
            return _feasible_fix(start, n)
        p = hex_init(6, 6)
        return make_cand(np.array(p[:n]))

    # Final LP re-solve at final centers with tight tolerances
    try:
        centers = best[:, :2].copy()
        r = _lp_radii(centers, n)
        if r is not None:
            cand = np.column_stack([centers, r])
            cand = _feasible_fix(cand, n)
            if score(cand) > best_score:
                best = cand
                best_score = score(cand)
    except Exception:
        pass

    # SLP tangent-space improvement loop
    margin = 1.5
    it = 0
    while best is not None and it < 40 and elapsed() < budget_seconds - margin:
        it += 1
        try:
            v, opt = _slp_step(best, n, delta=2e-3)
        except Exception:
            break
        if v is None or opt < 1e-12:
            break
        try:
            x_new = best.reshape(-1) + 0.5 * v
            x_new = x_new.reshape(n, 3)
            x_new = _feasible_fix(x_new, n)
            pol = _slsqp_polish(x_new, n, maxiter=2000)
            pol = _feasible_fix(pol, n)
            if score(pol) > best_score:
                best = pol
                best_score = score(pol)
            else:
                x_new2 = best.reshape(-1) + 0.25 * v
                x_new2 = _feasible_fix(x_new2.reshape(n, 3), n)
                pol2 = _slsqp_polish(x_new2, n, maxiter=2000)
                pol2 = _feasible_fix(pol2, n)
                if score(pol2) > best_score:
                    best = pol2
                    best_score = score(pol2)
                else:
                    break
        except Exception:
            break

    # Drop-smallest / reinsert experiment
    rounds = 0
    while best is not None and rounds < 4 and elapsed() < budget_seconds - margin:
        rounds += 1
        try:
            cand = _drop_reinsert(best, n, rng)
            cand = _feasible_fix(cand, n)
            if score(cand) > best_score + 1e-12:
                best = cand
                best_score = score(cand)
        except Exception:
            break

    return best

import numpy as np
import time
from scipy.optimize import minimize, linprog


def _feasible_fix(x, n):
    x = np.array(x, dtype=float).reshape(n, 3)
    x[:, 2] = np.maximum(x[:, 2], 1e-6)
    x[:, 0] = np.clip(x[:, 0], x[:, 2], 1.0 - x[:, 2])
    x[:, 1] = np.clip(x[:, 1], x[:, 2], 1.0 - x[:, 2])
    for _ in range(100):
        changed = False
        for i in range(n):
            for j in range(i + 1, n):
                dx = x[i, 0] - x[j, 0]
                dy = x[i, 1] - x[j, 1]
                d = np.hypot(dx, dy)
                s = x[i, 2] + x[j, 2]
                if d < s:
                    changed = True
                    excess = s - d + 1e-11
                    x[i, 2] -= excess / 2
                    x[j, 2] -= excess / 2
        x[:, 2] = np.maximum(x[:, 2], 1e-6)
        x[:, 0] = np.clip(x[:, 0], x[:, 2], 1.0 - x[:, 2])
        x[:, 1] = np.clip(x[:, 1], x[:, 2], 1.0 - x[:, 2])
        if not changed:
            break
    x[:, 2] *= (1.0 - 1e-12)
    return x


def _lp_radii(centers, n):
    c = -np.ones(n)
    A_ub = []
    b_ub = []
    for i in range(n):
        for w in (centers[i, 0], 1.0 - centers[i, 0],
                  centers[i, 1], 1.0 - centers[i, 1]):
            row = np.zeros(n)
            row[i] = 1.0
            A_ub.append(row)
            b_ub.append(max(w, 0.0))
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(centers[i, 0] - centers[j, 0],
                         centers[i, 1] - centers[j, 1])
            row = np.zeros(n)
            row[i] = 1.0
            row[j] = 1.0
            A_ub.append(row)
            b_ub.append(max(d, 0.0))
    bounds = [(1e-6, None)] * n
    try:
        res = linprog(c, A_ub=np.array(A_ub), b_ub=np.array(b_ub),
                      bounds=bounds, method='highs',
                      options={'primal_feasibility_tolerance': 1e-10,
                               'dual_feasibility_tolerance': 1e-10})
        if res.success:
            return np.maximum(res.x, 1e-6)
    except Exception:
        pass
    return None


def _slsqp_polish(x_init, n, maxiter, ftol=1e-14):
    def obj(v):
        return -np.sum(v[2::3])

    def obj_grad(v):
        g = np.zeros_like(v)
        g[2::3] = -1.0
        return g

    bounds = []
    for i in range(n):
        bounds.append((0.0, 1.0))
        bounds.append((0.0, 1.0))
        bounds.append((1e-4, 0.5))

    cons = []
    for i in range(n):
        for kind in range(4):
            def make_wall(i, kind):
                def f(v):
                    X = v.reshape(n, 3)
                    if kind == 0:
                        return X[i, 0] - X[i, 2]
                    elif kind == 1:
                        return 1.0 - X[i, 0] - X[i, 2]
                    elif kind == 2:
                        return X[i, 1] - X[i, 2]
                    else:
                        return 1.0 - X[i, 1] - X[i, 2]
                def jac(v):
                    g = np.zeros(3 * n)
                    if kind == 0:
                        g[3 * i] = 1.0
                    elif kind == 1:
                        g[3 * i] = -1.0
                    elif kind == 2:
                        g[3 * i + 1] = 1.0
                    else:
                        g[3 * i + 1] = -1.0
                    g[3 * i + 2] = -1.0
                    return g
                return f, jac
            f, j = make_wall(i, kind)
            cons.append({'type': 'ineq', 'fun': f, 'jac': j})

    for i in range(n):
        for j in range(i + 1, n):
            def make_pair(i, j):
                def f(v):
                    X = v.reshape(n, 3)
                    dx = X[i, 0] - X[j, 0]
                    dy = X[i, 1] - X[j, 1]
                    return dx * dx + dy * dy - (X[i, 2] + X[j, 2]) ** 2
                def jac(v):
                    X = v.reshape(n, 3)
                    dx = X[i, 0] - X[j, 0]
                    dy = X[i, 1] - X[j, 1]
                    s = X[i, 2] + X[j, 2]
                    g = np.zeros(3 * n)
                    g[3 * i] = 2.0 * dx
                    g[3 * i + 1] = 2.0 * dy
                    g[3 * i + 2] = -2.0 * s
                    g[3 * j] = -2.0 * dx
                    g[3 * j + 1] = -2.0 * dy
                    g[3 * j + 2] = -2.0 * s
                    return g
                return f, jac
            f, j = make_pair(i, j)
            cons.append({'type': 'ineq', 'fun': f, 'jac': j})

    v0 = x_init.reshape(-1).copy()
    v0[2::3] = np.clip(v0[2::3], 1e-4, 0.5)
    v0[0::3] = np.clip(v0[0::3], 0.0, 1.0)
    v0[1::3] = np.clip(v0[1::3], 0.0, 1.0)
    try:
        res = minimize(obj, v0, jac=obj_grad, method='SLSQP',
                       bounds=bounds, constraints=cons,
                       options={'maxiter': maxiter, 'ftol': ftol})
        return res.x.reshape(n, 3)
    except Exception:
        return x_init


def _slp_step(x, n, delta=2e-3):
    tol = 1e-6
    A_ub = []
    b_ub = []
    for i in range(n):
        for j in range(i + 1, n):
            dx = x[i, 0] - x[j, 0]
            dy = x[i, 1] - x[j, 1]
            d = np.hypot(dx, dy)
            gap = d - x[i, 2] - x[j, 2]
            if gap < tol:
                if d < 1e-12:
                    continue
                ux = dx / d
                uy = dy / d
                row = np.zeros(3 * n)
                row[3 * i] = -ux
                row[3 * i + 1] = -uy
                row[3 * i + 2] = 1.0
                row[3 * j] = ux
                row[3 * j + 1] = uy
                row[3 * j + 2] = 1.0
                A_ub.append(row)
                b_ub.append(0.0)
    for i in range(n):
        if abs(x[i, 0] - x[i, 2]) < tol:
            row = np.zeros(3 * n)
            row[3 * i] = -1.0
            row[3 * i + 2] = 1.0
            A_ub.append(row); b_ub.append(0.0)
        if abs(1.0 - x[i, 0] - x[i, 2]) < tol:
            row = np.zeros(3 * n)
            row[3 * i] = 1.0
            row[3 * i + 2] = 1.0
            A_ub.append(row); b_ub.append(0.0)
        if abs(x[i, 1] - x[i, 2]) < tol:
            row = np.zeros(3 * n)
            row[3 * i + 1] = -1.0
            row[3 * i + 2] = 1.0
            A_ub.append(row); b_ub.append(0.0)
        if abs(1.0 - x[i, 1] - x[i, 2]) < tol:
            row = np.zeros(3 * n)
            row[3 * i + 1] = 1.0
            row[3 * i + 2] = 1.0
            A_ub.append(row); b_ub.append(0.0)
    if not A_ub:
        return None, 0.0
    c = np.zeros(3 * n)
    c[2::3] = -1.0
    bounds = [(-delta, delta)] * (3 * n)
    try:
        res = linprog(c, A_ub=np.array(A_ub), b_ub=np.array(b_ub),
                      bounds=bounds, method='highs',
                      options={'primal_feasibility_tolerance': 1e-10,
                               'dual_feasibility_tolerance': 1e-10})
        if res.success:
            return res.x, -res.fun
    except Exception:
        pass
    return None, 0.0


def _perturb_centers(centers, rng, n, scale):
    c = centers.copy()
    k = rng.integers(1, max(2, n // 2))
    idx = rng.choice(n, size=k, replace=False)
    c[idx, 0] += rng.normal(0, scale, k)
    c[idx, 1] += rng.normal(0, scale, k)
    return c


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 32
    rng = np.random.default_rng(12345)
    HARD = min(budget_seconds * 0.85, budget_seconds - 1.0)

    def elapsed():
        return time.process_time() - t0

    best = None
    best_score = -1.0

    def score(x):
        return float(np.sum(x[:, 2]))

    if start is not None:
        try:
            s = _feasible_fix(start, n)
            best = s
            best_score = score(s)
        except Exception:
            pass

    def hex_init(rows, cols):
        pts = []
        for j in range(rows):
            y = (j + 0.5) / rows
            off = 0.5 if j % 2 == 0 else 1.0
            cnt = cols if j % 2 == 0 else cols - 1
            for i in range(cnt):
                x = (i + off) / cols
                pts.append((x, y))
        return pts

    def grid_init(g):
        pts = []
        for j in range(g):
            for i in range(g):
                pts.append(((i + 0.5) / g, (j + 0.5) / g))
        return pts

    def make_cand(centers):
        rlp = _lp_radii(centers, n)
        if rlp is None:
            rlp = np.full(n, 0.05)
        c = np.column_stack([centers, rlp])
        return _feasible_fix(c, n)

    # Polish start first
    if best is not None and elapsed() < HARD:
        pol = _slsqp_polish(best, n, maxiter=4000, ftol=1e-16)
        pol = _feasible_fix(pol, n)
        if score(pol) > best_score:
            best_score = score(pol)
            best = pol

    # SLP tangent-space improvement loop
    it = 0
    while best is not None and it < 80 and elapsed() < HARD - 1.0:
        it += 1
        try:
            v, opt = _slp_step(best, n, delta=2e-3)
        except Exception:
            break
        if v is None or opt < 1e-12:
            break
        improved = False
        for frac in (0.7, 0.4, 0.2, 0.1):
            try:
                x_new = (best.reshape(-1) + frac * v).reshape(n, 3)
                x_new = _feasible_fix(x_new, n)
                pol = _slsqp_polish(x_new, n, maxiter=2500)
                pol = _feasible_fix(pol, n)
                if score(pol) > best_score + 1e-12:
                    best = pol
                    best_score = score(pol)
                    improved = True
                    break
            except Exception:
                continue
        if not improved:
            break

    # Try inits if there's room
    inits = []
    for rows, cols in [(6, 6), (5, 7), (7, 5), (6, 7), (8, 4)]:
        p = hex_init(rows, cols)
        if len(p) >= n:
            inits.append(np.array(p[:n]))
    for g in (6, 7):
        p = grid_init(g)
        if len(p) >= n:
            inits.append(np.array(p[:n]))

    for centers in inits:
        if elapsed() > HARD - 1.0:
            break
        try:
            cand = make_cand(centers)
            if score(cand) > best_score:
                pol = _slsqp_polish(cand, n, maxiter=1500)
                pol = _feasible_fix(pol, n)
                if score(pol) > best_score:
                    best_score = score(pol)
                    best = pol
        except Exception:
            pass

    # Perturbation loop
    while best is not None and elapsed() < HARD:
        try:
            scale = rng.uniform(0.005, 0.04)
            newc = _perturb_centers(best[:, :2], rng, n, scale)
            cand = make_cand(newc)
            pol = _slsqp_polish(cand, n, maxiter=1500)
            pol = _feasible_fix(pol, n)
            if score(pol) > best_score:
                best_score = score(pol)
                best = pol
        except Exception:
            break

    if best is None:
        if start is not None:
            return _feasible_fix(start, n)
        p = hex_init(6, 6)
        return make_cand(np.array(p[:n]))

    # Final LP re-solve at final centers
    try:
        centers = best[:, :2].copy()
        r = _lp_radii(centers, n)
        if r is not None:
            cand = np.column_stack([centers, r])
            cand = _feasible_fix(cand, n)
            if score(cand) > best_score:
                best = cand
                best_score = score(cand)
    except Exception:
        pass

    return best

import numpy as np
import time
from scipy.optimize import minimize, linprog


def _feasible_fix(x, n):
    x = np.array(x, dtype=float).reshape(n, 3)
    x[:, 2] = np.maximum(x[:, 2], 1e-6)
    x[:, 0] = np.clip(x[:, 0], x[:, 2], 1.0 - x[:, 2])
    x[:, 1] = np.clip(x[:, 1], x[:, 2], 1.0 - x[:, 2])
    for _ in range(100):
        changed = False
        for i in range(n):
            for j in range(i + 1, n):
                dx = x[i, 0] - x[j, 0]
                dy = x[i, 1] - x[j, 1]
                d = np.hypot(dx, dy)
                s = x[i, 2] + x[j, 2]
                if d < s:
                    changed = True
                    excess = s - d + 1e-11
                    x[i, 2] -= excess / 2
                    x[j, 2] -= excess / 2
        x[:, 2] = np.maximum(x[:, 2], 1e-6)
        x[:, 0] = np.clip(x[:, 0], x[:, 2], 1.0 - x[:, 2])
        x[:, 1] = np.clip(x[:, 1], x[:, 2], 1.0 - x[:, 2])
        if not changed:
            break
    x[:, 2] *= (1.0 - 1e-12)
    return x


def _lp_radii(centers, n):
    c = -np.ones(n)
    A_ub = []
    b_ub = []
    for i in range(n):
        for w in (centers[i, 0], 1.0 - centers[i, 0],
                  centers[i, 1], 1.0 - centers[i, 1]):
            row = np.zeros(n)
            row[i] = 1.0
            A_ub.append(row)
            b_ub.append(max(w, 0.0))
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(centers[i, 0] - centers[j, 0],
                         centers[i, 1] - centers[j, 1])
            row = np.zeros(n)
            row[i] = 1.0
            row[j] = 1.0
            A_ub.append(row)
            b_ub.append(max(d, 0.0))
    bounds = [(1e-6, None)] * n
    try:
        res = linprog(c, A_ub=np.array(A_ub), b_ub=np.array(b_ub),
                      bounds=bounds, method='highs',
                      options={'primal_feasibility_tolerance': 1e-10,
                               'dual_feasibility_tolerance': 1e-10})
        if res.success:
            return np.maximum(res.x, 1e-6)
    except Exception:
        pass
    return None


def _slsqp_polish(x_init, n, maxiter, ftol=1e-14):
    def obj(v):
        return -np.sum(v[2::3])

    def obj_grad(v):
        g = np.zeros_like(v)
        g[2::3] = -1.0
        return g

    bounds = []
    for i in range(n):
        bounds.append((0.0, 1.0))
        bounds.append((0.0, 1.0))
        bounds.append((1e-4, 0.5))

    cons = []
    for i in range(n):
        for kind in range(4):
            def make_wall(i, kind):
                def f(v):
                    X = v.reshape(n, 3)
                    if kind == 0:
                        return X[i, 0] - X[i, 2]
                    elif kind == 1:
                        return 1.0 - X[i, 0] - X[i, 2]
                    elif kind == 2:
                        return X[i, 1] - X[i, 2]
                    else:
                        return 1.0 - X[i, 1] - X[i, 2]
                def jac(v):
                    g = np.zeros(3 * n)
                    if kind == 0:
                        g[3 * i] = 1.0
                    elif kind == 1:
                        g[3 * i] = -1.0
                    elif kind == 2:
                        g[3 * i + 1] = 1.0
                    else:
                        g[3 * i + 1] = -1.0
                    g[3 * i + 2] = -1.0
                    return g
                return f, jac
            f, j = make_wall(i, kind)
            cons.append({'type': 'ineq', 'fun': f, 'jac': j})

    for i in range(n):
        for j in range(i + 1, n):
            def make_pair(i, j):
                def f(v):
                    X = v.reshape(n, 3)
                    dx = X[i, 0] - X[j, 0]
                    dy = X[i, 1] - X[j, 1]
                    return dx * dx + dy * dy - (X[i, 2] + X[j, 2]) ** 2
                def jac(v):
                    X = v.reshape(n, 3)
                    dx = X[i, 0] - X[j, 0]
                    dy = X[i, 1] - X[j, 1]
                    s = X[i, 2] + X[j, 2]
                    g = np.zeros(3 * n)
                    g[3 * i] = 2.0 * dx
                    g[3 * i + 1] = 2.0 * dy
                    g[3 * i + 2] = -2.0 * s
                    g[3 * j] = -2.0 * dx
                    g[3 * j + 1] = -2.0 * dy
                    g[3 * j + 2] = -2.0 * s
                    return g
                return f, jac
            f, j = make_pair(i, j)
            cons.append({'type': 'ineq', 'fun': f, 'jac': j})

    v0 = x_init.reshape(-1).copy()
    v0[2::3] = np.clip(v0[2::3], 1e-4, 0.5)
    v0[0::3] = np.clip(v0[0::3], 0.0, 1.0)
    v0[1::3] = np.clip(v0[1::3], 0.0, 1.0)
    try:
        res = minimize(obj, v0, jac=obj_grad, method='SLSQP',
                       bounds=bounds, constraints=cons,
                       options={'maxiter': maxiter, 'ftol': ftol})
        return res.x.reshape(n, 3)
    except Exception:
        return x_init


def _slp_step(x, n, delta=2e-3):
    tol = 1e-6
    A_ub = []
    b_ub = []
    for i in range(n):
        for j in range(i + 1, n):
            dx = x[i, 0] - x[j, 0]
            dy = x[i, 1] - x[j, 1]
            d = np.hypot(dx, dy)
            gap = d - x[i, 2] - x[j, 2]
            if gap < tol:
                if d < 1e-12:
                    continue
                ux = dx / d
                uy = dy / d
                row = np.zeros(3 * n)
                row[3 * i] = -ux
                row[3 * i + 1] = -uy
                row[3 * i + 2] = 1.0
                row[3 * j] = ux
                row[3 * j + 1] = uy
                row[3 * j + 2] = 1.0
                A_ub.append(row)
                b_ub.append(0.0)
    for i in range(n):
        if abs(x[i, 0] - x[i, 2]) < tol:
            row = np.zeros(3 * n)
            row[3 * i] = -1.0
            row[3 * i + 2] = 1.0
            A_ub.append(row); b_ub.append(0.0)
        if abs(1.0 - x[i, 0] - x[i, 2]) < tol:
            row = np.zeros(3 * n)
            row[3 * i] = 1.0
            row[3 * i + 2] = 1.0
            A_ub.append(row); b_ub.append(0.0)
        if abs(x[i, 1] - x[i, 2]) < tol:
            row = np.zeros(3 * n)
            row[3 * i + 1] = -1.0
            row[3 * i + 2] = 1.0
            A_ub.append(row); b_ub.append(0.0)
        if abs(1.0 - x[i, 1] - x[i, 2]) < tol:
            row = np.zeros(3 * n)
            row[3 * i + 1] = 1.0
            row[3 * i + 2] = 1.0
            A_ub.append(row); b_ub.append(0.0)
    if not A_ub:
        return None, 0.0
    c = np.zeros(3 * n)
    c[2::3] = -1.0
    bounds = [(-delta, delta)] * (3 * n)
    try:
        res = linprog(c, A_ub=np.array(A_ub), b_ub=np.array(b_ub),
                      bounds=bounds, method='highs',
                      options={'primal_feasibility_tolerance': 1e-10,
                               'dual_feasibility_tolerance': 1e-10})
        if res.success:
            return res.x, -res.fun
    except Exception:
        pass
    return None, 0.0


def _kkt_newton(x, n, max_iter=30, tol=1e-14):
    """Solve exact KKT system for active set with Newton in longdouble.
    Returns improved x (or original if no improvement / failure)."""
    x = np.array(x, dtype=float)
    x_best = x.copy()
    best_score = float(np.sum(x[:, 2]))
    try:
        X = x.astype(np.longdouble)
        # Identify active set
        tol_act = 1e-6
        pairs = []
        for i in range(n):
            for j in range(i + 1, n):
                dx = X[i, 0] - X[j, 0]
                dy = X[i, 1] - X[j, 1]
                d = np.sqrt(dx * dx + dy * dy)
                gap = d - X[i, 2] - X[j, 2]
                if gap < tol_act:
                    pairs.append((i, j))
        walls = []  # (i, kind): 0 left, 1 right, 2 bottom, 3 top
        for i in range(n):
            if abs(X[i, 0] - X[i, 2]) < tol_act:
                walls.append((i, 0))
            if abs(1.0 - X[i, 0] - X[i, 2]) < tol_act:
                walls.append((i, 1))
            if abs(X[i, 1] - X[i, 2]) < tol_act:
                walls.append((i, 2))
            if abs(1.0 - X[i, 1] - X[i, 2]) < tol_act:
                walls.append((i, 3))
        m = len(pairs) + len(walls)
        if m == 0:
            return x_best
        # Variables: z = [X (3n), lambdas (m)]
        nv = 3 * n + m

        def g_val(X, k):
            # returns constraint value g_k(X) (>=0 feasible)
            if k < len(pairs):
                i, j = pairs[k]
                dx = X[i, 0] - X[j, 0]
                dy = X[i, 1] - X[j, 1]
                d = np.sqrt(dx * dx + dy * dy)
                return d - X[i, 2] - X[j, 2]
            else:
                i, kind = walls[k - len(pairs)]
                if kind == 0:
                    return X[i, 0] - X[i, 2]
                elif kind == 1:
                    return 1.0 - X[i, 0] - X[i, 2]
                elif kind == 2:
                    return X[i, 1] - X[i, 2]
                else:
                    return 1.0 - X[i, 1] - X[i, 2]

        def g_grad(X, k):
            g = np.zeros((n, 3), dtype=np.longdouble)
            if k < len(pairs):
                i, j = pairs[k]
                dx = X[i, 0] - X[j, 0]
                dy = X[i, 1] - X[j, 1]
                d = np.sqrt(dx * dx + dy * dy)
                if d < 1e-18:
                    return g
                ux = dx / d
                uy = dy / d
                g[i, 0] += ux; g[i, 1] += uy; g[i, 2] -= 1.0
                g[j, 0] -= ux; g[j, 1] -= uy; g[j, 2] -= 1.0
            else:
                i, kind = walls[k - len(pairs)]
                if kind == 0:
                    g[i, 0] = 1.0; g[i, 2] = -1.0
                elif kind == 1:
                    g[i, 0] = -1.0; g[i, 2] = -1.0
                elif kind == 2:
                    g[i, 1] = 1.0; g[i, 2] = -1.0
                else:
                    g[i, 1] = -1.0; g[i, 2] = -1.0
            return g

        def g_hess(X, k):
            # Hessian of g_k wrt (x,y,r) per circle, shape (n,3,n,3)
            H = np.zeros((n, 3, n, 3), dtype=np.longdouble)
            if k < len(pairs):
                i, j = pairs[k]
                dx = X[i, 0] - X[j, 0]
                dy = X[i, 1] - X[j, 1]
                d = np.sqrt(dx * dx + dy * dy)
                if d < 1e-18:
                    return H
                ux = dx / d
                uy = dy / d
                # Hessian of d wrt (xi,yi,xj,yj): (I - u u^T)/d on the 2x2 diff block
                Pxx = (1.0 - ux * ux) / d
                Pxy = (-ux * uy) / d
                Pyy = (1.0 - uy * uy) / d
                # d depends on (xi-xj, yi-yj); Hessian same sign for both since linear diff
                H[i, 0, i, 0] += Pxx
                H[i, 0, i, 1] += Pxy
                H[i, 1, i, 0] += Pxy
                H[i, 1, i, 1] += Pyy
                H[j, 0, j, 0] += Pxx
                H[j, 0, j, 1] += Pxy
                H[j, 1, j, 0] += Pxy
                H[j, 1, j, 1] += Pyy
                H[i, 0, j, 0] -= Pxx
                H[i, 0, j, 1] -= Pxy
                H[i, 1, j, 0] -= Pxy
                H[i, 1, j, 1] -= Pyy
                H[j, 0, i, 0] -= Pxx
                H[j, 0, i, 1] -= Pxy
                H[j, 1, i, 0] -= Pxy
                H[j, 1, i, 1] -= Pyy
            return H

        lam = np.zeros(m, dtype=np.longdouble)
        # Initial lambda estimate via least squares on stationarity
        # Stationarity: for each variable v, d(sum r)/dv - sum_k lam_k dg_k/dv = 0
        # Build A (3n x m) and b (3n)
        A = np.zeros((3 * n, m), dtype=np.longdouble)
        b = np.zeros(3 * n, dtype=np.longdouble)
        for k in range(m):
            gk = g_grad(X, k)
            A[:, k] = gk.reshape(-1)
        for i in range(n):
            b[3 * i + 2] = 1.0
        try:
            lam, *_ = np.linalg.lstsq(A.astype(float), b.astype(float), rcond=None)
            lam = lam.astype(np.longdouble)
        except Exception:
            pass

        for it in range(max_iter):
            # Build F and Jacobian
            F = np.zeros(nv, dtype=np.longdouble)
            J = np.zeros((nv, nv), dtype=np.longdouble)
            # Constraint equations: g_k(X) = 0
            for k in range(m):
                F[k] = g_val(X, k)
                gk = g_grad(X, k)
                J[k, :3 * n] = gk.reshape(-1)
            # Stationarity equations
            # For each variable index p in 0..3n-1:
            #   d(sum r)/dp - sum_k lam_k * dg_k/dp = 0
            # d(sum r)/dp = 1 if p is an r-component else 0
            for p in range(3 * n):
                val = 1.0 if (p % 3 == 2) else 0.0
                for k in range(m):
                    gk = g_grad(X, k)
                    val -= lam[k] * gk.reshape(-1)[p]
                F[m + p] = val
            # Jacobian of stationarity wrt X: -sum_k lam_k * Hess(g_k)
            for k in range(m):
                Hk = g_hess(X, k)
                J[m:, :3 * n] -= lam[k] * Hk.reshape(3 * n, 3 * n)
            # Jacobian of stationarity wrt lam: -dg_k/dp
            for k in range(m):
                gk = g_grad(X, k)
                J[m:, m + k] = -gk.reshape(-1)

            # Solve J * dz = -F
            try:
                dz = np.linalg.solve(J.astype(float), (-F).astype(float))
                dz = dz.astype(np.longdouble)
            except Exception:
                break
            # Line search on residual norm
            normF = float(np.linalg.norm(F.astype(float)))
            if normF < tol:
                break
            step = 1.0
            accepted = False
            for _ls in range(20):
                Xn = X.copy()
                Xn_flat = X.reshape(-1) + step * dz[:3 * n]
                Xn = Xn_flat.reshape(n, 3)
                lam_n = lam + step * dz[3 * n:]
                # recompute residual
                Fn = np.zeros(nv, dtype=np.longdouble)
                for k in range(m):
                    Fn[k] = g_val(Xn, k)
                for p in range(3 * n):
                    val = 1.0 if (p % 3 == 2) else 0.0
                    for k in range(m):
                        gk = g_grad(Xn, k)
                        val -= lam_n[k] * gk.reshape(-1)[p]
                    Fn[m + p] = val
                nn = float(np.linalg.norm(Fn.astype(float)))
                if nn < normF:
                    X = Xn
                    lam = lam_n
                    accepted = True
                    break
                step *= 0.5
            if not accepted:
                break

        # Check feasibility and score
        Xf = np.array(X, dtype=float)
        # Verify all constraints
        ok = True
        for i in range(n):
            if Xf[i, 2] <= 0:
                ok = False; break
            if Xf[i, 0] - Xf[i, 2] < -1e-9 or Xf[i, 0] + Xf[i, 2] > 1 + 1e-9:
                ok = False; break
            if Xf[i, 1] - Xf[i, 2] < -1e-9 or Xf[i, 1] + Xf[i, 2] > 1 + 1e-9:
                ok = False; break
        if ok:
            for i in range(n):
                if not ok: break
                for j in range(i + 1, n):
                    d = np.hypot(Xf[i, 0] - Xf[j, 0], Xf[i, 1] - Xf[j, 1])
                    if d < Xf[i, 2] + Xf[j, 2] - 1e-9:
                        ok = False; break
        if ok:
            sc = float(np.sum(Xf[:, 2]))
            if sc > best_score:
                x_best = Xf
    except Exception:
        pass
    return x_best


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 32
    rng = np.random.default_rng(12345)
    HARD = min(budget_seconds * 0.82, budget_seconds - 1.2)

    def elapsed():
        return time.process_time() - t0

    best = None
    best_score = -1.0

    def score(x):
        return float(np.sum(x[:, 2]))

    if start is not None:
        try:
            s = _feasible_fix(start, n)
            best = s
            best_score = score(s)
        except Exception:
            pass

    # Early KKT Newton on start
    if best is not None and elapsed() < budget_seconds - 2.0:
        try:
            kn = _kkt_newton(best, n)
            kn = _feasible_fix(kn, n)
            if score(kn) > best_score:
                best = kn
                best_score = score(kn)
        except Exception:
            pass

    def hex_init(rows, cols):
        pts = []
        for j in range(rows):
            y = (j + 0.5) / rows
            off = 0.5 if j % 2 == 0 else 1.0
            cnt = cols if j % 2 == 0 else cols - 1
            for i in range(cnt):
                x = (i + off) / cols
                pts.append((x, y))
        return pts

    def grid_init(g):
        pts = []
        for j in range(g):
            for i in range(g):
                pts.append(((i + 0.5) / g, (j + 0.5) / g))
        return pts

    inits = []
    for rows, cols in [(6, 6), (5, 7), (7, 5), (6, 7), (8, 4)]:
        p = hex_init(rows, cols)
        if len(p) >= n:
            inits.append(np.array(p[:n]))
    for g in (6, 7):
        p = grid_init(g)
        if len(p) >= n:
            inits.append(np.array(p[:n]))

    def make_cand(centers):
        rlp = _lp_radii(centers, n)
        if rlp is None:
            rlp = np.full(n, 0.05)
        c = np.column_stack([centers, rlp])
        return _feasible_fix(c, n)

    def consider(cand):
        nonlocal best, best_score
        cand = _feasible_fix(cand, n)
        if score(cand) > best_score:
            best_score = score(cand)
            best = cand

    if best is not None and elapsed() < HARD:
        pol = _slsqp_polish(best, n, maxiter=3000, ftol=1e-16)
        pol = _feasible_fix(pol, n)
        if score(pol) > best_score:
            best_score = score(pol)
            best = pol

    for centers in inits:
        if elapsed() > 0.5 * budget_seconds:
            break
        try:
            cand = make_cand(centers)
            consider(cand)
            if elapsed() < 0.5 * budget_seconds:
                pol = _slsqp_polish(cand, n, maxiter=1200)
                pol = _feasible_fix(pol, n)
                if score(pol) > best_score:
                    best_score = score(pol)
                    best = pol
        except Exception:
            pass

    while best is not None and elapsed() < HARD:
        try:
            cand = best.copy()
            scale = rng.uniform(0.01, 0.05)
            cand[:, 0] += rng.normal(0, scale, n)
            cand[:, 1] += rng.normal(0, scale, n)
            cand = _feasible_fix(cand, n)
            newc = make_cand(cand[:, :2])
            pol = _slsqp_polish(newc, n, maxiter=1200)
            pol = _feasible_fix(pol, n)
            if score(pol) > best_score:
                best_score = score(pol)
                best = pol
        except Exception:
            break

    if best is None:
        if start is not None:
            return _feasible_fix(start, n)
        p = hex_init(6, 6)
        return make_cand(np.array(p[:n]))

    try:
        centers = best[:, :2].copy()
        r = _lp_radii(centers, n)
        if r is not None:
            cand = np.column_stack([centers, r])
            cand = _feasible_fix(cand, n)
            if score(cand) > best_score:
                best = cand
                best_score = score(cand)
    except Exception:
        pass

    margin = 1.5
    it = 0
    while best is not None and it < 40 and elapsed() < budget_seconds - margin:
        it += 1
        try:
            v, opt = _slp_step(best, n, delta=2e-3)
        except Exception:
            break
        if v is None or opt < 1e-12:
            break
        try:
            x_new = best.reshape(-1) + 0.5 * v
            x_new = x_new.reshape(n, 3)
            x_new = _feasible_fix(x_new, n)
            pol = _slsqp_polish(x_new, n, maxiter=2000)
            pol = _feasible_fix(pol, n)
            if score(pol) > best_score:
                best = pol
                best_score = score(pol)
            else:
                x_new2 = best.reshape(-1) + 0.25 * v
                x_new2 = _feasible_fix(x_new2.reshape(n, 3), n)
                pol2 = _slsqp_polish(x_new2, n, maxiter=2000)
                pol2 = _feasible_fix(pol2, n)
                if score(pol2) > best_score:
                    best = pol2
                    best_score = score(pol2)
                else:
                    break
        except Exception:
            break

    # Final KKT Newton polish
    if best is not None and elapsed() < budget_seconds - 0.5:
        try:
            kn = _kkt_newton(best, n)
            kn = _feasible_fix(kn, n)
            if score(kn) > best_score:
                best = kn
                best_score = score(kn)
        except Exception:
            pass

    return best

import numpy as np
import time
from scipy.optimize import linprog, minimize


def _feasible(x, n, safety=1e-11):
    x = np.array(x, dtype=float).reshape(n, 3)
    x[:, 2] = np.maximum(x[:, 2], 1e-7)
    x[:, 0] = np.clip(x[:, 0], x[:, 2], 1.0 - x[:, 2])
    x[:, 1] = np.clip(x[:, 1], x[:, 2], 1.0 - x[:, 2])
    for _ in range(200):
        changed = False
        for i in range(n):
            for j in range(i + 1, n):
                dx = x[i, 0] - x[j, 0]
                dy = x[i, 1] - x[j, 1]
                d = np.hypot(dx, dy)
                s = x[i, 2] + x[j, 2]
                if d < s:
                    changed = True
                    excess = s - d + safety
                    x[i, 2] -= excess / 2
                    x[j, 2] -= excess / 2
        x[:, 2] = np.maximum(x[:, 2], 1e-7)
        x[:, 0] = np.clip(x[:, 0], x[:, 2], 1.0 - x[:, 2])
        x[:, 1] = np.clip(x[:, 1], x[:, 2], 1.0 - x[:, 2])
        if not changed:
            break
    x[:, 2] *= (1.0 - 1e-12)
    return x


def _lp_radii(centers, n):
    c = -np.ones(n)
    A_ub = []
    b_ub = []
    for i in range(n):
        for w in (centers[i, 0], 1.0 - centers[i, 0],
                  centers[i, 1], 1.0 - centers[i, 1]):
            row = np.zeros(n)
            row[i] = 1.0
            A_ub.append(row)
            b_ub.append(max(w, 0.0))
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(centers[i, 0] - centers[j, 0],
                         centers[i, 1] - centers[j, 1])
            row = np.zeros(n)
            row[i] = 1.0
            row[j] = 1.0
            A_ub.append(row)
            b_ub.append(max(d, 0.0))
    bounds = [(1e-7, None)] * n
    try:
        res = linprog(c, A_ub=np.array(A_ub), b_ub=np.array(b_ub),
                      bounds=bounds, method='highs',
                      options={'primal_feasibility_tolerance': 1e-10,
                               'dual_feasibility_tolerance': 1e-10})
        if res.success:
            return np.maximum(res.x, 1e-7)
    except Exception:
        pass
    return None


def _slsqp_polish(x_init, n, maxiter, ftol=1e-15):
    def obj(v):
        return -np.sum(v[2::3])

    def obj_grad(v):
        g = np.zeros_like(v)
        g[2::3] = -1.0
        return g

    bounds = []
    for i in range(n):
        bounds.append((0.0, 1.0))
        bounds.append((0.0, 1.0))
        bounds.append((1e-6, 0.5))

    cons = []
    for i in range(n):
        for kind in range(4):
            def make_wall(i, kind):
                def f(v):
                    X = v.reshape(n, 3)
                    if kind == 0:
                        return X[i, 0] - X[i, 2]
                    elif kind == 1:
                        return 1.0 - X[i, 0] - X[i, 2]
                    elif kind == 2:
                        return X[i, 1] - X[i, 2]
                    else:
                        return 1.0 - X[i, 1] - X[i, 2]
                def jac(v):
                    g = np.zeros(3 * n)
                    if kind == 0:
                        g[3 * i] = 1.0
                    elif kind == 1:
                        g[3 * i] = -1.0
                    elif kind == 2:
                        g[3 * i + 1] = 1.0
                    else:
                        g[3 * i + 1] = -1.0
                    g[3 * i + 2] = -1.0
                    return g
                return f, jac
            f, j = make_wall(i, kind)
            cons.append({'type': 'ineq', 'fun': f, 'jac': j})

    for i in range(n):
        for j in range(i + 1, n):
            def make_pair(i, j):
                def f(v):
                    X = v.reshape(n, 3)
                    dx = X[i, 0] - X[j, 0]
                    dy = X[i, 1] - X[j, 1]
                    return dx * dx + dy * dy - (X[i, 2] + X[j, 2]) ** 2
                def jac(v):
                    X = v.reshape(n, 3)
                    dx = X[i, 0] - X[j, 0]
                    dy = X[i, 1] - X[j, 1]
                    s = X[i, 2] + X[j, 2]
                    g = np.zeros(3 * n)
                    g[3 * i] = 2.0 * dx
                    g[3 * i + 1] = 2.0 * dy
                    g[3 * i + 2] = -2.0 * s
                    g[3 * j] = -2.0 * dx
                    g[3 * j + 1] = -2.0 * dy
                    g[3 * j + 2] = -2.0 * s
                    return g
                return f, jac
            f, j = make_pair(i, j)
            cons.append({'type': 'ineq', 'fun': f, 'jac': j})

    v0 = x_init.reshape(-1).copy()
    v0[2::3] = np.clip(v0[2::3], 1e-6, 0.5)
    v0[0::3] = np.clip(v0[0::3], 0.0, 1.0)
    v0[1::3] = np.clip(v0[1::3], 0.0, 1.0)
    try:
        res = minimize(obj, v0, jac=obj_grad, method='SLSQP',
                       bounds=bounds, constraints=cons,
                       options={'maxiter': maxiter, 'ftol': ftol})
        return res.x.reshape(n, 3)
    except Exception:
        return x_init


def _slp_step(x, n, delta=1.5e-3):
    tol = 1e-7
    A_ub = []
    b_ub = []
    for i in range(n):
        for j in range(i + 1, n):
            dx = x[i, 0] - x[j, 0]
            dy = x[i, 1] - x[j, 1]
            d = np.hypot(dx, dy)
            gap = d - x[i, 2] - x[j, 2]
            if gap < tol:
                if d < 1e-12:
                    continue
                ux = dx / d
                uy = dy / d
                row = np.zeros(3 * n)
                row[3 * i] = -ux
                row[3 * i + 1] = -uy
                row[3 * i + 2] = 1.0
                row[3 * j] = ux
                row[3 * j + 1] = uy
                row[3 * j + 2] = 1.0
                A_ub.append(row)
                b_ub.append(-gap + 1e-12)
    for i in range(n):
        if x[i, 0] - x[i, 2] < tol:
            row = np.zeros(3 * n); row[3 * i] = -1.0; row[3 * i + 2] = 1.0
            A_ub.append(row); b_ub.append(x[i, 2] - x[i, 0] + 1e-12)
        if 1.0 - x[i, 0] - x[i, 2] < tol:
            row = np.zeros(3 * n); row[3 * i] = 1.0; row[3 * i + 2] = 1.0
            A_ub.append(row); b_ub.append(1.0 - x[i, 0] - x[i, 2] + 1e-12)
        if x[i, 1] - x[i, 2] < tol:
            row = np.zeros(3 * n); row[3 * i + 1] = -1.0; row[3 * i + 2] = 1.0
            A_ub.append(row); b_ub.append(x[i, 2] - x[i, 1] + 1e-12)
        if 1.0 - x[i, 1] - x[i, 2] < tol:
            row = np.zeros(3 * n); row[3 * i + 1] = 1.0; row[3 * i + 2] = 1.0
            A_ub.append(row); b_ub.append(1.0 - x[i, 1] - x[i, 2] + 1e-12)
    c = np.zeros(3 * n)
    c[2::3] = -1.0
    lb = np.empty(3 * n)
    ub = np.empty(3 * n)
    lb[0::3] = -delta; ub[0::3] = delta
    lb[1::3] = -delta; ub[1::3] = delta
    lb[2::3] = -delta; ub[2::3] = 3 * delta
    bounds = list(zip(lb, ub))
    try:
        res = linprog(c, A_ub=np.array(A_ub), b_ub=np.array(b_ub),
                      bounds=bounds, method='highs',
                      options={'primal_feasibility_tolerance': 1e-10,
                               'dual_feasibility_tolerance': 1e-10})
        if res.success:
            return res.x
    except Exception:
        pass
    return None


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 32
    deadline = t0 + budget_seconds - 0.9
    rng = np.random.default_rng(20240711)

    def score(x):
        return float(np.sum(x[:, 2]))

    best = None
    best_score = -1.0

    if start is not None:
        try:
            s = _feasible(start, n)
            best = s
            best_score = score(s)
        except Exception:
            pass

    if best is None:
        pts = []
        rows = 6
        for j in range(rows):
            y = (j + 0.5) / rows
            cnt = 6 if j % 2 == 0 else 5
            for i in range(cnt):
                x = (i + 0.5) / 6 if j % 2 == 0 else (i + 1.0) / 6
                pts.append((x, y))
        pts = pts[:n]
        while len(pts) < n:
            pts.append((0.5, 0.5))
        centers0 = np.array(pts, dtype=float)
        x0 = np.column_stack([centers0, np.full(n, 0.08)])
        best = _feasible(x0, n)
        best_score = score(best)

    # Polish start with SLSQP first (cheap, often boosts score).
    if time.process_time() < deadline:
        try:
            pol = _slsqp_polish(best, n, maxiter=300)
            pol = _feasible(pol, n)
            if score(pol) > best_score:
                best = pol
                best_score = score(pol)
        except Exception:
            pass

    it = 0
    stall = 0
    while time.process_time() < deadline:
        it += 1
        x = best.copy()
        for _ in range(6):
            if time.process_time() >= deadline:
                break
            step = _slp_step(x, delta=1.5e-3)
            if step is None:
                break
            xn = _feasible((x.reshape(-1) + step).reshape(n, 3), n)
            if score(xn) > score(x) + 1e-10:
                x = xn
            else:
                step = _slp_step(x, delta=5e-4)
                if step is None:
                    break
                xn = _feasible((x.reshape(-1) + step).reshape(n, 3), n)
                if score(xn) > score(x) + 1e-11:
                    x = xn
                else:
                    break

        rlp = _lp_radii(x[:, :2], n)
        if rlp is not None:
            cand = _feasible(np.column_stack([x[:, :2], rlp]), n)
            if score(cand) > score(x):
                x = cand

        if score(x) > best_score + 1e-10:
            best = x
            best_score = score(x)
            stall = 0
        else:
            stall += 1

        # Periodically run SLSQP polish to escape SLP local optima.
        if stall > 0 and stall % 4 == 0 and time.process_time() < deadline:
            try:
                pol = _slsqp_polish(best, n, maxiter=200)
                pol = _feasible(pol, n)
                if score(pol) > best_score + 1e-9:
                    best = pol
                    best_score = score(pol)
                    stall = 0
            except Exception:
                pass

        scale = 0.004 + 0.02 * min(stall, 6) / 6.0
        cand = best.copy()
        cand[:, 0] += rng.normal(0, scale, n)
        cand[:, 1] += rng.normal(0, scale, n)
        cand[:, 2] *= rng.uniform(0.97, 1.05, n)
        cand = _feasible(cand, n)
        rlp = _lp_radii(cand[:, :2], n)
        if rlp is not None:
            cand2 = _feasible(np.column_stack([cand[:, :2], rlp]), n)
            if score(cand2) > score(cand):
                cand = cand2
        if score(cand) > best_score:
            best = cand
            best_score = score(cand)
            stall = 0

    # Final SLSQP polish with remaining budget.
    if time.process_time() < deadline:
        try:
            pol = _slsqp_polish(best, n, maxiter=500)
            pol = _feasible(pol, n)
            if score(pol) > best_score:
                best = pol
                best_score = score(pol)
        except Exception:
            pass

    best = _feasible(best, n)
    return best

import numpy as np
import time
from scipy.optimize import minimize, linprog


def _feasible_fix(x, n):
    x = np.array(x, dtype=float).reshape(n, 3)
    x[:, 2] = np.maximum(x[:, 2], 1e-6)
    x[:, 0] = np.clip(x[:, 0], x[:, 2], 1.0 - x[:, 2])
    x[:, 1] = np.clip(x[:, 1], x[:, 2], 1.0 - x[:, 2])
    for _ in range(100):
        changed = False
        for i in range(n):
            for j in range(i + 1, n):
                dx = x[i, 0] - x[j, 0]
                dy = x[i, 1] - x[j, 1]
                d = np.hypot(dx, dy)
                s = x[i, 2] + x[j, 2]
                if d < s:
                    changed = True
                    excess = s - d + 1e-11
                    x[i, 2] -= excess / 2
                    x[j, 2] -= excess / 2
        x[:, 2] = np.maximum(x[:, 2], 1e-6)
        x[:, 0] = np.clip(x[:, 0], x[:, 2], 1.0 - x[:, 2])
        x[:, 1] = np.clip(x[:, 1], x[:, 2], 1.0 - x[:, 2])
        if not changed:
            break
    x[:, 2] *= (1.0 - 1e-12)
    return x


def _lp_radii(centers, n):
    c = -np.ones(n)
    A_ub = []
    b_ub = []
    for i in range(n):
        for w in (centers[i, 0], 1.0 - centers[i, 0],
                  centers[i, 1], 1.0 - centers[i, 1]):
            row = np.zeros(n)
            row[i] = 1.0
            A_ub.append(row)
            b_ub.append(max(w, 0.0))
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(centers[i, 0] - centers[j, 0],
                         centers[i, 1] - centers[j, 1])
            row = np.zeros(n)
            row[i] = 1.0
            row[j] = 1.0
            A_ub.append(row)
            b_ub.append(max(d, 0.0))
    bounds = [(1e-6, None)] * n
    try:
        res = linprog(c, A_ub=np.array(A_ub), b_ub=np.array(b_ub),
                      bounds=bounds, method='highs',
                      options={'primal_feasibility_tolerance': 1e-10,
                               'dual_feasibility_tolerance': 1e-10})
        if res.success:
            return np.maximum(res.x, 1e-6)
    except Exception:
        pass
    return None


def _slsqp_polish(x_init, n, maxiter, ftol=1e-14):
    def obj(v):
        return -np.sum(v[2::3])

    def obj_grad(v):
        g = np.zeros_like(v)
        g[2::3] = -1.0
        return g

    bounds = []
    for i in range(n):
        bounds.append((0.0, 1.0))
        bounds.append((0.0, 1.0))
        bounds.append((1e-4, 0.5))

    cons = []
    for i in range(n):
        for kind in range(4):
            def make_wall(i, kind):
                def f(v):
                    X = v.reshape(n, 3)
                    if kind == 0:
                        return X[i, 0] - X[i, 2]
                    elif kind == 1:
                        return 1.0 - X[i, 0] - X[i, 2]
                    elif kind == 2:
                        return X[i, 1] - X[i, 2]
                    else:
                        return 1.0 - X[i, 1] - X[i, 2]
                def jac(v):
                    g = np.zeros(3 * n)
                    if kind == 0:
                        g[3 * i] = 1.0
                    elif kind == 1:
                        g[3 * i] = -1.0
                    elif kind == 2:
                        g[3 * i + 1] = 1.0
                    else:
                        g[3 * i + 1] = -1.0
                    g[3 * i + 2] = -1.0
                    return g
                return f, jac
            f, j = make_wall(i, kind)
            cons.append({'type': 'ineq', 'fun': f, 'jac': j})

    for i in range(n):
        for j in range(i + 1, n):
            def make_pair(i, j):
                def f(v):
                    X = v.reshape(n, 3)
                    dx = X[i, 0] - X[j, 0]
                    dy = X[i, 1] - X[j, 1]
                    return dx * dx + dy * dy - (X[i, 2] + X[j, 2]) ** 2
                def jac(v):
                    X = v.reshape(n, 3)
                    dx = X[i, 0] - X[j, 0]
                    dy = X[i, 1] - X[j, 1]
                    s = X[i, 2] + X[j, 2]
                    g = np.zeros(3 * n)
                    g[3 * i] = 2.0 * dx
                    g[3 * i + 1] = 2.0 * dy
                    g[3 * i + 2] = -2.0 * s
                    g[3 * j] = -2.0 * dx
                    g[3 * j + 1] = -2.0 * dy
                    g[3 * j + 2] = -2.0 * s
                    return g
                return f, jac
            f, j = make_pair(i, j)
            cons.append({'type': 'ineq', 'fun': f, 'jac': j})

    v0 = x_init.reshape(-1).copy()
    v0[2::3] = np.clip(v0[2::3], 1e-4, 0.5)
    v0[0::3] = np.clip(v0[0::3], 0.0, 1.0)
    v0[1::3] = np.clip(v0[1::3], 0.0, 1.0)
    try:
        res = minimize(obj, v0, jac=obj_grad, method='SLSQP',
                       bounds=bounds, constraints=cons,
                       options={'maxiter': maxiter, 'ftol': ftol})
        return res.x.reshape(n, 3)
    except Exception:
        return x_init


def _slp_step(x, n, delta=2e-3):
    tol = 1e-6
    A_ub = []
    b_ub = []
    for i in range(n):
        for j in range(i + 1, n):
            dx = x[i, 0] - x[j, 0]
            dy = x[i, 1] - x[j, 1]
            d = np.hypot(dx, dy)
            gap = d - x[i, 2] - x[j, 2]
            if gap < tol:
                if d < 1e-12:
                    continue
                ux = dx / d
                uy = dy / d
                row = np.zeros(3 * n)
                row[3 * i] = -ux
                row[3 * i + 1] = -uy
                row[3 * i + 2] = 1.0
                row[3 * j] = ux
                row[3 * j + 1] = uy
                row[3 * j + 2] = 1.0
                A_ub.append(row)
                b_ub.append(0.0)
    for i in range(n):
        if abs(x[i, 0] - x[i, 2]) < tol:
            row = np.zeros(3 * n)
            row[3 * i] = -1.0
            row[3 * i + 2] = 1.0
            A_ub.append(row); b_ub.append(0.0)
        if abs(1.0 - x[i, 0] - x[i, 2]) < tol:
            row = np.zeros(3 * n)
            row[3 * i] = 1.0
            row[3 * i + 2] = 1.0
            A_ub.append(row); b_ub.append(0.0)
        if abs(x[i, 1] - x[i, 2]) < tol:
            row = np.zeros(3 * n)
            row[3 * i + 1] = -1.0
            row[3 * i + 2] = 1.0
            A_ub.append(row); b_ub.append(0.0)
        if abs(1.0 - x[i, 1] - x[i, 2]) < tol:
            row = np.zeros(3 * n)
            row[3 * i + 1] = 1.0
            row[3 * i + 2] = 1.0
            A_ub.append(row); b_ub.append(0.0)
    if not A_ub:
        return None, 0.0
    c = np.zeros(3 * n)
    c[2::3] = -1.0
    bounds = [(-delta, delta)] * (3 * n)
    try:
        res = linprog(c, A_ub=np.array(A_ub), b_ub=np.array(b_ub),
                      bounds=bounds, method='highs',
                      options={'primal_feasibility_tolerance': 1e-10,
                               'dual_feasibility_tolerance': 1e-10})
        if res.success:
            return res.x, -res.fun
    except Exception:
        pass
    return None, 0.0


def _perturb_centers(centers, rng, n, scale):
    c = centers.copy()
    k = rng.integers(1, max(2, n // 2))
    idx = rng.choice(n, size=k, replace=False)
    c[idx, 0] += rng.normal(0, scale, k)
    c[idx, 1] += rng.normal(0, scale, k)
    return c


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 32
    rng = np.random.default_rng(12345)
    HARD = min(budget_seconds * 0.85, budget_seconds - 1.0)

    def elapsed():
        return time.process_time() - t0

    best = None
    best_score = -1.0

    def score(x):
        return float(np.sum(x[:, 2]))

    if start is not None:
        try:
            s = _feasible_fix(start, n)
            best = s
            best_score = score(s)
        except Exception:
            pass

    def hex_init(rows, cols):
        pts = []
        for j in range(rows):
            y = (j + 0.5) / rows
            off = 0.5 if j % 2 == 0 else 1.0
            cnt = cols if j % 2 == 0 else cols - 1
            for i in range(cnt):
                x = (i + off) / cols
                pts.append((x, y))
        return pts

    def grid_init(g):
        pts = []
        for j in range(g):
            for i in range(g):
                pts.append(((i + 0.5) / g, (j + 0.5) / g))
        return pts

    def make_cand(centers):
        rlp = _lp_radii(centers, n)
        if rlp is None:
            rlp = np.full(n, 0.05)
        c = np.column_stack([centers, rlp])
        return _feasible_fix(c, n)

    def consider(cand):
        nonlocal best, best_score
        cand = _feasible_fix(cand, n)
        sc = score(cand)
        if sc > best_score:
            best_score = sc
            best = cand
            return True
        return False

    # Polish start with strong SLSQP
    if best is not None and elapsed() < HARD:
        pol = _slsqp_polish(best, n, maxiter=4000, ftol=1e-16)
        pol = _feasible_fix(pol, n)
        if score(pol) > best_score:
            best_score = score(pol)
            best = pol

    inits = []
    for rows, cols in [(6, 6), (5, 7), (7, 5), (6, 7), (8, 4), (7, 6)]:
        p = hex_init(rows, cols)
        if len(p) >= n:
            inits.append(np.array(p[:n]))
    for g in (6, 7):
        p = grid_init(g)
        if len(p) >= n:
            inits.append(np.array(p[:n]))

    # Try fresh inits only if we don't already have a strong start
    if best is None or best_score < 2.90:
        for centers in inits:
            if elapsed() > 0.35 * budget_seconds:
                break
            try:
                cand = make_cand(centers)
                consider(cand)
                if elapsed() < 0.35 * budget_seconds:
                    pol = _slsqp_polish(cand, n, maxiter=1500)
                    pol = _feasible_fix(pol, n)
                    consider(pol)
            except Exception:
                pass

    # SLP tangent-space loop with random basin-hopping kicks
    margin = 1.0
    it = 0
    stall = 0
    while best is not None and it < 400 and elapsed() < HARD - margin:
        it += 1
        try:
            v, opt = _slp_step(best, n, delta=5e-3)
        except Exception:
            break
        if v is None or opt < 1e-13:
            # basin hop: perturb centers, re-solve LP, polish
            scale = 0.02 * (1.0 + 0.5 * stall)
            newc = _perturb_centers(best[:, :2], rng, n, scale)
            cand = make_cand(newc)
            pol = _slsqp_polish(cand, n, maxiter=2000)
            pol = _feasible_fix(pol, n)
            if consider(pol):
                stall = 0
            else:
                stall += 1
                if stall > 6:
                    break
            continue
        improved = False
        for step in (1.0, 0.5, 0.25, 0.1):
            try:
                x_new = (best.reshape(-1) + step * v).reshape(n, 3)
                x_new = _feasible_fix(x_new, n)
                pol = _slsqp_polish(x_new, n, maxiter=2500)
                pol = _feasible_fix(pol, n)
                if consider(pol):
                    improved = True
                    break
            except Exception:
                continue
        if not improved:
            stall += 1
            newc = _perturb_centers(best[:, :2], rng, n, 0.015)
            cand = make_cand(newc)
            pol = _slsqp_polish(cand, n, maxiter=1500)
            pol = _feasible_fix(pol, n)
            if consider(pol):
                stall = 0
            if stall > 8:
                break
        else:
            stall = 0

    if best is None:
        if start is not None:
            return _feasible_fix(start, n)
        p = hex_init(6, 6)
        return make_cand(np.array(p[:n]))

    # Final LP re-solve on best centers
    try:
        centers = best[:, :2].copy()
        r = _lp_radii(centers, n)
        if r is not None:
            cand = np.column_stack([centers, r])
            cand = _feasible_fix(cand, n)
            if score(cand) > best_score:
                best = cand
                best_score = score(cand)
    except Exception:
        pass

    best = _feasible_fix(best, n)
    return best

