            row = np.zeros(3 * n)
            row[3 * i] = 1.0
            row[3 * i + 2] = 1.0
            A_ub.append(row); b_ub.append(0.0)
        if abs(x[i, 1] - x[i, 2]) < tol:
            row = np.zeros(3 * n)
            row[3 * i + 1] = -1.0
            row[3 * i + 2] = 1.0
            A_ub.append(row); b_ub.append(0.0)
        if abs(1.0 - x[i, 1] - x[i, 2]) < tol:
            row = np.zeros(3 * n)
            row[3 * i + 1] = 1.0
            row[3 * i + 2] = 1.0
            A_ub.append(row); b_ub.append(0.0)
    if not A_ub:
        return None, 0.0
    c = np.zeros(3 * n)
    c[2::3] = -1.0
    bounds = [(-delta, delta)] * (3 * n)
    try:
        res = linprog(c, A_ub=np.array(A_ub), b_ub=np.array(b_ub),
                      bounds=bounds, method='highs',
                      options={'primal_feasibility_tolerance': 1e-10,
                               'dual_feasibility_tolerance': 1e-10})
        if res.success:
            return res.x, -res.fun
    except Exception:
        pass
    return None, 0.0


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 32
    rng = np.random.default_rng(12345)
    HARD = min(budget_seconds * 0.82, budget_seconds - 1.2)

    def elapsed():
        return time.process_time() - t0

    best = None
    best_score = -1.0

    def score(x):
        return float(np.sum(x[:, 2]))

    if start is not None:
        try:
            s = _feasible_fix(start, n)
            best = s
            best_score = score(s)
        except Exception:
            pass

    def hex_init(rows, cols):
        pts = []
        for j in range(rows):
            y = (j + 0.5) / rows
            off = 0.5 if j % 2 == 0 else 1.0
            cnt = cols if j % 2 == 0 else cols - 1
            for i in range(cnt):
                x = (i + off) / cols
                pts.append((x, y))
        return pts

    def grid_init(g):
        pts = []
        for j in range(g):
            for i in range(g):
                pts.append(((i + 0.5) / g, (j + 0.5) / g))
        return pts

    def fourfold_init():
        # 8 centers in [0,0.5]x[0,0.5], including points on x=0.5 and y=0.5
        base = [
            (0.10, 0.10),
            (0.30, 0.10),
            (0.50, 0.10),
            (0.10, 0.30),
            (0.30, 0.30),
            (0.50, 0.30),
            (0.10, 0.50),
            (0.30, 0.50),
        ]
        pts = []
        for (x, y) in base:
            for sx in (x, 1.0 - x):
                for sy in (y, 1.0 - y):
                    pts.append((sx, sy))
        # dedupe while preserving order
        seen = set()
        out = []
        for p in pts:
            key = (round(p[0], 9), round(p[1], 9))
            if key not in seen:
                seen.add(key)
                out.append(p)
        return out

    def corner_ring_init():
        pts = []
        # 4 corners offset inward
        for cx, cy in [(0.13, 0.13), (0.87, 0.13), (0.13, 0.87), (0.87, 0.87)]:
            pts.append((cx, cy))
        # ring of 12 at radius 0.30 from centre
        for k in range(12):
            a = 2.0 * np.pi * k / 12.0
            pts.append((0.5 + 0.30 * np.cos(a), 0.5 + 0.30 * np.sin(a)))
        # 16 on a 4x4 interior grid
        for j in range(4):
            for i in range(4):
                pts.append((0.2 + 0.2 * i, 0.2 + 0.2 * j))
        return pts

    inits = []
    # New structurally-different inits first
    try:
        p = fourfold_init()
        if len(p) >= n:
            inits.append(np.array(p[:n]))
    except Exception:
        pass
    try:
        p = corner_ring_init()
        if len(p) >= n:
            inits.append(np.array(p[:n]))
    except Exception:
        pass
    for rows, cols in [(6, 6), (5, 7), (7, 5), (6, 7), (8, 4)]:
        p = hex_init(rows, cols)
        if len(p) >= n:
            inits.append(np.array(p[:n]))
    for g in (6, 7):
        p = grid_init(g)
        if len(p) >= n:
            inits.append(np.array(p[:n]))

    def make_cand(centers):
        rlp = _lp_radii(centers, n)
        if rlp is None:
            rlp = np.full(n, 0.05)
        c = np.column_stack([centers, rlp])
        return _feasible_fix(c, n)

    def consider(cand):
        nonlocal best, best_score
        cand = _feasible_fix(cand, n)
        if score(cand) > best_score:
            best_score = score(cand)
            best = cand

    # Polish the start first
    if best is not None and elapsed() < HARD:
        pol = _slsqp_polish(best, n, maxiter=3000, ftol=1e-16)
        pol = _feasible_fix(pol, n)
        if score(pol) > best_score:
            best_score = score(pol)
            best = pol

    for centers in inits:
        if elapsed() > 0.5 * budget_seconds:
            break
        try:
            cand = make_cand(centers)
            consider(cand)
            if elapsed() < 0.5 * budget_seconds:
                pol = _slsqp_polish(cand, n, maxiter=1200)
                pol = _feasible_fix(pol, n)
                if score(pol) > best_score:
                    best_score = score(pol)
                    best = pol
        except Exception:
            pass

    # Random restarts / perturbations around best
    while best is not None and elapsed() < HARD:
        try:
            cand = best.copy()
            scale = rng.uniform(0.01, 0.05)
            cand[:, 0] += rng.normal(0, scale, n)
            cand[:, 1] += rng.normal(0, scale, n)
            cand = _feasible_fix(cand, n)
            newc = make_cand(cand[:, :2])
            pol = _slsqp_polish(newc, n, maxiter=1200)
            pol = _feasible_fix(pol, n)
            if score(pol) > best_score:
                best_score = score(pol)
                best = pol
        except Exception:
            break

    if best is None:
        if start is not None:
            return _feasible_fix(start, n)
        p = hex_init(6, 6)
        return make_cand(np.array(p[:n]))

    # Final LP re-solve at final centers with tight tolerances
    try:
        centers = best[:, :2].copy()
        r = _lp_radii(centers, n)
        if r is not None:
            cand = np.column_stack([centers, r])
            cand = _feasible_fix(cand, n)
            if score(cand) > best_score:
                best = cand
                best_score = score(cand)
    except Exception:
        pass

    # SLP tangent-space improvement loop
    margin = 1.5
    it = 0
    while best is not None and it < 40 and elapsed() < budget_seconds - margin:
        it += 1
        try:
            v, opt = _slp_step(best, n, delta=2e-3)
        except Exception:
            break
        if v is None or opt < 1e-12:
            break
        try:
            x_new = best.reshape(-1) + 0.5 * v
            x_new = x_new.reshape(n, 3)
            x_new = _feasible_fix(x_new, n)
            pol = _slsqp_polish(x_new, n, maxiter=2000)
            pol = _feasible_fix(pol, n)
            if score(pol) > best_score:
                best = pol
                best_score = score(pol)
            else:
                x_new2 = best.reshape(-1) + 0.25 * v
                x_new2 = _feasible_fix(x_new2.reshape(n, 3), n)
                pol2 = _slsqp_polish(x_new2, n, maxiter=2000)
                pol2 = _feasible_fix(pol2, n)
                if score(pol2) > best_score:
                    best = pol2
                    best_score = score(pol2)
                else:
                    break
        except Exception:
            break

    return best

import numpy as np
import time
from scipy.optimize import minimize, linprog


def _feasible_fix(x, n):
    x = np.array(x, dtype=float).reshape(n, 3)
    x[:, 2] = np.maximum(x[:, 2], 1e-7)
    x[:, 0] = np.clip(x[:, 0], x[:, 2], 1.0 - x[:, 2])
    x[:, 1] = np.clip(x[:, 1], x[:, 2], 1.0 - x[:, 2])
    for _ in range(200):
        changed = False
        for i in range(n):
            for j in range(i + 1, n):
                dx = x[i, 0] - x[j, 0]
                dy = x[i, 1] - x[j, 1]
                d = np.hypot(dx, dy)
                s = x[i, 2] + x[j, 2]
                if d < s:
                    changed = True
                    excess = s - d + 1e-12
                    if d > 1e-12:
                        ux = dx / d
                        uy = dy / d
                        x[i, 0] += ux * excess * 0.5
                        x[i, 1] += uy * excess * 0.5
                        x[j, 0] -= ux * excess * 0.5
                        x[j, 1] -= uy * excess * 0.5
                    x[i, 2] -= excess * 0.25
                    x[j, 2] -= excess * 0.25
        x[:, 2] = np.maximum(x[:, 2], 1e-7)
        x[:, 0] = np.clip(x[:, 0], x[:, 2], 1.0 - x[:, 2])
        x[:, 1] = np.clip(x[:, 1], x[:, 2], 1.0 - x[:, 2])
        if not changed:
            break
    x[:, 2] *= (1.0 - 1e-13)
    return x


def _lp_radii(centers, n):
    c = -np.ones(n)
    A_ub = []
    b_ub = []
    for i in range(n):
        for w in (centers[i, 0], 1.0 - centers[i, 0],
                  centers[i, 1], 1.0 - centers[i, 1]):
            row = np.zeros(n)
            row[i] = 1.0
            A_ub.append(row)
            b_ub.append(max(w, 0.0))
    for i in range(n):
        for j in range(i + 1, n):
            d = np.hypot(centers[i, 0] - centers[j, 0],
                         centers[i, 1] - centers[j, 1])
            row = np.zeros(n)
            row[i] = 1.0
            row[j] = 1.0
            A_ub.append(row)
            b_ub.append(max(d, 0.0))
    bounds = [(1e-7, None)] * n
    try:
        res = linprog(c, A_ub=np.array(A_ub), b_ub=np.array(b_ub),
                      bounds=bounds, method='highs',
                      options={'primal_feasibility_tolerance': 1e-10,
                               'dual_feasibility_tolerance': 1e-10})
        if res.success:
            return np.maximum(res.x, 1e-7)
    except Exception:
        pass
    return None


def _slsqp_polish(x_init, n, maxiter, ftol=1e-15):
    def obj(v):
        return -np.sum(v[2::3])

    def obj_grad(v):
        g = np.zeros_like(v)
        g[2::3] = -1.0
        return g

    bounds = []
    for i in range(n):
        bounds.append((0.0, 1.0))
        bounds.append((0.0, 1.0))
        bounds.append((1e-5, 0.5))

    cons = []
    for i in range(n):
        for kind in range(4):
            def make_wall(i, kind):
                def f(v):
                    X = v.reshape(n, 3)
                    if kind == 0:
                        return X[i, 0] - X[i, 2]
                    elif kind == 1:
                        return 1.0 - X[i, 0] - X[i, 2]
                    elif kind == 2:
                        return X[i, 1] - X[i, 2]
                    else:
                        return 1.0 - X[i, 1] - X[i, 2]
                def jac(v):
                    g = np.zeros(3 * n)
                    if kind == 0:
                        g[3 * i] = 1.0
                    elif kind == 1:
                        g[3 * i] = -1.0
                    elif kind == 2:
                        g[3 * i + 1] = 1.0
                    else:
                        g[3 * i + 1] = -1.0
                    g[3 * i + 2] = -1.0
                    return g
                return f, jac
            f, j = make_wall(i, kind)
            cons.append({'type': 'ineq', 'fun': f, 'jac': j})

    for i in range(n):
        for j in range(i + 1, n):
            def make_pair(i, j):
                def f(v):
                    X = v.reshape(n, 3)
                    dx = X[i, 0] - X[j, 0]
                    dy = X[i, 1] - X[j, 1]
                    return dx * dx + dy * dy - (X[i, 2] + X[j, 2]) ** 2
                def jac(v):
                    X = v.reshape(n, 3)
                    dx = X[i, 0] - X[j, 0]
                    dy = X[i, 1] - X[j, 1]
                    s = X[i, 2] + X[j, 2]
                    g = np.zeros(3 * n)
                    g[3 * i] = 2.0 * dx
                    g[3 * i + 1] = 2.0 * dy
                    g[3 * i + 2] = -2.0 * s
                    g[3 * j] = -2.0 * dx
                    g[3 * j + 1] = -2.0 * dy
                    g[3 * j + 2] = -2.0 * s
                    return g
                return f, jac
            f, j = make_pair(i, j)
            cons.append({'type': 'ineq', 'fun': f, 'jac': j})

    v0 = x_init.reshape(-1).copy()
    v0[2::3] = np.clip(v0[2::3], 1e-5, 0.5)
    v0[0::3] = np.clip(v0[0::3], 0.0, 1.0)
    v0[1::3] = np.clip(v0[1::3], 0.0, 1.0)
    try:
        res = minimize(obj, v0, jac=obj_grad, method='SLSQP',
                       bounds=bounds, constraints=cons,
                       options={'maxiter': maxiter, 'ftol': ftol})
        return res.x.reshape(n, 3)
    except Exception:
        return x_init


def _slp_step(x, n, delta=2e-3):
    tol = 1e-6
    A_ub = []
    b_ub = []
    for i in range(n):
        for j in range(i + 1, n):
            dx = x[i, 0] - x[j, 0]
            dy = x[i, 1] - x[j, 1]
            d = np.hypot(dx, dy)
            gap = d - x[i, 2] - x[j, 2]
            if gap < tol:
                if d < 1e-12:
                    continue
                ux = dx / d
                uy = dy / d
                row = np.zeros(3 * n)
                row[3 * i] = -ux
                row[3 * i + 1] = -uy
                row[3 * i + 2] = 1.0
                row[3 * j] = ux
                row[3 * j + 1] = uy
                row[3 * j + 2] = 1.0
                A_ub.append(row)
                b_ub.append(0.0)
    for i in range(n):
        if abs(x[i, 0] - x[i, 2]) < tol:
            row = np.zeros(3 * n)
            row[3 * i] = -1.0
            row[3 * i + 2] = 1.0
            A_ub.append(row); b_ub.append(0.0)
        if abs(1.0 - x[i, 0] - x[i, 2]) < tol:
            row = np.zeros(3 * n)
            row[3 * i] = 1.0
            row[3 * i + 2] = 1.0
            A_ub.append(row); b_ub.append(0.0)
        if abs(x[i, 1] - x[i, 2]) < tol:
            row = np.zeros(3 * n)
            row[3 * i + 1] = -1.0
            row[3 * i + 2] = 1.0
            A_ub.append(row); b_ub.append(0.0)
        if abs(1.0 - x[i, 1] - x[i, 2]) < tol:
            row = np.zeros(3 * n)
            row[3 * i + 1] = 1.0
            row[3 * i + 2] = 1.0
            A_ub.append(row); b_ub.append(0.0)
    if not A_ub:
        return None, 0.0
    c = np.zeros(3 * n)
    c[2::3] = -1.0
    bounds = [(-delta, delta)] * (3 * n)
    try:
        res = linprog(c, A_ub=np.array(A_ub), b_ub=np.array(b_ub),
                      bounds=bounds, method='highs',
                      options={'primal_feasibility_tolerance': 1e-10,
                               'dual_feasibility_tolerance': 1e-10})
        if res.success:
            return res.x, -res.fun
    except Exception:
        pass
    return None, 0.0


def construct(budget_seconds, start):
    t0 = time.process_time()
    n = 32
    rng = np.random.default_rng(987654321)
    HARD = min(budget_seconds * 0.85, budget_seconds - 0.8)

    def elapsed():
        return time.process_time() - t0

    best = None
    best_score = -1.0

    def score(x):
        return float(np.sum(x[:, 2]))

    if start is not None:
        try:
            s = _feasible_fix(start, n)
            best = s
            best_score = score(s)
        except Exception:
            pass

    def hex_init(rows, cols):
        pts = []
        for j in range(rows):
            y = (j + 0.5) / rows
            off = 0.5 if j % 2 == 0 else 1.0
            cnt = cols if j % 2 == 0 else cols - 1
            for i in range(cnt):
                x = (i + off) / cols
                pts.append((x, y))
        return pts

    def grid_init(g):
        pts = []
        for j in range(g):
            for i in range(g):
                pts.append(((i + 0.5) / g, (j + 0.5) / g))
        return pts

    def make_cand(centers):
        rlp = _lp_radii(centers, n)
        if rlp is None:
            rlp = np.full(n, 0.05)
        c = np.column_stack([centers, rlp])
        return _feasible_fix(c, n)

    def consider(cand):
        nonlocal best, best_score
        cand = _feasible_fix(cand, n)
        sc = score(cand)
        if sc > best_score:
            best_score = sc
            best = cand
            return True
        return False

    # Polish start
    if best is not None and elapsed() < HARD:
        pol = _slsqp_polish(best, n, maxiter=4000, ftol=1e-16)
        pol = _feasible_fix(pol, n)
        if score(pol) > best_score:
            best_score = score(pol)
            best = pol

    # --- Screening phase: random center sets with LP radii ---
    screen_deadline = 0.45 * budget_seconds
    M = 300
    screened = []
    min_sep = 0.04
    for _ in range(M):
        if elapsed() > screen_deadline:
            break
        centers = None
        for _try in range(50):
            cand = rng.uniform(0.03, 0.97, size=(n, 2))
            # check min pairwise distance
            ok = True
            for i in range(n):
                for j in range(i + 1, n):
                    dx = cand[i, 0] - cand[j, 0]
                    dy = cand[i, 1] - cand[j, 1]
                    if dx * dx + dy * dy < min_sep * min_sep:
                        ok = False
                        break
                if not ok:
                    break
            if ok:
                centers = cand
                break
        if centers is None:
            continue
        rlp = _lp_radii(centers, n)
        if rlp is None:
            continue
        screened.append((float(np.sum(rlp)), centers, rlp))
        if elapsed() > screen_deadline:
            break

    screened.sort(key=lambda t: -t[0])
    top = screened[:5]
    for _, centers, rlp in top:
        if elapsed() > HARD - 0.5:
            break
        try:
            c = np.column_stack([centers, rlp])
            c = _feasible_fix(c, n)
            pol = _slsqp_polish(c, n, maxiter=1500)
            pol = _feasible_fix(pol, n)
            consider(pol)
        except Exception:
            pass

    inits = []
    for rows, cols in [(6, 6), (5, 7), (7, 5), (6, 7), (8, 4), (7, 6)]:
        p = hex_init(rows, cols)
        if len(p) >= n:
            inits.append(np.array(p[:n]))
    for g in (6, 7):
        p = grid_init(g)
        if len(p) >= n:
            inits.append(np.array(p[:n]))

    # Only try fresh inits if we don't already have a strong start
    if best is None or best_score < 2.85:
        for centers in inits:
            if elapsed() > 0.55 * budget_seconds:
                break
            try:
                cand = make_cand(centers)
                consider(cand)
                if elapsed() < 0.55 * budget_seconds:
                    pol = _slsqp_polish(cand, n, maxiter=1500)
                    pol = _feasible_fix(pol, n)
                    consider(pol)
            except Exception:
                pass

    # SLP tangent-space improvement loop (main effort)
    margin = 1.0
    it = 0
    stall = 0
    while best is not None and it < 200 and elapsed() < HARD - margin:
        it += 1
        try:
            v, opt = _slp_step(best, n, delta=5e-3)
        except Exception:
            break
        if v is None or opt < 1e-13:
            cand = best.copy()
            k = rng.integers(1, 4)
            idx = rng.choice(n, size=k, replace=False)
            cand[idx, 0] += rng.normal(0, 0.02, k)
            cand[idx, 1] += rng.normal(0, 0.02, k)
            cand = _feasible_fix(cand, n)
            newc = make_cand(cand[:, :2])
            pol = _slsqp_polish(newc, n, maxiter=1500)
            pol = _feasible_fix(pol, n)
            if consider(pol):
                stall = 0
            else:
                stall += 1
                if stall > 3:
                    break
            continue
        improved = False
        for step in (1.0, 0.5, 0.25):
            try:
                x_new = (best.reshape(-1) + step * v).reshape(n, 3)
                x_new = _feasible_fix(x_new, n)
                pol = _slsqp_polish(x_new, n, maxiter=2500)
                pol = _feasible_fix(pol, n)
                if consider(pol):
                    improved = True
                    break
            except Exception:
                continue
        if not improved:
            stall += 1
            cand = best.copy()
            idx = rng.choice(n, size=rng.integers(1, 4), replace=False)
            cand[idx, 0] += rng.normal(0, 0.015, len(idx))
            cand[idx, 1] += rng.normal(0, 0.015, len(idx))
            cand = _feasible_fix(cand, n)
            newc = make_cand(cand[:, :2])
            pol = _slsqp_polish(newc, n, maxiter=1500)
            pol = _feasible_fix(pol, n)
            if consider(pol):
                stall = 0
            if stall > 5:
                break
        else:
            stall = 0

    if best is None:
        if start is not None:
            return _feasible_fix(start, n)
        p = hex_init(6, 6)
        return make_cand(np.array(p[:n]))

    try:
        centers = best[:, :2].copy()
        r = _lp_radii(centers, n)
        if r is not None:
            cand = np.column_stack([centers, r])
            cand = _feasible_fix(cand, n)
            if score(cand) > best_score:
                best = cand
                best_score = score(cand)
    except Exception:
        pass

    best = _feasible_fix(best, n)
    return best
